css:
@keyframes dbo-topology-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
@keyframes dbo-topology-flow { to { stroke-dashoffset: -14; } }
@keyframes dbo-topology-pop { from { opacity: 0; scale: 0.6; } }
@keyframes dbo-topology-fade { from { opacity: 0; } }
@keyframes dbo-topology-rise { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbo-topology-pulse { 0%, 100% { opacity: 0.9; scale: 1; } 50% { opacity: 0.15; scale: 1.9; } }

.dbo-topology {
  /* re-theme with these five */
  --dbo-topology-bg: oklch(0.2 0.018 170);
  --dbo-topology-ink: oklch(0.95 0.012 160);
  --dbo-topology-accent: oklch(0.86 0.13 166);
  --dbo-topology-warn: oklch(0.84 0.14 84);
  --dbo-topology-bad: oklch(0.7 0.18 29);
  /* derived */
  --dbo-topology-panel: color-mix(in oklch, var(--dbo-topology-bg), white 4%);
  --dbo-topology-raise: color-mix(in oklch, var(--dbo-topology-bg), white 8%);
  --dbo-topology-sink: color-mix(in oklch, var(--dbo-topology-bg), black 22%);
  --dbo-topology-line: color-mix(in oklch, var(--dbo-topology-ink) 11%, transparent);
  --dbo-topology-line-2: color-mix(in oklch, var(--dbo-topology-ink) 20%, transparent);
  --dbo-topology-muted: color-mix(in oklch, var(--dbo-topology-ink) 62%, var(--dbo-topology-bg));
  --dbo-topology-faint: color-mix(in oklch, var(--dbo-topology-ink) 38%, var(--dbo-topology-bg));
  --dbo-topology-ease: cubic-bezier(0.2, 0.9, 0.2, 1);
  --dbo-topology-spring: linear(0, 0.38 9%, 0.78 20%, 1.02 32%, 1.08 40%, 1.04 52%, 0.99 66%, 1);
  --dbo-topology-mono: ui-monospace, "SF Mono", Menlo, monospace;

  width: 100%;
  height: var(--dbo-topology-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-topology-bg);
  color: var(--dbo-topology-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbo-topology-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-topology-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-topology-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbo-topology-eyebrow { font: 600 10.5px/1.2 var(--dbo-topology-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-topology-faint); }

  .dbo-topology-app {
    display: grid; height: 100%;
    grid-template-columns: minmax(0, 1fr) 304px;
    grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-areas: "top top" "filters insp" "main insp";
  }

  /* ---------- header ---------- */
  .dbo-topology-top {
    grid-area: top; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
    padding: 12px 16px; border-bottom: 1px solid var(--dbo-topology-line);
  }
  .dbo-topology-brand { display: flex; align-items: center; gap: 10px; margin-right: 6px; }
  .dbo-topology-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; fill: var(--dbo-topology-bg); stroke: var(--dbo-topology-bg); stroke-width: 1.7; stroke-linecap: round; background: var(--dbo-topology-accent); }
  .dbo-topology-brand span { display: grid; line-height: 1.15; }
  .dbo-topology-brand b { font-weight: 700; letter-spacing: -0.015em; font-size: 14px; }
  .dbo-topology-brand small { font: 11px var(--dbo-topology-mono); color: var(--dbo-topology-muted); }

  .dbo-topology-tabs { display: flex; gap: 2px; }
  .dbo-topology-tabs button {
    position: relative; display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 12px; border-radius: 8px;
    font-weight: 600; color: var(--dbo-topology-muted); transition: color 160ms, background-color 160ms;
  }
  .dbo-topology-tabs svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  .dbo-topology-tabs button:hover { color: var(--dbo-topology-ink); background: color-mix(in oklch, var(--dbo-topology-ink) 5%, transparent); }
  .dbo-topology-tabs button[aria-selected="true"] { color: var(--dbo-topology-ink); background: var(--dbo-topology-raise); }
  .dbo-topology-tabs button[aria-selected="true"]::after { content: ""; position: absolute; left: 12px; right: 12px; bottom: -13px; height: 2px; border-radius: 2px; background: var(--dbo-topology-accent); }

  .dbo-topology-tools { display: flex; flex-wrap: wrap; gap: 8px; margin-left: auto; }
  .dbo-topology-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: var(--dbo-topology-sink); box-shadow: inset 0 0 0 1px var(--dbo-topology-line); }
  .dbo-topology-seg button { height: 26px; padding: 0 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbo-topology-muted); font-variant-numeric: tabular-nums; transition: color 150ms, background-color 150ms; }
  .dbo-topology-seg button:hover { color: var(--dbo-topology-ink); }
  .dbo-topology-seg button[aria-checked="true"] { color: var(--dbo-topology-bg); background: var(--dbo-topology-accent); }

  /* ---------- filters ---------- */
  .dbo-topology-filters { grid-area: filters; display: flex; align-items: center; gap: 6px; padding: 10px 16px 6px; overflow-x: auto; scrollbar-width: none; }
  .dbo-topology-filters .dbo-topology-eyebrow { margin-right: 4px; flex: none; }
  .dbo-topology-when { margin-left: auto; padding-left: 12px; flex: none; font: 500 11px var(--dbo-topology-mono); color: var(--dbo-topology-faint); font-variant-numeric: tabular-nums; }
  .dbo-topology-live { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); margin: 0; }
  .dbo-topology-chip {
    flex: none; display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 99px;
    font: 500 12px var(--dbo-topology-mono); color: var(--dbo-topology-muted);
    box-shadow: inset 0 0 0 1px var(--dbo-topology-line); transition: color 150ms, box-shadow 150ms, background-color 150ms;
  }
  .dbo-topology-chip i { width: 6px; height: 6px; border-radius: 50%; background: var(--dbo-topology-faint); }
  .dbo-topology-chip:hover { color: var(--dbo-topology-ink); box-shadow: inset 0 0 0 1px var(--dbo-topology-line-2); }
  .dbo-topology-chip[aria-pressed="true"] { color: var(--dbo-topology-ink); background: color-mix(in oklch, var(--dbo-topology-accent) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-topology-accent) 50%, transparent); }
  .dbo-topology-chip[aria-pressed="true"] i { background: var(--dbo-topology-accent); }

  /* ---------- main ---------- */
  .dbo-topology-main { grid-area: main; min-height: 0; display: grid; padding: 4px 12px 12px 16px; }
  .dbo-topology-view { min-height: 0; display: grid; }
  .dbo-topology-map {
    position: relative; min-height: 0; border-radius: 12px; overflow: hidden;
    background:
      radial-gradient(circle at 1px 1px, color-mix(in oklch, var(--dbo-topology-ink) 9%, transparent) 1px, transparent 0) 0 0 / 18px 18px,
      var(--dbo-topology-sink);
    box-shadow: inset 0 0 0 1px var(--dbo-topology-line);
  }
  .dbo-topology-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; outline: none; }

  .dbo-topology-tier { font: 600 9.5px var(--dbo-topology-mono); letter-spacing: 0.1em; text-transform: uppercase; fill: var(--dbo-topology-faint); }
  .dbo-topology-tierline { stroke: var(--dbo-topology-line); stroke-dasharray: 2 5; }

  /* edges */
  .dbo-topology-edge { transition: opacity 220ms var(--dbo-topology-ease); }
  .dbo-topology-ebase {
    fill: none; stroke: color-mix(in oklch, var(--dbo-topology-ink) 22%, transparent); stroke-linecap: round;
    stroke-dasharray: 1; stroke-dashoffset: 1;
    animation: dbo-topology-draw 900ms var(--dbo-topology-ease) forwards; animation-delay: calc(var(--t) * 140ms + 120ms);
    transition: stroke 260ms, stroke-width 420ms var(--dbo-topology-ease);
  }
  .dbo-topology-eflow {
    fill: none; stroke: var(--dbo-topology-accent); stroke-linecap: round; stroke-dasharray: 0.1 13.9; pointer-events: none;
    animation: dbo-topology-fade 600ms both, dbo-topology-flow var(--dur, 2s) linear infinite;
    animation-delay: calc(var(--t) * 140ms + 900ms), 0ms;
    transition: stroke 260ms;
  }
  .dbo-topology-ehit { fill: none; stroke: transparent; stroke-width: 12; pointer-events: stroke; cursor: help; }
  .dbo-topology-edge[data-s="warn"] .dbo-topology-ebase { stroke: color-mix(in oklch, var(--dbo-topology-warn) 55%, transparent); }
  .dbo-topology-edge[data-s="warn"] .dbo-topology-eflow { stroke: var(--dbo-topology-warn); }
  .dbo-topology-edge[data-s="bad"] .dbo-topology-ebase { stroke: color-mix(in oklch, var(--dbo-topology-bad) 60%, transparent); }
  .dbo-topology-edge[data-s="bad"] .dbo-topology-eflow { stroke: var(--dbo-topology-bad); stroke-dasharray: 0.1 5.9 0.1 7.9; }
  .dbo-topology-edge:hover .dbo-topology-ebase, .dbo-topology-edge[data-lit] .dbo-topology-ebase { stroke: color-mix(in oklch, var(--dbo-topology-ink) 55%, transparent); }
  .dbo-topology-edge[data-s="bad"][data-lit] .dbo-topology-ebase { stroke: var(--dbo-topology-bad); }
  &[data-paused] .dbo-topology-eflow { animation-play-state: paused; }
  &[data-settled] {
    .dbo-topology-ebase { animation: none; stroke-dashoffset: 0; }
    .dbo-topology-eflow { animation: dbo-topology-flow var(--dur, 2s) linear infinite; }
    .dbo-topology-nbody { animation: none; }
  }
  &[data-settled][data-paused] .dbo-topology-eflow { animation-play-state: paused; }

  /* nodes */
  .dbo-topology-node { cursor: pointer; outline: none; transition: opacity 220ms var(--dbo-topology-ease); }
  .dbo-topology-nbody {
    transform-box: fill-box; transform-origin: center;
    animation: dbo-topology-pop 640ms var(--dbo-topology-spring) both; animation-delay: calc(var(--t) * 140ms + var(--i) * 24ms);
  }
  .dbo-topology-disc { fill: var(--dbo-topology-panel); stroke: var(--dbo-topology-line-2); stroke-width: 1; transition: fill 160ms, stroke 160ms; }
  .dbo-topology-node:hover .dbo-topology-disc { fill: var(--dbo-topology-raise); stroke: color-mix(in oklch, var(--dbo-topology-ink) 40%, transparent); }
  .dbo-topology-node[aria-pressed="true"] .dbo-topology-disc { fill: color-mix(in oklch, var(--sc) 22%, var(--dbo-topology-panel)); stroke: var(--sc); stroke-width: 1.5; }
  .dbo-topology-foc { fill: none; stroke: var(--dbo-topology-accent); stroke-width: 1.5; stroke-dasharray: 3 3; opacity: 0; }
  .dbo-topology-node:focus-visible .dbo-topology-foc { opacity: 1; }
  .dbo-topology-rbg { fill: none; stroke: color-mix(in oklch, var(--dbo-topology-ink) 10%, transparent); stroke-width: 3; }
  .dbo-topology-ring {
    fill: none; stroke: var(--sc); stroke-width: 3; stroke-linecap: round;
    stroke-dasharray: calc(var(--v, 0) * 1px) 100px; rotate: -90deg; transform-box: fill-box; transform-origin: center;
    transition: stroke-dasharray 760ms var(--dbo-topology-ease), stroke 260ms;
  }
  .dbo-topology-ico { fill: none; stroke: var(--dbo-topology-muted); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; transition: stroke 160ms; }
  .dbo-topology-ico * { vector-effect: non-scaling-stroke; }
  .dbo-topology-node:hover .dbo-topology-ico, .dbo-topology-node[aria-pressed="true"] .dbo-topology-ico { stroke: var(--dbo-topology-ink); }
  .dbo-topology-halo { fill: var(--dbo-topology-bad); transform-box: fill-box; transform-origin: center; opacity: 0; }
  .dbo-topology-node[data-s="bad"] .dbo-topology-halo { animation: dbo-topology-pulse 2s var(--dbo-topology-ease) infinite; }
  &[data-paused] .dbo-topology-halo { animation-play-state: paused; }
  .dbo-topology-node[data-s="ok"] { --sc: var(--dbo-topology-accent); }
  .dbo-topology-node[data-s="warn"] { --sc: var(--dbo-topology-warn); }
  .dbo-topology-node[data-s="bad"] { --sc: var(--dbo-topology-bad); }
  .dbo-topology-name, .dbo-topology-meta { text-anchor: middle; paint-order: stroke; stroke: var(--dbo-topology-sink); stroke-width: 4px; stroke-linejoin: round; }
  .dbo-topology-name { font: 600 11.5px var(--dbo-topology-mono); letter-spacing: -0.02em; fill: var(--dbo-topology-ink); }
  .dbo-topology-meta { font: 500 10px var(--dbo-topology-mono); fill: var(--dbo-topology-muted); font-variant-numeric: tabular-nums; }
  .dbo-topology-node[data-s="bad"] .dbo-topology-meta { fill: color-mix(in oklch, var(--dbo-topology-bad) 75%, var(--dbo-topology-ink)); }
  .dbo-topology-node[data-s="warn"] .dbo-topology-meta { fill: color-mix(in oklch, var(--dbo-topology-warn) 70%, var(--dbo-topology-ink)); }

  /* compact (narrow map): tiers run top to bottom, labels only */
  .dbo-topology-svg[data-compact] {
    .dbo-topology-meta, .dbo-topology-tier { display: none; }
    .dbo-topology-name { font-size: 9.5px; letter-spacing: -0.03em; }
  }

  /* focus + filter dimming, driven from the map's own state with :has() */
  .dbo-topology-map:has([data-lit]) {
    .dbo-topology-node:not([data-lit]), .dbo-topology-edge:not([data-lit]) { opacity: 0.16; }
  }
  .dbo-topology-node[data-out], .dbo-topology-edge[data-out] { opacity: 0.14; }

  /* legend */
  .dbo-topology-legend {
    position: absolute; left: 10px; bottom: 10px; display: flex; flex-wrap: wrap; gap: 4px 14px; align-items: center;
    padding: 6px 10px; border-radius: 8px; background: color-mix(in oklch, var(--dbo-topology-sink) 82%, transparent);
    font: 500 10.5px var(--dbo-topology-mono); color: var(--dbo-topology-muted); pointer-events: none;
    box-shadow: inset 0 0 0 1px var(--dbo-topology-line);
  }
  .dbo-topology-legend span { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-topology-legend em { font-style: normal; }
  .dbo-topology-legend i { width: 8px; height: 8px; border-radius: 50%; }
  .dbo-topology-legend i[data-s="ok"] { background: var(--dbo-topology-accent); }
  .dbo-topology-legend i[data-s="warn"] { background: var(--dbo-topology-warn); }
  .dbo-topology-legend i[data-s="bad"] { background: var(--dbo-topology-bad); }
  .dbo-topology-legend svg { width: 28px; height: 10px; }
  .dbo-topology-legend path { stroke: var(--dbo-topology-muted); stroke-linecap: round; }
  .dbo-topology-legend path:first-child { stroke-width: 3.5; }
  .dbo-topology-legend path:last-child { stroke-width: 1.2; }

  /* tooltip */
  .dbo-topology-tip {
    position: absolute; left: 0; top: 0; z-index: 5; min-width: 196px; padding: 10px 12px; border-radius: 10px; pointer-events: none;
    background: color-mix(in oklch, var(--dbo-topology-bg), black 40%);
    box-shadow: 0 0 0 1px var(--dbo-topology-line-2), 0 14px 32px oklch(0 0 0 / 0.5);
    font: 11.5px/1.5 var(--dbo-topology-mono); font-variant-numeric: tabular-nums;
    opacity: 0; scale: 0.96; transform-origin: 0 0;
    transition: opacity 120ms, scale 180ms var(--dbo-topology-ease);
  }
  .dbo-topology-tip[data-on] { opacity: 1; scale: 1; }
  .dbo-topology-tip header { font: 650 12px system-ui, sans-serif; margin-bottom: 6px; display: flex; gap: 8px; align-items: center; }
  .dbo-topology-tip header small { font: 500 10.5px var(--dbo-topology-mono); color: var(--dbo-topology-muted); margin-left: auto; }
  .dbo-topology-tip div { display: flex; justify-content: space-between; gap: 18px; color: var(--dbo-topology-muted); }
  .dbo-topology-tip div b { color: var(--dbo-topology-ink); font-weight: 600; }
  .dbo-topology-tip [data-s="bad"] b { color: var(--dbo-topology-bad); }
  .dbo-topology-tip [data-s="warn"] b { color: var(--dbo-topology-warn); }

  /* ---------- table ---------- */
  .dbo-topology-tablewrap {
    min-height: 0; overflow: auto; border-radius: 12px; background: var(--dbo-topology-panel); box-shadow: inset 0 0 0 1px var(--dbo-topology-line);
    scrollbar-width: thin; scrollbar-color: var(--dbo-topology-line-2) transparent;
  }
  .dbo-topology-table { width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
  .dbo-topology-table th {
    position: sticky; top: 0; z-index: 1; padding: 0; text-align: left; background: var(--dbo-topology-panel);
    border-bottom: 1px solid var(--dbo-topology-line-2);
  }
  .dbo-topology-table th button {
    width: 100%; display: flex; align-items: center; gap: 5px; padding: 10px 12px;
    font: 600 10.5px var(--dbo-topology-mono); letter-spacing: 0.06em; text-transform: uppercase; color: var(--dbo-topology-muted);
  }
  .dbo-topology-table th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; opacity: 0; transition: opacity 150ms; }
  .dbo-topology-table th[aria-sort="ascending"] button::after { border-bottom-color: currentColor; translate: 0 -2px; opacity: 1; }
  .dbo-topology-table th[aria-sort="descending"] button::after { border-top-color: currentColor; translate: 0 2px; opacity: 1; }
  .dbo-topology-table th[aria-sort$="ending"] button { color: var(--dbo-topology-ink); }
  .dbo-topology-table th button:hover { color: var(--dbo-topology-ink); }
  .dbo-topology-num { text-align: right; }
  .dbo-topology-table th.dbo-topology-num button { justify-content: flex-end; }
  .dbo-topology-table td { padding: 9px 12px; border-bottom: 1px solid var(--dbo-topology-line); white-space: nowrap; }
  .dbo-topology-table td.dbo-topology-num { font: 500 12px var(--dbo-topology-mono); }
  .dbo-topology-table tbody tr { cursor: pointer; outline: none; transition: background-color 140ms; }
  .dbo-topology-tablewrap[data-enter] tbody tr { animation: dbo-topology-rise 420ms var(--dbo-topology-ease) both; animation-delay: calc(var(--i) * 22ms); }
  .dbo-topology-table tbody tr:hover { background: color-mix(in oklch, var(--dbo-topology-ink) 4%, transparent); }
  .dbo-topology-table tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dbo-topology-accent) 11%, transparent); }
  .dbo-topology-table tbody tr:focus-visible { box-shadow: inset 2px 0 0 var(--dbo-topology-accent); background: color-mix(in oklch, var(--dbo-topology-ink) 5%, transparent); }
  .dbo-topology-svc { display: flex; align-items: center; gap: 8px; font: 600 12.5px var(--dbo-topology-mono); }
  .dbo-topology-svc i { width: 8px; height: 8px; border-radius: 50%; background: var(--sc); flex: none; }
  .dbo-topology-table tr[data-s="ok"] { --sc: var(--dbo-topology-accent); }
  .dbo-topology-table tr[data-s="warn"] { --sc: var(--dbo-topology-warn); }
  .dbo-topology-table tr[data-s="bad"] { --sc: var(--dbo-topology-bad); }
  .dbo-topology-nscell { font: 11.5px var(--dbo-topology-mono); color: var(--dbo-topology-muted); }
  .dbo-topology-bar { display: inline-grid; grid-template-columns: 54px auto; align-items: center; gap: 8px; }
  .dbo-topology-bar s { height: 4px; border-radius: 2px; background: color-mix(in oklch, var(--dbo-topology-ink) 10%, transparent); overflow: hidden; text-decoration: none; }
  .dbo-topology-bar s::before { content: ""; display: block; height: 100%; width: calc(var(--w) * 100%); background: var(--dbo-topology-accent); border-radius: inherit; }
  .dbo-topology-table [data-hot] { color: var(--dbo-topology-bad); }
  .dbo-topology-table [data-warm] { color: var(--dbo-topology-warn); }

  /* ---------- inspector ---------- */
  .dbo-topology-insp {
    grid-area: insp; min-height: 0; overflow: auto; padding: 12px 16px 16px 4px;
    scrollbar-width: thin; scrollbar-color: var(--dbo-topology-line-2) transparent;
  }
  .dbo-topology-ihead { display: grid; gap: 6px; padding: 4px 2px 12px; }
  .dbo-topology-ihead h3 { font: 650 clamp(17px, 0.9rem + 0.5cqi, 21px)/1.15 var(--dbo-topology-mono); letter-spacing: -0.03em; }
  .dbo-topology-ihead p { color: var(--dbo-topology-muted); font-size: 12px; }
  .dbo-topology-pills { display: flex; flex-wrap: wrap; gap: 5px; }
  .dbo-topology-pill { display: inline-flex; align-items: center; gap: 5px; height: 21px; padding: 0 8px; border-radius: 99px; font: 600 10.5px var(--dbo-topology-mono); background: color-mix(in oklch, var(--dbo-topology-ink) 7%, transparent); color: var(--dbo-topology-muted); }
  .dbo-topology-pill[data-s] { color: var(--sc); background: color-mix(in oklch, var(--sc) 14%, transparent); }
  .dbo-topology-pill[data-s="ok"] { --sc: var(--dbo-topology-accent); }
