let W = 0, H = 0, R = 19, compact = false;
function layout() {
  W = mapEl.clientWidth; H = mapEl.clientHeight;
  if (!W || !H) return;
  compact = W < 600;
  svg.toggleAttribute('data-compact', compact);
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const tiers = [0, 1, 2, 3, 4].map(t => NODES.filter(n => n.tier === t));
  // the busiest tier sets the node size, so ring + two label lines always fit their slot
  R = compact ? 12 : (H - 98) / Math.max(...tiers.map(l => l.length)) < 86 ? 17 : 19;
  if (!compact) {
    const pad = Math.min(72, W * 0.08), top = 46, bot = 52, colW = (W - pad * 2) / 4;
    tiers.forEach((list, t) => {
      const x = pad + colW * t, slot = (H - top - bot) / list.length;
      list.forEach((n, k) => { n.cx = x; n.cy = top + slot * (k + 0.5); });
      set(gT.children[t], { x, y: 24, 'text-anchor': 'middle' });
    });
  } else {
    const padX = 24, top = 30, bot = 92, rowH = (H - top - bot) / 4;
    tiers.forEach((list, t) => {
      const y = top + rowH * t, slot = (W - padX * 2) / list.length;
      list.forEach((n, k) => { n.cx = padX + slot * (k + 0.5); n.cy = y; n.alt = list.length > 4 && k % 2 === 1; });
    });
  }
  NODES.forEach(n => {
    n.g.setAttribute('transform', `translate(${n.cx.toFixed(1)} ${n.cy.toFixed(1)})`);
    set(n.halo, { r: R }); set(n.foc, { r: R + 9 }); set(n.rbg, { r: R + 4.5 }); set(n.ring, { r: R + 4.5 }); set(n.disc, { r: R });
    const s = compact ? 0.5 : 0.75;
    n.ico.setAttribute('transform', `translate(${-12 * s} ${-12 * s}) scale(${s})`);
    if (compact) { set(n.nameEl, { x: 0, y: n.alt ? -(R + 10) : R + 17 }); }
    else { set(n.nameEl, { x: 0, y: R + 20 }); set(n.metaEl, { x: 0, y: R + 34 }); }
  });
  // fan edges out around the circle so they do not all leave from one point
  NODES.forEach(n => {
    const outs = [...n.out].sort((p, q) => compact ? byId[p.b].cx - byId[q.b].cx : byId[p.b].cy - byId[q.b].cy);
    const ins = [...n.in].sort((p, q) => compact ? byId[p.a].cx - byId[q.a].cx : byId[p.a].cy - byId[q.a].cy);
    const spread = (list, key) => list.forEach((e, k) => { e[key] = list.length < 2 ? 0 : (k / (list.length - 1) - 0.5) * Math.min(1.1, 0.2 * list.length); });
    spread(outs, 'ao'); spread(ins, 'ai');
  });
  EDGES.forEach(ed => {
    const a = byId[ed.a], b = byId[ed.b], r = R + 6;
    let d;
    if (!compact) {
      const x1 = a.cx + r * Math.cos(ed.ao), y1 = a.cy + r * Math.sin(ed.ao), x2 = b.cx - r * Math.cos(ed.ai), y2 = b.cy + r * Math.sin(ed.ai);
      const dx = Math.max(24, (x2 - x1) * 0.5);
      d = `M${x1.toFixed(1)} ${y1.toFixed(1)}C${(x1 + dx).toFixed(1)} ${y1.toFixed(1)} ${(x2 - dx).toFixed(1)} ${y2.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`;
    } else {
      const x1 = a.cx - r * Math.sin(ed.ao), y1 = a.cy + r * Math.cos(ed.ao), x2 = b.cx - r * Math.sin(ed.ai), y2 = b.cy - r * Math.cos(ed.ai);
      const dy = Math.max(18, (y2 - y1) * 0.5);
      d = `M${x1.toFixed(1)} ${y1.toFixed(1)}C${x1.toFixed(1)} ${(y1 + dy).toFixed(1)} ${x2.toFixed(1)} ${(y2 - dy).toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`;
    }
    ed.base.setAttribute('d', d); ed.flow.setAttribute('d', d); ed.hit.setAttribute('d', d);
  });
}

/* ---------- paint data onto the map, table and inspector ---------- */
function paintMap() {
