    n.g.setAttribute('aria-label', `${n.name}: ${fRpsFull(a.rps)} requests per second, ${fPct(a.err)} errors, p95 ${fMs(a.p95)}, ${s === 'ok' ? 'healthy' : s === 'warn' ? 'degraded' : 'critical'}`);
    n.g.toggleAttribute('data-out', st.ns !== 'all' && n.ns !== st.ns);
