function hood(id) {
  const nodes = new Set([id]), edges = new Set();
  const walk = (start, dir) => {
    const seen = new Set([start]), q = [start];
    while (q.length) {
      const x = q.pop();
      (dir ? byId[x].out : byId[x].in).forEach(e => { edges.add(e.id); const nx = dir ? e.b : e.a; nodes.add(nx); if (!seen.has(nx)) { seen.add(nx); q.push(nx); } });
    }
  };
  walk(id, 0); walk(id, 1);
