  const h = focus && focus.includes('>') ? { nodes: new Set(focus.split('>')), edges: new Set([focus]) } : focus ? hood(focus) : null;
  NODES.forEach(n => n.g.toggleAttribute('data-lit', !!h && h.nodes.has(n.id)));
  EDGES.forEach(e => e.g.toggleAttribute('data-lit', !!h && h.edges.has(e.id)));
