  rowEls.forEach(r => { if (!list.some(n => n.id === r.dataset.id)) r.remove(); });
  list.forEach((n, i) => { const r = rowEls.get(n.id); r.style.setProperty('--i', i); tbody.appendChild(r); });
  const cur = list.find(n => n.id === st.cur) || list[0];
  list.forEach(n => { rowEls.get(n.id).tabIndex = n === cur ? 0 : -1; });
  $$('th', table).forEach(th => { const b = $('button', th); th.setAttribute('aria-sort', b.dataset.k === k ? (dir > 0 ? 'ascending' : 'descending') : 'none'); });
  if (first) list.forEach(n => {
    const r = rowEls.get(n.id), f = first.get(n.id); if (f == null) return;
    const dy = f - r.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) r.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.2,.9,.2,1)' });
  });
}
$('thead', table).addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  const k = b.dataset.k;
  st.sort = { k, dir: st.sort.k === k ? -st.sort.dir : (k === 'name' || k === 'ns' ? 1 : -1) };
  paintTable(true);
});
tbody.addEventListener('click', e => { const r = e.target.closest('tr'); if (r) { st.cur = r.dataset.id; select(st.sel === r.dataset.id ? null : r.dataset.id); } });
tbody.addEventListener('keydown', e => {
  const r = e.target.closest('tr'); if (!r) return;
  const rows = $$('tr', tbody), i = rows.indexOf(r);
  let j = -1;
  if (e.key === 'ArrowDown') j = Math.min(rows.length - 1, i + 1);
  else if (e.key === 'ArrowUp') j = Math.max(0, i - 1);
  else if (e.key === 'Home') j = 0;
  else if (e.key === 'End') j = rows.length - 1;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(st.sel === r.dataset.id ? null : r.dataset.id); return; }
  else if (e.key === 'Escape') { select(null); return; }
  if (j < 0) return;
  e.preventDefault();
