  rows[j].focus(); st.cur = rows[j].dataset.id;
});

/* ---------- controls ---------- */
function radio(group, onPick) {
  const btns = $$(`[data-group="${group}"] button`);
  const pick = (b, focus) => {
    btns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
    if (focus) b.focus();
    onPick(b.dataset.v);
  };
  btns.forEach((b, i) => {
    b.addEventListener('click', () => pick(b));
    b.addEventListener('keydown', e => {
      const dirn = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
      if (!dirn) return;
      e.preventDefault(); pick(btns[(i + dirn + btns.length) % btns.length], true);
    });
  });
}
const repaint = () => { paintMap(); paintTable(false); renderInsp(false); };
radio('range', v => { st.range = v; repaint(); });
radio('mode', v => { st.mode = v; repaint(); });

$('.dbo-topology-filters').addEventListener('click', e => {
  const b = e.target.closest('.dbo-topology-chip'); if (!b) return;
  st.ns = b.dataset.ns;
  $$('.dbo-topology-chip').forEach(c => c.setAttribute('aria-pressed', String(c === b)));
  if (st.sel && st.ns !== 'all' && byId[st.sel].ns !== st.ns) st.sel = null;
  paintMap(); paintTable(true); renderInsp(true);
});

const tabs = $$('[role="tab"]');
function showView(v, focus) {
  st.view = v;
  tabs.forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
