  if (v === 'map') requestAnimationFrame(() => { if (!root.isConnected) return; layout(); });
  else { const tw = $('.dbo-topology-tablewrap'); tw.setAttribute('data-enter', ''); setTimeout(() => tw.removeAttribute('data-enter'), 900); }
}
tabs.forEach((t, i) => {
  t.addEventListener('click', () => showView(t.dataset.view));
  t.addEventListener('keydown', e => {
    if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
    e.preventDefault(); showView(tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length].dataset.view, true);
  });
});

/* ---------- lifecycle ---------- */
layout(); paintMap(); paintTable(false); renderInsp(true);
let lastInspW = insp.clientWidth;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  layout();
  if (Math.abs(insp.clientWidth - lastInspW) > 2) { lastInspW = insp.clientWidth; sparks(); }
});
ro.observe(mapEl); ro.observe(insp);
// entry animations play once; after that, re-showing the map only resumes the flow
setTimeout(() => { if (root.isConnected) root.setAttribute('data-settled', ''); }, 2600);
// the flowing dashes are pure CSS; pause them whenever the map is scrolled out of view
const io = new IntersectionObserver(es => {
  if (!root.isConnected) { io.disconnect(); return; }
  root.toggleAttribute('data-paused', !es[0].isIntersecting);
});
io.observe(root);

css:
@keyframes dbo-budget-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbo-budget-reveal { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbo-budget-grow { from { transform: scaleY(0); } }
@keyframes dbo-budget-fade { from { opacity: 0; } }
@keyframes dbo-budget-beat { 0%, 100% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--dbo-budget-burn) 45%, transparent); } 60% { box-shadow: 0 0 0 5px transparent; } }
@property --dbo-budget-fill { syntax: "<number>"; inherits: true; initial-value: 0; }

.dbo-budget {
  /* re-theme with these five */
  --dbo-budget-bg: oklch(0.972 0.009 85);
  --dbo-budget-ink: oklch(0.25 0.02 55);
  --dbo-budget-accent: oklch(0.52 0.095 168);
  --dbo-budget-burn: oklch(0.6 0.185 34);
  --dbo-budget-warn: oklch(0.73 0.135 72);
  /* derived */
  --dbo-budget-card: color-mix(in oklch, var(--dbo-budget-bg), white 70%);
  --dbo-budget-side-bg: color-mix(in oklch, var(--dbo-budget-bg), var(--dbo-budget-ink) 4%);
  --dbo-budget-line: color-mix(in oklch, var(--dbo-budget-ink) 11%, transparent);
  --dbo-budget-line-2: color-mix(in oklch, var(--dbo-budget-ink) 20%, transparent);
  --dbo-budget-muted: color-mix(in oklch, var(--dbo-budget-ink) 64%, var(--dbo-budget-bg));
  --dbo-budget-faint: color-mix(in oklch, var(--dbo-budget-ink) 42%, var(--dbo-budget-bg));
  --dbo-budget-orange: color-mix(in oklch, var(--dbo-budget-burn) 60%, var(--dbo-budget-warn));
  --dbo-budget-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbo-budget-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --dbo-budget-serif: ui-serif, "New York", "Iowan Old Style", Georgia, serif;

  width: 100%;
  height: var(--dbo-budget-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-budget-bg);
  color: var(--dbo-budget-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: light;
  accent-color: var(--dbo-budget-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-budget-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-budget-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }

  .dbo-budget-eyebrow { font: 600 10.5px/1.2 var(--dbo-budget-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-budget-faint); }

  .dbo-budget-app {
    display: grid; height: 100%;
    grid-template-columns: 246px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side top" "side main";
  }

  /* ---------- side ---------- */
  .dbo-budget-side {
    grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px;
    padding: 18px 12px 14px; background: var(--dbo-budget-side-bg); border-right: 1px solid var(--dbo-budget-line);
  }
  .dbo-budget-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 12px; }
  .dbo-budget-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; fill: none; stroke: var(--dbo-budget-bg); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; background: var(--dbo-budget-ink); }
  .dbo-budget-brand span { display: grid; line-height: 1.15; }
  .dbo-budget-brand b { font: 700 15px/1.1 var(--dbo-budget-serif); letter-spacing: -0.01em; }
  .dbo-budget-brand small { font-size: 11px; color: var(--dbo-budget-muted); }
  .dbo-budget-sidehead { padding: 0 8px; }
  .dbo-budget-list { display: grid; gap: 3px; overflow: auto; margin: 0 -4px; padding: 0 4px; scrollbar-width: thin; scrollbar-color: var(--dbo-budget-line-2) transparent; }
  .dbo-budget-item {
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px; align-items: baseline;
    padding: 9px 10px 10px; border-radius: 10px; cursor: pointer; outline: none;
    transition: background-color 160ms var(--dbo-budget-ease), box-shadow 160ms, --dbo-budget-fill 900ms var(--dbo-budget-ease);
    animation: dbo-budget-rise 520ms var(--dbo-budget-ease) both; animation-delay: calc(var(--i) * 55ms);
  }
  .dbo-budget-item:hover { background: color-mix(in oklch, var(--dbo-budget-ink) 5%, transparent); }
  .dbo-budget-item[aria-selected="true"] { background: var(--dbo-budget-card); box-shadow: 0 0 0 1px var(--dbo-budget-line), 0 1px 2px color-mix(in oklch, var(--dbo-budget-ink) 8%, transparent); }
  .dbo-budget-item:focus-visible { box-shadow: 0 0 0 2px var(--dbo-budget-accent); }
  .dbo-budget-item b { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbo-budget-item em { font: 600 12.5px var(--dbo-budget-mono); font-style: normal; font-variant-numeric: tabular-nums; text-align: right; }
  .dbo-budget-item small { font: 11px var(--dbo-budget-mono); color: var(--dbo-budget-muted); display: flex; gap: 6px; align-items: center; }
  .dbo-budget-item[data-s="bad"] em { color: var(--dbo-budget-burn); }
  .dbo-budget-item[data-s="warn"] em { color: color-mix(in oklch, var(--dbo-budget-warn) 70%, var(--dbo-budget-ink)); }
  .dbo-budget-meter { grid-column: 1 / -1; height: 4px; margin-top: 6px; border-radius: 2px; background: color-mix(in oklch, var(--dbo-budget-ink) 9%, transparent); overflow: hidden; }
  .dbo-budget-meter::before {
    content: ""; display: block; height: 100%; border-radius: inherit; width: calc(var(--dbo-budget-fill) * 1%);
    background: var(--c, var(--dbo-budget-accent));
  }
  .dbo-budget-item[data-s="warn"] { --c: var(--dbo-budget-warn); }
  .dbo-budget-item[data-s="bad"] { --c: var(--dbo-budget-burn); }
  .dbo-budget-badge { font: 700 9.5px/1 var(--dbo-budget-mono); letter-spacing: 0.06em; text-transform: uppercase; padding: 3px 5px; border-radius: 4px; color: var(--dbo-budget-card); background: var(--dbo-budget-burn); }
  .dbo-budget-badge[data-sev="ticket"] { background: var(--dbo-budget-orange); }
  .dbo-budget-sidenote { margin-top: auto; padding: 10px 8px 0; border-top: 1px solid var(--dbo-budget-line); font-size: 11.5px; color: var(--dbo-budget-faint); }

  /* ---------- top ---------- */
  .dbo-budget-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 20px; padding: 18px 22px 14px; }
  .dbo-budget-title { display: grid; gap: 4px; min-width: 0; flex: 1 1 340px; }
  .dbo-budget-title h2 { font: 650 clamp(20px, 1rem + 1.1cqi, 28px)/1.1 var(--dbo-budget-serif); letter-spacing: -0.015em; }
  .dbo-budget-title p { color: var(--dbo-budget-muted); max-width: 62ch; }
  .dbo-budget-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 9px; background: color-mix(in oklch, var(--dbo-budget-ink) 6%, transparent); }
  .dbo-budget-seg button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 600; color: var(--dbo-budget-muted); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbo-budget-seg button:hover { color: var(--dbo-budget-ink); }
  .dbo-budget-seg button[aria-checked="true"] { color: var(--dbo-budget-ink); background: var(--dbo-budget-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbo-budget-ink) 14%, transparent), 0 0 0 1px var(--dbo-budget-line); }

  /* ---------- main ---------- */
  .dbo-budget-main {
    grid-area: main; min-height: 0; overflow: auto; padding: 0 22px 20px;
    display: grid; gap: 14px; align-content: start;
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
    grid-template-areas: "stats stats" "chart chart" "pol sim";
    scrollbar-width: thin; scrollbar-color: var(--dbo-budget-line-2) transparent;
  }
  .dbo-budget-panel { min-width: 0; border-radius: 14px; background: var(--dbo-budget-card); box-shadow: 0 0 0 1px var(--dbo-budget-line), 0 1px 2px color-mix(in oklch, var(--dbo-budget-ink) 5%, transparent); }
  .dbo-budget-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; padding: 13px 16px 6px; }
  .dbo-budget-ph h3 { font-size: 13px; font-weight: 650; margin-right: auto; }
  .dbo-budget-ph small { font-size: 11.5px; color: var(--dbo-budget-faint); }

  /* stats */
  .dbo-budget-stats { grid-area: stats; margin: 0; display: grid; grid-template-columns: minmax(0, 1.5fr) repeat(3, minmax(0, 1fr)); border-top: 1px solid var(--dbo-budget-line-2); border-bottom: 1px solid var(--dbo-budget-line); }
  .dbo-budget-stat { padding: 12px 16px 13px 0; display: grid; align-content: start; gap: 2px; animation: dbo-budget-rise 560ms var(--dbo-budget-ease) both; animation-delay: calc(var(--i) * 60ms + 120ms); }
  .dbo-budget-stat + .dbo-budget-stat { padding-left: 16px; border-left: 1px solid var(--dbo-budget-line); }
  .dbo-budget-stat dt { font: 600 10.5px var(--dbo-budget-mono); letter-spacing: 0.07em; text-transform: uppercase; color: var(--dbo-budget-muted); }
  .dbo-budget-stat dd { margin: 0; font: 600 clamp(20px, 0.9rem + 1.1cqi, 26px)/1.15 var(--dbo-budget-mono); letter-spacing: -0.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbo-budget-stat dd small { font-size: 0.55em; letter-spacing: 0; color: var(--dbo-budget-muted); margin-left: 2px; }
  .dbo-budget-stat p { font-size: 11.5px; color: var(--dbo-budget-muted); font-variant-numeric: tabular-nums; }
  .dbo-budget-hero dd { font: 500 clamp(34px, 1.2rem + 3cqi, 52px)/1 var(--dbo-budget-serif); letter-spacing: -0.03em; margin: 2px 0 2px; }
  .dbo-budget-hero dd small { font-size: 0.42em; }
  .dbo-budget-stat[data-s="bad"] dd { color: var(--dbo-budget-burn); }
  .dbo-budget-stat[data-s="warn"] dd { color: color-mix(in oklch, var(--dbo-budget-warn) 65%, var(--dbo-budget-ink)); }
  .dbo-budget-stat[data-s="ok"] dd { color: var(--dbo-budget-accent); }
  .dbo-budget-stat dd[data-tick] { animation: dbo-budget-fade 420ms var(--dbo-budget-ease); }

  /* chart */
  .dbo-budget-chartpanel { grid-area: chart; }
  .dbo-budget-legend { display: flex; gap: 14px; font: 500 11px var(--dbo-budget-mono); color: var(--dbo-budget-muted); }
  .dbo-budget-legend li { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-budget-legend i { width: 16px; height: 0; border-top: 2px solid var(--dbo-budget-accent); }
  .dbo-budget-legend i[data-k="ideal"] { border-top: 1.5px dashed var(--dbo-budget-faint); }
  .dbo-budget-legend i[data-k="proj"] { border-top: 2px dashed var(--dbo-budget-burn); }
  .dbo-budget-legend [data-simonly] { display: none; }
  &:has(.dbo-budget-switch[aria-checked="true"]) .dbo-budget-legend [data-simonly] { display: inline-flex; }
  .dbo-budget-chart { position: relative; height: 318px; margin: 0 8px 8px; cursor: crosshair; touch-action: pan-y; outline: none; }
  .dbo-budget-chart:focus-visible { box-shadow: inset 0 0 0 2px var(--dbo-budget-accent); border-radius: 10px; }
  .dbo-budget-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbo-budget-gl { stroke: var(--dbo-budget-line); }
  .dbo-budget-zero { stroke: var(--dbo-budget-line-2); stroke-width: 1.25; }
  .dbo-budget-ax { font: 10.5px var(--dbo-budget-mono); fill: var(--dbo-budget-faint); font-variant-numeric: tabular-nums; }
  .dbo-budget-ax-strong { fill: var(--dbo-budget-muted); font-weight: 600; }
  .dbo-budget-ideal { fill: none; stroke: var(--dbo-budget-faint); stroke-width: 1.25; stroke-dasharray: 4 4; }
  .dbo-budget-apos { fill: color-mix(in oklch, var(--dbo-budget-accent) 14%, transparent); }
  .dbo-budget-aneg { fill: color-mix(in oklch, var(--dbo-budget-burn) 16%, transparent); }
  .dbo-budget-lpos { fill: none; stroke: var(--dbo-budget-accent); stroke-width: 2; stroke-linejoin: round; }
  .dbo-budget-lneg { fill: none; stroke: var(--dbo-budget-burn); stroke-width: 2; stroke-linejoin: round; }
  .dbo-budget-proj { fill: none; stroke: var(--dbo-budget-burn); stroke-width: 2; stroke-dasharray: 5 4; stroke-linejoin: round; }
  .dbo-budget-future { fill: color-mix(in oklch, var(--dbo-budget-burn) 5%, transparent); }
  .dbo-budget-hatch path { stroke: color-mix(in oklch, var(--dbo-budget-burn) 22%, transparent); stroke-width: 1; }
  .dbo-budget-break { fill: none; stroke: var(--dbo-budget-muted); stroke-width: 1.25; }
  .dbo-budget-now { stroke: var(--dbo-budget-ink); stroke-width: 1; stroke-dasharray: 2 3; opacity: 0.55; }
  .dbo-budget-band { opacity: 0.85; }
  .dbo-budget-band[data-sev="page"] { fill: color-mix(in oklch, var(--dbo-budget-burn) 18%, transparent); }
  .dbo-budget-band[data-sev="ticket"] { fill: color-mix(in oklch, var(--dbo-budget-warn) 26%, transparent); }
  .dbo-budget-bandmark[data-sev="page"] { fill: var(--dbo-budget-burn); }
  .dbo-budget-bandmark[data-sev="ticket"] { fill: var(--dbo-budget-orange); }
  .dbo-budget-th { stroke-dasharray: 3 3; stroke-width: 1; transition: stroke-width 160ms, opacity 160ms; opacity: 0.55; }
  .dbo-budget-th[data-l="1"] { stroke: var(--dbo-budget-warn); }
  .dbo-budget-th[data-l="2"] { stroke: var(--dbo-budget-orange); }
  .dbo-budget-th[data-l="3"] { stroke: var(--dbo-budget-burn); }
  .dbo-budget-th[data-on] { opacity: 1; stroke-width: 1.75; stroke-dasharray: none; }
  .dbo-budget-thl { font: 600 10px var(--dbo-budget-mono); }
  .dbo-budget-thl[data-l="1"] { fill: color-mix(in oklch, var(--dbo-budget-warn) 70%, var(--dbo-budget-ink)); }
  .dbo-budget-thl[data-l="2"] { fill: var(--dbo-budget-orange); }
  .dbo-budget-thl[data-l="3"] { fill: var(--dbo-budget-burn); }
  .dbo-budget-b0 { fill: color-mix(in oklch, var(--dbo-budget-ink) 22%, transparent); }
  .dbo-budget-b1 { fill: var(--dbo-budget-warn); }
  .dbo-budget-b2 { fill: var(--dbo-budget-orange); }
  .dbo-budget-b3 { fill: var(--dbo-budget-burn); }
  .dbo-budget-bsim { opacity: 0.55; }
  .dbo-budget-bars { transform-box: fill-box; transform-origin: 50% 100%; }
  .dbo-budget-svg[data-anim] {
    .dbo-budget-plot { animation: dbo-budget-reveal var(--dur, 1100ms) var(--dbo-budget-ease) both; }
    .dbo-budget-bars { animation: dbo-budget-grow var(--dur, 1100ms) var(--dbo-budget-ease) both; animation-delay: 120ms; }
  }
  .dbo-budget-cross { stroke: var(--dbo-budget-ink); stroke-width: 1; opacity: 0.4; }
  .dbo-budget-dot { fill: var(--dbo-budget-card); stroke-width: 2; }
  .dbo-budget-dot[data-k="a"] { stroke: var(--dbo-budget-accent); }
  .dbo-budget-dot[data-k="a"][data-neg] { stroke: var(--dbo-budget-burn); }
  .dbo-budget-dot[data-k="b"] { stroke: var(--dbo-budget-ink); }

