const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const uid = 'dbo-budget-' + Math.random().toString(36).slice(2, 8);

/* ---------- model ----------
   32 days of 5-minute buckets per objective: total events and bad events, kept as prefix
   sums so any window's burn rate is two subtractions. Budget, burn-down, burn-rate bars,
   alert states and the simulator all read these same arrays. */
const NOW = Date.UTC(2026, 9, 2, 14, 20);
const B5 = 300000, DAYS = 32, N = DAYS * 288;
const POL = [
  { id: 'fast', name: 'Page · fast burn', note: '2% of budget in 1 h', long: 12, short: 1, lw: '1 h', sw: '5 m', th: 14.4, sev: 'page', l: 3 },
  { id: 'slow', name: 'Page · slow burn', note: '5% of budget in 6 h', long: 72, short: 6, lw: '6 h', sw: '30 m', th: 6, sev: 'page', l: 2 },
  { id: 'tick', name: 'Ticket', note: '10% of budget in 3 d', long: 864, short: 72, lw: '3 d', sw: '6 h', th: 1, sev: 'ticket', l: 1 }
];
const mondays = (() => { // the PDF renderer chokes on the Monday 09:00 invoice batch
  const out = [];
  for (let d = 0; d < DAYS; d++) {
    const t = Date.UTC(2026, 9, 2 - d, 9, 0);
    if (new Date(t).getUTCDay() === 1 && t < NOW) out.push({ ago: (NOW - t) / 60000, dur: 40, frac: 0.03 });
  }
  return out;
})();
const SLOS = [
  { id: 'api', name: 'Public API availability', kind: 'Availability', svc: 'api-gateway', target: 0.999, rps: 1800,
    desc: 'Requests at the gateway that return anything other than a 5xx, over all requests.', unit: 'requests', base: 0.0004,
    inc: [{ ago: 9 * 1440 + 190, dur: 48, frac: 0.07 }, { ago: 3 * 1440 + 610, dur: 25, frac: 0.022 }, { ago: 300, dur: 300, frac: 0.0022 }] },
  { id: 'pay', name: 'Invoice payment latency', kind: 'Latency', svc: 'payments-api', target: 0.99, rps: 60,
    desc: 'Card and bank payments on hosted invoices that complete in under 400 ms.', unit: 'payments', base: 0.0081,
    inc: [{ ago: 11 * 1440 + 300, dur: 840, frac: 0.045 }, { ago: 2 * 1440 + 900, dur: 540, frac: 0.12 }] },
  { id: 'hook', name: 'Webhook delivery', kind: 'Freshness', svc: 'event-relay', target: 0.995, rps: 25,
    desc: 'Webhooks acknowledged by the customer endpoint within 60 seconds of the event.', unit: 'deliveries', base: 0.0011,
    inc: [{ ago: 17 * 1440 + 200, dur: 120, frac: 0.05 }] },
  { id: 'login', name: 'Sign-in success', kind: 'Availability', svc: 'identity', target: 0.9995, rps: 12,
    desc: 'Password and SSO sign-in attempts that end in a session rather than a server error.', unit: 'sign-ins', base: 0.00012,
    inc: [{ ago: 6 * 1440 + 420, dur: 20, frac: 0.02 }, { ago: 35, dur: 35, frac: 0.016 }] },
  { id: 'pdf', name: 'Invoice PDF render', kind: 'Latency', svc: 'render-worker', target: 0.99, rps: 4,
    desc: 'Invoice PDFs rendered and stored within 5 seconds of being requested.', unit: 'renders', base: 0.0035,
    inc: [...mondays, { ago: 3600, dur: 3600, frac: 0.0095 }] }
];

let seed = 1;
const rand = () => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const hash = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619); return h; };
const shape = t => {
  const d = new Date(t), h = d.getUTCHours() + d.getUTCMinutes() / 60, dow = d.getUTCDay();
  return (0.55 + 0.45 * Math.sin((h - 8) / 24 * 2 * Math.PI)) * (dow === 0 || dow === 6 ? 0.62 : 1);
};
function gen(s) {
  if (s.data) return s.data;
  seed = hash(s.id);
  const T = new Float64Array(N + 1), B = new Float64Array(N + 1);
  for (let i = 0; i < N; i++) {
    const ago = (N - i - 0.5) * 5, t = NOW - ago * 60000;
    const tot = Math.round(s.rps * 300 * shape(t) * (0.92 + rand() * 0.16));
    let p = s.base * (0.45 + rand() * 1.1);
    s.inc.forEach(c => { if (ago <= c.ago && ago > c.ago - c.dur) p += c.frac * (0.85 + rand() * 0.3); });
    T[i + 1] = T[i] + tot;
    B[i + 1] = B[i] + Math.min(tot, Math.floor(tot * p + rand()));
  }
  return (s.data = { T, B });
}
// burn rate of the w buckets ending at bucket i (inclusive), as a multiple of the allowed error rate
const burnAt = (D, i, w, allowed) => { const a = Math.max(0, i + 1 - w), t = D.T[i + 1] - D.T[a]; return t ? (D.B[i + 1] - D.B[a]) / t / allowed : 0; };

function view(s, days) {
  const D = gen(s), nb = days * 288, i0 = N - nb, allowed = 1 - s.target;
  const tot = D.T[N] - D.T[i0], bad = D.B[N] - D.B[i0], budget = allowed * tot;
  const Hn = days * 24, rem = new Float64Array(Hn + 1), burn = new Float64Array(Hn), hb = new Float64Array(Hn), ht = new Float64Array(Hn);
  rem[0] = 1;
  for (let h = 0; h < Hn; h++) {
    const a = i0 + h * 12, b = a + 12;
    ht[h] = D.T[b] - D.T[a]; hb[h] = D.B[b] - D.B[a];
    burn[h] = ht[h] ? hb[h] / ht[h] / allowed : 0;
    rem[h + 1] = 1 - (D.B[b] - D.B[i0]) / budget;
  }
  const pols = POL.map(p => {
    const runs = []; let open = -1;
    for (let i = i0; i < N; i++) {
      const f = burnAt(D, i, p.long, allowed) >= p.th && burnAt(D, i, p.short, allowed) >= p.th;
      if (f && open < 0) open = i;
      if (!f && open >= 0) { runs.push([open, i]); open = -1; }
    }
    if (open >= 0) runs.push([open, N]);
    return { p, runs, long: burnAt(D, N - 1, p.long, allowed), short: burnAt(D, N - 1, p.short, allowed), firing: open >= 0 };
  });
  return { s, D, days, i0, allowed, tot, bad, budget, remaining: 1 - bad / budget, Hn, rem, burn, hb, ht, pols };
}

/* a hypothetical incident starting now: traffic repeats last week's, bad = rate x traffic */
function simulate(v, rate, mins) {
  const { D, allowed, budget } = v, k = Math.round(mins / 5), L = 900;
  const T = new Float64Array(L + k + 1), B = new Float64Array(L + k + 1), base = N - L;
  for (let j = 0; j <= L; j++) { T[j] = D.T[base + j] - D.T[base]; B[j] = D.B[base + j] - D.B[base]; }
  for (let j = 0; j < k; j++) {
    const src = N - 2016 + j, tot = D.T[src + 1] - D.T[src];
    T[L + j + 1] = T[L + j] + tot; B[L + j + 1] = B[L + j] + tot * Math.max(rate, v.s.base);
  }
  const E = { T, B }, fires = {};
  v.pols.forEach(pp => {
    if (pp.firing) { fires[pp.p.id] = 0; return; }
    for (let j = 0; j < k; j++) {
      const i = L + j;
      if (burnAt(E, i, pp.p.long, allowed) >= pp.p.th && burnAt(E, i, pp.p.short, allowed) >= pp.p.th) { fires[pp.p.id] = (j + 1) * 5; break; }
    }
  });
  const proj = [v.remaining];
  let out = v.remaining > 0 ? null : 0;
  for (let j = 0; j < k; j++) {
    const r = v.remaining - (B[L + j + 1] - B[L]) / budget;
    proj.push(r);
    if (out == null && r < 0) out = (j + 1) * 5;
  }
  const hburn = [];
  for (let h = 0; h * 12 < k; h++) {
    const a = L + h * 12, b = Math.min(L + k, a + 12);
    hburn.push({ b: (B[b] - B[a]) / (T[b] - T[a]) / allowed, frac: (b - a) / 12 });
  }
  return { k, mins: k * 5, rate, proj, fires, out, spent: (B[L + k] - B[L]) / budget, hburn };
}

/* ---------- formatting ---------- */
const nf = new Intl.NumberFormat('en-US');
const big = v => v >= 1e9 ? (v / 1e9).toFixed(2) + 'B' : v >= 1e6 ? (v / 1e6).toFixed(v >= 1e8 ? 0 : 1) + 'M' : v >= 1e4 ? Math.round(v / 1e3) + 'k' : nf.format(Math.round(v));
const pct = (v, d = 1) => (v * 100).toFixed(d) + '%';
const xb = v => v >= 100 ? Math.round(v) + '×' : v >= 10 ? v.toFixed(1) + '×' : v.toFixed(2) + '×';
const dur = m => { m = Math.round(m); if (m < 60) return m + ' min'; const h = Math.floor(m / 60), r = m % 60; return h + ' h' + (r ? ' ' + r + ' min' : ''); };
const mmss = min => { const s = Math.round(Math.abs(min) * 60); return Math.floor(s / 60) + 'm ' + String(s % 60).padStart(2, '0') + 's'; };
const dfDay = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const dfHr = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'UTC', hourCycle: 'h23' });
const rateFrom = v => 0.001 * Math.pow(500, v / 100);
const ratePct = r => (r * 100 < 1 ? (r * 100).toFixed(2) : r * 100 < 10 ? (r * 100).toFixed(1) : Math.round(r * 100)) + '%';
const remState = r => r < 0 ? 'bad' : r < 0.25 ? 'warn' : 'ok';
const relAgo = ms => { const m = ms / 60000; return m < 90 ? Math.round(m) + ' min ago' : m < 2880 ? Math.round(m / 60) + ' h ago' : Math.round(m / 1440) + ' d ago'; };

/* ---------- state ---------- */
const st = { slo: 'api', win: 28, pol: null, sim: false, rate: 58, dur: 9, hover: null };
let V = null, SIM = null;
const cur = () => SLOS.find(s => s.id === st.slo);

/* ---------- sidebar ---------- */
const list = $('.dbo-budget-list');
list.innerHTML = SLOS.map((s, i) => `<li class="dbo-budget-item" role="option" id="${uid}-o-${s.id}" data-id="${s.id}" tabindex="${s.id === st.slo ? 0 : -1}" aria-selected="${s.id === st.slo}" style="--i:${i}">
  <b>${s.name}</b><em data-r></em><small><span>${(s.target * 100).toFixed(s.target >= 0.999 ? 2 : 1)}% · ${s.svc}</span><span data-badges></span></small><span class="dbo-budget-meter"></span></li>`).join('');
function paintSide() {
