list.addEventListener('click', e => { const el = e.target.closest('.dbo-budget-item'); if (el) pickSlo(el.dataset.id); });
list.addEventListener('keydown', e => {
  const items = $$('.dbo-budget-item', list), i = items.findIndex(x => x.dataset.id === st.slo);
  const d = { ArrowDown: 1, ArrowRight: 1, ArrowUp: -1, ArrowLeft: -1 }[e.key];
