  $('[data-name]').textContent = s.name;
  $('[data-desc]').textContent = s.desc;
  const set = (k, html, state) => { const el = $(`[data-v="${k}"]`); el.innerHTML = html; if (state !== undefined) el.closest('.dbo-budget-stat').dataset.s = state; if (tick && el.tagName === 'DD' && !reduce) { el.removeAttribute('data-tick'); void el.offsetWidth; el.setAttribute('data-tick', ''); } };
  const outageMin = Math.abs(v.remaining) * v.allowed * v.days * 1440;
  set('rem', `${(v.remaining * 100).toFixed(1)}<small>%</small>`, remState(v.remaining));
  set('remsub', v.remaining >= 0 ? `≈ ${mmss(outageMin)} of full outage left in ${v.days} days` : `Over budget by ≈ ${mmss(outageMin)} of full outage`);
  const b1 = burnAt(v.D, N - 1, 12, v.allowed), b6 = burnAt(v.D, N - 1, 72, v.allowed);
  set('burn', xb(b1), b1 >= 6 ? 'bad' : b1 >= 1 ? 'warn' : '');
  set('burnsub', `6 h: ${xb(b6)} · 1× spends the budget exactly`);
  const sli = 1 - v.bad / v.tot;
  set('sli', `${(sli * 100).toFixed(s.target >= 0.999 ? 3 : 2)}<small>%</small>`, sli >= s.target ? '' : 'bad');
  set('slisub', `target ${(s.target * 100).toFixed(s.target >= 0.999 ? 2 : 1)}% of ${big(v.tot)} ${s.unit}`);
  set('bad', big(v.bad), v.bad > v.budget ? 'bad' : '');
  set('badsub', `of ${big(v.budget)} allowed in ${v.days} days`);
}

/* ---------- policies ---------- */
const tbody = $('.dbo-budget-table tbody');
function paintPolicies() {
  const v = V;
  tbody.innerHTML = v.pols.map((pp, i) => {
    const p = pp.p, last = pp.runs.length ? pp.runs[pp.runs.length - 1] : null;
    const total = pp.runs.reduce((a, r) => a + (r[1] - r[0]) * 5, 0);
    const fired = pp.firing ? `now · ${dur((N - last[0]) * 5)}` : last ? `${pp.runs.length}× · ${relAgo((N - last[1]) * B5)}` : 'never';
    return `<tr data-p="${p.id}" tabindex="${(st.pol || 'fast') === p.id ? 0 : -1}" aria-selected="${st.pol === p.id}" title="Fired for ${dur(total)} in total over ${v.days} days">
      <td><span class="dbo-budget-pname"><b>${p.name}</b><small>${p.lw} &amp; ${p.sw} windows ≥ ${p.th}×</small></span></td>
      <td class="dbo-budget-num"><span ${pp.long >= p.th ? 'data-over' : ''}>${xb(pp.long)}</span> / <span ${pp.short >= p.th ? 'data-over' : ''}>${xb(pp.short)}</span></td>
      <td><span class="dbo-budget-state" ${pp.firing ? `data-fire="${p.sev}"` : ''}><i></i>${pp.firing ? 'Firing' : 'OK'}</span></td>
      <td class="dbo-budget-num">${fired}</td></tr>`;
  }).join('');
}
function pickPol(id, focus) {
  st.pol = st.pol === id ? null : id;
  $$('tr', tbody).forEach(r => { r.setAttribute('aria-selected', String(r.dataset.p === st.pol)); r.tabIndex = r.dataset.p === id ? 0 : -1; if (focus && r.dataset.p === id) r.focus(); });
  draw(false);
  const pp = V.pols.find(x => x.p.id === id);
  live.textContent = st.pol ? `${pp.p.name}: fired ${pp.runs.length} times in ${V.days} days` : 'Policy markers hidden';
}
tbody.addEventListener('click', e => { const r = e.target.closest('tr'); if (r) pickPol(r.dataset.p); });
tbody.addEventListener('keydown', e => {
  const r = e.target.closest('tr'); if (!r) return;
  const rows = $$('tr', tbody), i = rows.indexOf(r);
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pickPol(r.dataset.p, true); return; }
  const d = e.key === 'ArrowDown' ? 1 : e.key === 'ArrowUp' ? -1 : 0;
  if (!d) return;
  e.preventDefault();
  const n = rows[Math.max(0, Math.min(rows.length - 1, i + d))];
  rows.forEach(x => { x.tabIndex = x === n ? 0 : -1; }); n.focus();
});

/* ---------- simulator ---------- */
const sw = $('.dbo-budget-switch'), inRate = $('[data-in="rate"]'), inDur = $('[data-in="dur"]');
function paintSim() {
  const rate = rateFrom(st.rate), mins = st.dur * 5;
  $('[data-o="rate"]').textContent = ratePct(rate);
  $('[data-o="dur"]').textContent = dur(mins);
  SIM = simulate(V, rate, mins);
  const after = V.remaining - SIM.spent;
  $('[data-verdict]').innerHTML = `${ratePct(rate)} errors for ${dur(mins)} spends <b ${SIM.spent > 0.1 ? 'data-hot' : ''}>${pct(SIM.spent)}</b> of the ${V.days}-day budget: <b>${pct(V.remaining)}</b> → <b ${after < 0 ? 'data-hot' : ''}>${pct(after)}</b>` +
    (SIM.out === 0 ? '. The budget is already spent.' : SIM.out ? `, and runs it dry after <b data-hot>${dur(SIM.out)}</b>.` : '.');
  $('[data-fires]').innerHTML = V.pols.map(pp => {
    const m = SIM.fires[pp.p.id];
    return `<li ${m != null ? `data-fire="${pp.p.sev}"` : ''}><span>${pp.p.name}</span><b>${m === 0 ? 'already firing' : m != null ? 'fires after ' + dur(m) : 'stays quiet'}</b></li>`;
  }).join('');
}
const setSim = on => { st.sim = on; sw.setAttribute('aria-checked', String(on)); draw(false); };
sw.addEventListener('click', () => setSim(!st.sim));
[inRate, inDur].forEach(inp => inp.addEventListener('input', () => {
  st.rate = +inRate.value; st.dur = +inDur.value;
  paintSim();
  if (!st.sim) setSim(true); else draw(false);
}));

/* ---------- chart ---------- */
const chart = $('.dbo-budget-chart'), svg = $('.dbo-budget-svg'), tip = $('.dbo-budget-tip'), live = $('.dbo-budget-live');
let G = null; // geometry of the last draw, for hover
function draw(anim) {
  const W = chart.clientWidth, H = chart.clientHeight;
  if (!W || !H || !V) return;
  const v = V, sim = st.sim ? SIM : null;
  const m = { l: 46, r: 40, t: 10 }, axisH = 22, gap = 34;
  const iw = W - m.l - m.r, hA = Math.round((H - m.t - axisH - gap) * 0.64), hB = H - m.t - axisH - gap - hA;
  const yA0 = m.t, yB0 = m.t + hA + gap;
  const t0 = NOW - v.days * 864e5, t1 = NOW + (sim ? sim.mins * 60000 : 0);
  // with a simulation running, the future gets a fixed 20% of the axis on its own scale
  const split = sim ? 0.8 : 1, xNow = m.l + iw * split;
  const X = t => t <= NOW ? m.l + (t - t0) / (NOW - t0) * iw * split : xNow + (t - NOW) / (t1 - NOW) * iw * (1 - split);
  const Xinv = x => x <= xNow ? t0 + (x - m.l) / (iw * split) * (NOW - t0) : NOW + (x - xNow) / (iw * (1 - split)) * (t1 - NOW);
  let lo = Math.min(0, ...v.rem, ...(sim ? sim.proj : [1]));
  lo = Math.min(-0.25, Math.floor((lo - 0.04) * 4) / 4);
  const hi = 1.05, YA = r => yA0 + (hi - r) / (hi - lo) * hA;
  const maxB = Math.max(20, ...v.burn, ...(sim ? sim.hburn.map(x => x.b) : [0])) * 1.25;
  const lmin = Math.log10(0.1), lmax = Math.log10(maxB);
  const YB = b => yB0 + hB - (Math.log10(Math.max(0.1, b)) - lmin) / (lmax - lmin) * hB;
  const hx = h => X(t0 + h * 36e5);
  G = { X, Xinv, YA, YB, t0, t1, iw, m, hA, hB, yA0, yB0, W, H };
  const f = n => n.toFixed(1);
  let o = `<defs>
    <clipPath id="${uid}-top"><rect x="0" y="${yA0 - 4}" width="${W}" height="${f(YA(0) - yA0 + 4)}"/></clipPath>
    <clipPath id="${uid}-bot"><rect x="0" y="${f(YA(0))}" width="${W}" height="${f(yA0 + hA - YA(0) + 4)}"/></clipPath>
    <pattern id="${uid}-hatch" class="dbo-budget-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v6"/></pattern></defs>`;
  // y grid, budget
  for (let r = Math.ceil(lo * 4) / 4; r <= 1.0001; r += 0.25) {
    const y = f(YA(r));
    o += `<line class="${Math.abs(r) < 1e-6 ? 'dbo-budget-zero' : 'dbo-budget-gl'}" x1="${m.l}" x2="${m.l + iw}" y1="${y}" y2="${y}"/><text class="dbo-budget-ax${Math.abs(r) < 1e-6 ? ' dbo-budget-ax-strong' : ''}" x="${m.l - 8}" y="${y}" dy="3.5" text-anchor="end">${Math.round(r * 100)}%</text>`;
  }
  // y grid, burn rate (log)
  [0.1, 1, 10, 100].forEach(b => { if (b > maxB) return; const y = f(YB(b)); o += `<line class="dbo-budget-gl" x1="${m.l}" x2="${m.l + iw}" y1="${y}" y2="${y}"/><text class="dbo-budget-ax" x="${m.l - 8}" y="${y}" dy="3.5" text-anchor="end">${b}×</text>`; });
  o += `<text class="dbo-budget-ax dbo-budget-ax-strong" x="${m.l}" y="${yB0 - 10}">Hourly burn rate</text>`;
  // future zone
  if (sim) o += `<rect class="dbo-budget-future" x="${f(X(NOW))}" y="${yA0}" width="${f(X(t1) - X(NOW))}" height="${yB0 + hB - yA0}"/><rect fill="url(#${uid}-hatch)" x="${f(X(NOW))}" y="${yA0}" width="${f(X(t1) - X(NOW))}" height="${yB0 + hB - yA0}"/>`;
  // policy bands
  const sel = st.pol && v.pols.find(x => x.p.id === st.pol);
  if (sel) sel.runs.forEach(([a, b]) => {
    const xa = X(NOW - (N - a) * B5), xb2 = Math.max(xa + 2, X(NOW - (N - b) * B5));
    o += `<rect class="dbo-budget-band" data-sev="${sel.p.sev}" x="${f(xa)}" y="${yA0}" width="${f(xb2 - xa)}" height="${hA}"/><rect class="dbo-budget-bandmark" data-sev="${sel.p.sev}" x="${f(xa)}" y="${yA0 + hA - 3}" width="${f(xb2 - xa)}" height="3"/>`;
  });
  // burn-down
  const pts = Array.from(v.rem, (r, h) => [hx(h), YA(r)]);
  const line = pts.map((p, i) => `${i ? 'L' : 'M'}${f(p[0])} ${f(p[1])}`).join('');
  const area = `${line}L${f(pts[pts.length - 1][0])} ${f(YA(0))}L${f(pts[0][0])} ${f(YA(0))}Z`;
  o += `<g class="dbo-budget-plot">
    <line class="dbo-budget-ideal" x1="${f(X(t0))}" y1="${f(YA(1))}" x2="${f(X(NOW))}" y2="${f(YA(0))}"/>
    <path class="dbo-budget-apos" clip-path="url(#${uid}-top)" d="${area}"/><path class="dbo-budget-aneg" clip-path="url(#${uid}-bot)" d="${area}"/>
    <path class="dbo-budget-lpos" clip-path="url(#${uid}-top)" d="${line}"/><path class="dbo-budget-lneg" clip-path="url(#${uid}-bot)" d="${line}"/>
  </g>`;
  if (sim) o += `<path class="dbo-budget-proj" d="${sim.proj.map((r, j) => `${j ? 'L' : 'M'}${f(X(NOW + j * B5))} ${f(YA(r))}`).join('')}"/>`;
  // burn bars, one path per severity
  const paths = ['', '', '', ''], spath = ['', '', '', ''], base = YB(0.1), lvl = b => b >= 14.4 ? 3 : b >= 6 ? 2 : b >= 1 ? 1 : 0;
  const bw = Math.max(0.6, (xNow - m.l) / v.Hn - ((xNow - m.l) / v.Hn > 3 ? 1 : 0));
  for (let h = 0; h < v.Hn; h++) { const b = v.burn[h]; if (b <= 0.1) continue; const x = hx(h), y = YB(b); paths[lvl(b)] += `M${f(x)} ${f(base)}V${f(y)}h${bw.toFixed(2)}V${f(base)}Z`; }
  if (sim) sim.hburn.forEach((hb, k) => { const x = X(NOW + k * 36e5), x2 = X(Math.min(t1, NOW + (k + 1) * 36e5)), y = YB(hb.b); spath[lvl(hb.b)] += `M${f(x + 1)} ${f(base)}V${f(y)}H${f(Math.max(x + 2, x2 - 1))}V${f(base)}Z`; });
  o += `<g class="dbo-budget-bars">${paths.map((d, k) => d ? `<path class="dbo-budget-b${k}" d="${d}"/>` : '').join('')}${spath.map((d, k) => d ? `<path class="dbo-budget-b${k} dbo-budget-bsim" d="${d}"/>` : '').join('')}</g>`;
  POL.forEach(p => { const y = f(YB(p.th)); o += `<line class="dbo-budget-th" data-l="${p.l}" ${sel && sel.p.id === p.id ? 'data-on' : ''} x1="${m.l}" x2="${m.l + iw}" y1="${y}" y2="${y}"/>`; });
  [[14.4, 3], [6, 2], [1, 1]].forEach(([b, l]) => { o += `<text class="dbo-budget-thl" data-l="${l}" x="${m.l + iw + 6}" y="${f(YB(b))}" dy="3.5">${b}×</text>`; });
  // x axis
  const step = [1, 2, 4, 7, 14].find(k => (v.days / k) * 62 <= (xNow - m.l)) || 14;
  const dayStart = Date.UTC(2026, 9, 2) - v.days * 864e5;
  for (let d = 0; d <= v.days; d += step) {
    const t = dayStart + d * 864e5; if (t <= t0 + 36e5 * 3) continue;
    if (sim && X(NOW) - X(t) < 44) continue;
    const x = f(X(t));
    o += `<line class="dbo-budget-gl" x1="${x}" x2="${x}" y1="${yB0 + hB}" y2="${yB0 + hB + 4}"/><text class="dbo-budget-ax" x="${x}" y="${H - 6}" text-anchor="middle">${dfDay.format(t)}</text>`;
  }
  const xn = f(X(NOW));
  o += `<line class="dbo-budget-now" x1="${xn}" x2="${xn}" y1="${yA0}" y2="${yB0 + hB}"/>`;
  if (sim) o += `<text class="dbo-budget-ax dbo-budget-ax-strong" x="${xn}" y="${H - 6}" text-anchor="middle">now</text><text class="dbo-budget-ax" x="${f(m.l + iw)}" y="${H - 6}" text-anchor="end">+${dur(sim.mins)}</text>` +
    `<path class="dbo-budget-break" d="M${f(xNow - 4)} ${yB0 + hB + 7}l4 -8M${f(xNow)} ${yB0 + hB + 7}l4 -8"/>`;
  o += `<line class="dbo-budget-cross" y1="${yA0}" y2="${yB0 + hB}" visibility="hidden"/><circle class="dbo-budget-dot" data-k="a" r="4" visibility="hidden"/><circle class="dbo-budget-dot" data-k="b" r="3.5" visibility="hidden"/>`;
  svg.innerHTML = o;
  if (anim && !reduce) {
    svg.style.setProperty('--dur', anim === 'quick' ? '650ms' : '1200ms');
    svg.removeAttribute('data-anim'); void svg.getBoundingClientRect(); svg.setAttribute('data-anim', '');
    clearTimeout(draw.t); draw.t = setTimeout(() => svg.removeAttribute('data-anim'), 1500);
  }
  if (st.hover != null) hover(st.hover);
}

function hover(t) {
  if (!G) return;
  const cross = $('.dbo-budget-cross', svg), da = $('[data-k="a"]', svg), db = $('[data-k="b"]', svg);
  if (t == null) { [cross, da, db].forEach(e => e.setAttribute('visibility', 'hidden')); tip.removeAttribute('data-on'); st.hover = null; return; }
  st.hover = t;
  const v = V, x = G.X(t);
  let html, ra, bb;
  if (t <= NOW) {
    const h = Math.max(0, Math.min(v.Hn - 1, Math.floor((t - G.t0) / 36e5)));
    ra = v.rem[h + 1]; bb = v.burn[h];
    html = `<header>${dfHr.format(G.t0 + h * 36e5)}–${String((new Date(G.t0 + (h + 1) * 36e5)).getUTCHours()).padStart(2, '0')}:00</header>
      <div ${ra < 0 ? 'data-hot' : ''}><span>budget left</span><b>${pct(ra)}</b></div>
      <div ${bb >= 6 ? 'data-hot' : ''}><span>burn that hour</span><b>${xb(bb)}</b></div>
      <div><span>bad / total</span><b>${big(v.hb[h])} / ${big(v.ht[h])}</b></div>`;
  } else {
    const j = Math.max(0, Math.min(SIM.k, Math.round((t - NOW) / B5))), k = Math.min(SIM.hburn.length - 1, Math.floor(j / 12));
    ra = SIM.proj[j]; bb = SIM.hburn[k].b;
    html = `<header>Simulated · now + ${dur(j * 5)}</header>
      <div ${ra < 0 ? 'data-hot' : ''}><span>budget left</span><b>${pct(ra)}</b></div>
      <div data-hot><span>burn rate</span><b>${xb(bb)}</b></div>`;
  }
  cross.setAttribute('x1', x); cross.setAttribute('x2', x); cross.setAttribute('visibility', 'visible');
  da.setAttribute('cx', x); da.setAttribute('cy', G.YA(ra)); da.setAttribute('visibility', 'visible'); da.toggleAttribute('data-neg', ra < 0);
  db.setAttribute('cx', x); db.setAttribute('cy', G.YB(bb)); db.setAttribute('visibility', 'visible');
  tip.innerHTML = html; tip.setAttribute('data-on', '');
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const left = x + 14 + tw > G.W ? x - tw - 14 : x + 14;
  tip.style.transform = `translate(${Math.max(0, left)}px, ${Math.max(0, Math.min(G.H - th, G.YA(ra) - th - 10))}px)`;
}
chart.addEventListener('pointermove', e => {
  if (!G) return;
  const r = chart.getBoundingClientRect(), x = e.clientX - r.left;
  if (x < G.m.l || x > G.m.l + G.iw) { hover(null); return; }
  const t = G.Xinv(x);
  hover(t <= NOW ? Math.floor((t - G.t0) / 36e5) * 36e5 + G.t0 + 18e5 : t);
});
chart.addEventListener('pointerleave', () => hover(null));
chart.addEventListener('keydown', e => {
  if (!G) return;
  let t = st.hover ?? NOW - 18e5;
  const stp = e.shiftKey ? 864e5 : 36e5;
  if (e.key === 'ArrowLeft') t -= stp; else if (e.key === 'ArrowRight') t += stp;
  else if (e.key === 'Home') t = G.t0 + 18e5; else if (e.key === 'End') t = G.t1 - 18e5;
  else if (e.key === 'Escape') { hover(null); return; } else return;
  e.preventDefault();
  hover(Math.max(G.t0 + 18e5, Math.min(G.t1 - 1, t)));
  const ra = t <= NOW ? V.rem[Math.min(V.Hn, Math.floor((st.hover - G.t0) / 36e5) + 1)] : null;
  if (ra != null) live.textContent = `${dfHr.format(st.hover)}: ${pct(ra)} of budget left`;
});
chart.addEventListener('blur', () => hover(null));

/* ---------- window radios ---------- */
const radios = $$('[data-group="win"] button');
radios.forEach((b, i) => {
  const pick = focus => { radios.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); if (focus) b.focus(); st.win = +b.dataset.v; st.hover = null; paintSide(); render('quick'); };
  b.addEventListener('click', () => pick(false));
  b.addEventListener('keydown', e => {
    const d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
    if (!d) return;
    e.preventDefault(); radios[(i + d + radios.length) % radios.length].click(); radios[(i + d + radios.length) % radios.length].focus();
  });
});

function render(anim) {
  V = view(cur(), st.win);
  paintStats(!!anim); paintPolicies(); paintSim(); draw(anim);
}

/* ---------- lifecycle ---------- */
inRate.value = st.rate; inDur.value = st.dur;
paintSide(); render(true);
let lastW = chart.clientWidth;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (Math.abs(chart.clientWidth - lastW) < 1) return;
  lastW = chart.clientWidth; draw(false);
});
ro.observe(chart);

css:
@keyframes dbo-dora-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dbo-dora-rise { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbo-dora-wipe { from { transform: scaleX(0); } }
@keyframes dbo-dora-grow { from { transform: scaleY(0); } }
@property --dbo-dora-pos { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.dbo-dora {
  /* re-theme with these four */
  --dbo-dora-bg: oklch(0.99 0.002 250);
  --dbo-dora-ink: oklch(0.21 0.02 265);
  --dbo-dora-accent: oklch(0.53 0.19 262);
  --dbo-dora-fail: oklch(0.6 0.21 24);
  /* derived */
  --dbo-dora-card: var(--dbo-dora-bg);
  --dbo-dora-wash: color-mix(in oklch, var(--dbo-dora-bg), var(--dbo-dora-ink) 3.5%);
  --dbo-dora-line: color-mix(in oklch, var(--dbo-dora-ink) 10%, transparent);
  --dbo-dora-line-2: color-mix(in oklch, var(--dbo-dora-ink) 18%, transparent);
  --dbo-dora-muted: color-mix(in oklch, var(--dbo-dora-ink) 62%, var(--dbo-dora-bg));
  --dbo-dora-faint: color-mix(in oklch, var(--dbo-dora-ink) 40%, var(--dbo-dora-bg));
  --dbo-dora-tint: color-mix(in oklch, var(--dbo-dora-accent) 10%, var(--dbo-dora-bg));
  --dbo-dora-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dbo-dora-spring: linear(0, 0.42 10%, 0.84 22%, 1.06 34%, 1.1 42%, 1.04 54%, 0.99 68%, 1);
  --dbo-dora-mono: ui-monospace, "SF Mono", Menlo, monospace;

  width: 100%;
  height: var(--dbo-dora-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-dora-bg);
  color: var(--dbo-dora-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: light;
  accent-color: var(--dbo-dora-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-dora-line-2);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-dora-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbo-dora-eyebrow { font: 600 10.5px/1.2 var(--dbo-dora-mono); letter-spacing: 0.09em; text-transform: uppercase; color: var(--dbo-dora-faint); }

  .dbo-dora-app {
    display: grid; height: 100%;
    grid-template-columns: 216px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side top" "side main";
  }

  /* ---------- side ---------- */
  .dbo-dora-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 8px; padding: 18px 12px 14px; border-right: 1px solid var(--dbo-dora-line-2); }
  .dbo-dora-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 14px; }
  .dbo-dora-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; fill: none; stroke: var(--dbo-dora-bg); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; background: var(--dbo-dora-accent); }
  .dbo-dora-brand span { display: grid; line-height: 1.15; }
  .dbo-dora-brand b { font-weight: 750; letter-spacing: -0.02em; font-size: 14px; }
  .dbo-dora-brand small { font-size: 11px; color: var(--dbo-dora-muted); }
  .dbo-dora-nav { display: grid; gap: 2px; margin-bottom: 12px; }
  .dbo-dora-nav button { display: flex; align-items: center; gap: 10px; height: 34px; padding: 0 10px; border-radius: 8px; font-weight: 550; color: var(--dbo-dora-muted); transition: background-color 150ms, color 150ms; }
  .dbo-dora-nav svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  .dbo-dora-nav button:hover { color: var(--dbo-dora-ink); background: var(--dbo-dora-wash); }
  .dbo-dora-nav button[aria-selected="true"] { color: var(--dbo-dora-accent); background: var(--dbo-dora-tint); font-weight: 650; }
  .dbo-dora-sidehead { padding: 0 10px 2px; }
  .dbo-dora-svcs { display: grid; gap: 1px; overflow: auto; scrollbar-width: thin; }
  .dbo-dora-svcs label {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 8px; cursor: pointer;
    transition: background-color 150ms, opacity 150ms;
    animation: dbo-dora-rise 460ms var(--dbo-dora-ease) both; animation-delay: calc(var(--i) * 45ms);
  }
  .dbo-dora-svcs label:hover { background: var(--dbo-dora-wash); }
  .dbo-dora-svcs input { margin: 0; width: 14px; height: 14px; }
  .dbo-dora-svcs label:has(input:not(:checked)) { opacity: 0.5; }
  .dbo-dora-svcs label:has(input:focus-visible) { outline: 2px solid var(--dbo-dora-accent); outline-offset: -2px; }
  .dbo-dora-svcs b { font: 600 12px var(--dbo-dora-mono); letter-spacing: -0.02em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-dora-svcs small { font: 11px var(--dbo-dora-mono); color: var(--dbo-dora-faint); font-variant-numeric: tabular-nums; text-align: right; }
  .dbo-dora-svcs small em { font-style: normal; color: var(--dbo-dora-fail); }
  .dbo-dora-sidenote { margin-top: auto; padding: 10px 10px 0; border-top: 1px solid var(--dbo-dora-line); font-size: 11.5px; color: var(--dbo-dora-faint); }

  /* ---------- top ---------- */
  .dbo-dora-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 16px; padding: 18px 22px 12px; }
  .dbo-dora-title { display: grid; gap: 4px; }
  .dbo-dora-title h2 { font-size: clamp(20px, 1rem + 1cqi, 27px); font-weight: 750; letter-spacing: -0.035em; line-height: 1.05; }
  .dbo-dora-seg { display: inline-flex; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--dbo-dora-line-2); overflow: hidden; }
  .dbo-dora-seg button { height: 30px; padding: 0 13px; font: 600 12px var(--dbo-dora-mono); color: var(--dbo-dora-muted); transition: background-color 150ms, color 150ms; }
  .dbo-dora-seg button + button { box-shadow: inset 1px 0 0 var(--dbo-dora-line-2); }
  .dbo-dora-seg button:hover { color: var(--dbo-dora-ink); background: var(--dbo-dora-wash); }
  .dbo-dora-seg button[aria-checked="true"] { color: var(--dbo-dora-bg); background: var(--dbo-dora-ink); }

  /* ---------- main ---------- */
  .dbo-dora-main {
    grid-area: main; min-height: 0; overflow: auto; padding: 0 22px 20px;
    display: grid; gap: 14px; align-content: start;
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr);
    grid-template-areas: "keys keys" "view view" "detail fails";
    scrollbar-width: thin; scrollbar-color: var(--dbo-dora-line-2) transparent;
  }
  .dbo-dora-panel { min-width: 0; border-radius: 12px; background: var(--dbo-dora-card); box-shadow: inset 0 0 0 1px var(--dbo-dora-line-2); }
  .dbo-dora-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 14px; padding: 12px 14px 4px; }
  .dbo-dora-ph h3 { font-size: 13px; font-weight: 700; letter-spacing: -0.01em; margin-right: auto; }
  .dbo-dora-ph small { font: 11px var(--dbo-dora-mono); color: var(--dbo-dora-faint); }

  /* four keys */
  .dbo-dora-keys { grid-area: keys; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 2px solid var(--dbo-dora-ink); }
  .dbo-dora-key { display: grid; align-content: start; gap: 3px; padding: 12px 14px 4px 0; animation: dbo-dora-rise 520ms var(--dbo-dora-ease) both; animation-delay: calc(var(--i) * 60ms + 100ms); }
  .dbo-dora-key + .dbo-dora-key { padding-left: 14px; box-shadow: inset 1px 0 0 var(--dbo-dora-line); }
  .dbo-dora-key h4 { font: 600 10.5px var(--dbo-dora-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-dora-muted); display: flex; justify-content: space-between; gap: 6px; }
  .dbo-dora-band { font: 700 9.5px/1 var(--dbo-dora-mono); letter-spacing: 0.08em; padding: 3px 6px; border-radius: 4px; color: var(--dbo-dora-accent); background: var(--dbo-dora-tint); }
  .dbo-dora-band[data-b="0"] { color: var(--dbo-dora-fail); background: color-mix(in oklch, var(--dbo-dora-fail) 10%, var(--dbo-dora-bg)); }
  .dbo-dora-band[data-b="1"] { color: var(--dbo-dora-muted); background: var(--dbo-dora-wash); }
  .dbo-dora-kv { font: 650 clamp(22px, 0.9rem + 1.4cqi, 30px)/1.1 system-ui, sans-serif; letter-spacing: -0.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbo-dora-kv small { font-size: 0.48em; font-weight: 550; letter-spacing: -0.01em; color: var(--dbo-dora-muted); margin-left: 3px; }
  .dbo-dora-delta { font: 500 11px var(--dbo-dora-mono); color: var(--dbo-dora-faint); font-variant-numeric: tabular-nums; }
  .dbo-dora-delta b { font-weight: 650; }
  .dbo-dora-delta [data-good] { color: oklch(0.55 0.13 155); }
  .dbo-dora-delta [data-bad] { color: var(--dbo-dora-fail); }
  .dbo-dora-scale { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 2px; margin-top: 8px; padding-bottom: 14px; transition: --dbo-dora-pos 700ms var(--dbo-dora-spring); }
  .dbo-dora-scale i { height: 4px; border-radius: 1px; background: var(--dbo-dora-line-2); transform-origin: left; animation: dbo-dora-wipe 600ms var(--dbo-dora-ease) both; animation-delay: calc(var(--i) * 60ms + 260ms); }
  .dbo-dora-scale i[data-on] { background: var(--dbo-dora-ink); }
  .dbo-dora-scale span { position: absolute; top: 9px; font: 9.5px var(--dbo-dora-mono); color: var(--dbo-dora-faint); text-transform: uppercase; letter-spacing: 0.06em; }
  .dbo-dora-scale span:first-of-type { left: 0; }
  .dbo-dora-scale span:last-of-type { right: 0; }
  .dbo-dora-scale::after {
    content: ""; position: absolute; top: -3px; left: var(--dbo-dora-pos); width: 2px; height: 10px; margin-left: -1px; border-radius: 1px;
    background: var(--dbo-dora-accent); box-shadow: 0 0 0 2px var(--dbo-dora-bg);
  }

  /* lanes */
  .dbo-dora-timepanel, .dbo-dora-listpanel { grid-area: view; display: flex; flex-direction: column; }
  .dbo-dora-legend { display: flex; flex-wrap: wrap; gap: 4px 14px; font: 500 11px var(--dbo-dora-mono); color: var(--dbo-dora-muted); }
  .dbo-dora-legend li { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-dora-legend i { width: 8px; height: 8px; border-radius: 50%; background: var(--dbo-dora-accent); }
  .dbo-dora-legend i[data-k="fail"] { border-radius: 1px; rotate: 45deg; scale: 0.9; background: var(--dbo-dora-fail); }
  .dbo-dora-legend i[data-k="restore"] { width: 16px; height: 4px; border-radius: 2px; background: color-mix(in oklch, var(--dbo-dora-fail) 35%, transparent); }
  .dbo-dora-lanes { position: relative; height: 236px; margin: 4px 10px 0; outline: none; cursor: default; }
  .dbo-dora-lanes:focus-visible { box-shadow: inset 0 0 0 2px var(--dbo-dora-accent); border-radius: 8px; }
  .dbo-dora-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbo-dora-lane { fill: var(--dbo-dora-wash); }
  .dbo-dora-wkend { fill: color-mix(in oklch, var(--dbo-dora-ink) 3%, transparent); }
  .dbo-dora-gl { stroke: var(--dbo-dora-line); }
  .dbo-dora-ax { font: 10.5px var(--dbo-dora-mono); fill: var(--dbo-dora-faint); font-variant-numeric: tabular-nums; }
  .dbo-dora-ln { font: 600 11.5px var(--dbo-dora-mono); fill: var(--dbo-dora-ink); letter-spacing: -0.02em; }
  .dbo-dora-lc { font: 10.5px var(--dbo-dora-mono); fill: var(--dbo-dora-faint); }
  .dbo-dora-mk { transform-box: fill-box; transform-origin: center; cursor: pointer; transition: scale 200ms var(--dbo-dora-spring); }
  .dbo-dora-mk[data-f="0"] { fill: var(--dbo-dora-accent); stroke: var(--dbo-dora-bg); stroke-width: 1; }
  .dbo-dora-mk[data-f="1"] { fill: var(--dbo-dora-fail); stroke: var(--dbo-dora-bg); stroke-width: 1; }
  .dbo-dora-mk[data-hot] { scale: 1.6; }
  .dbo-dora-rs { fill: color-mix(in oklch, var(--dbo-dora-fail) 32%, transparent); }
  .dbo-dora-rse { stroke: var(--dbo-dora-fail); stroke-width: 1.5; }
  .dbo-dora-sel { fill: none; stroke: var(--dbo-dora-ink); stroke-width: 1.5; pointer-events: none; }
  .dbo-dora-selline { stroke: var(--dbo-dora-ink); stroke-dasharray: 2 3; opacity: 0.35; pointer-events: none; }
  .dbo-dora-svg[data-anim] .dbo-dora-mk { animation: dbo-dora-pop 520ms var(--dbo-dora-spring) both; animation-delay: calc(var(--d) * 900ms); }
  .dbo-dora-svg[data-anim] .dbo-dora-rs { animation: dbo-dora-wipe 500ms var(--dbo-dora-ease) both; animation-delay: calc(var(--d) * 900ms + 200ms); transform-box: fill-box; transform-origin: left; }

  .dbo-dora-tip {
    position: absolute; left: 0; top: 0; z-index: 4; width: max-content; max-width: 280px; padding: 10px 12px; border-radius: 10px; pointer-events: none;
    background: var(--dbo-dora-ink); color: var(--dbo-dora-bg); font-size: 12px;
    box-shadow: 0 14px 30px color-mix(in oklch, var(--dbo-dora-ink) 25%, transparent);
    opacity: 0; scale: 0.97; transform-origin: 0 0; transition: opacity 120ms, scale 180ms var(--dbo-dora-ease);
  }
  .dbo-dora-tip[data-on] { opacity: 1; scale: 1; }
  .dbo-dora-tip b { display: block; font-weight: 650; margin-bottom: 2px; text-wrap: balance; }
  .dbo-dora-tip code { font: 11px var(--dbo-dora-mono); color: color-mix(in oklch, var(--dbo-dora-bg) 70%, var(--dbo-dora-ink)); }
  .dbo-dora-tip p { font: 11px var(--dbo-dora-mono); color: color-mix(in oklch, var(--dbo-dora-bg) 75%, var(--dbo-dora-ink)); margin-top: 4px; }
  .dbo-dora-tip em { font-style: normal; color: color-mix(in oklch, var(--dbo-dora-fail) 55%, white); font-weight: 600; }

  /* overview brush */
  .dbo-dora-ov { position: relative; height: 62px; margin: 6px 10px 12px; touch-action: none; user-select: none; -webkit-user-select: none; }
  .dbo-dora-ovsvg { position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; }
  .dbo-dora-ob0 { fill: color-mix(in oklch, var(--dbo-dora-ink) 22%, transparent); }
  .dbo-dora-ob1 { fill: var(--dbo-dora-fail); }
  .dbo-dora-ovsvg[data-anim] .dbo-dora-obars { animation: dbo-dora-grow 700ms var(--dbo-dora-ease) both; transform-box: fill-box; transform-origin: 50% 100%; }
  .dbo-dora-brush { position: absolute; top: 0; bottom: 16px; left: var(--l, 0px); width: var(--w, 100px); pointer-events: none; }
  .dbo-dora-body {
    position: absolute; inset: 0; pointer-events: auto; cursor: grab; border-radius: 4px;
    background: color-mix(in oklch, var(--dbo-dora-accent) 12%, transparent);
    box-shadow: inset 0 0 0 1.5px var(--dbo-dora-accent);
  }
  .dbo-dora-body:active { cursor: grabbing; }
  .dbo-dora-h { position: absolute; top: 50%; z-index: 1; width: 10px; height: 26px; margin-top: -13px; border-radius: 4px; pointer-events: auto; cursor: ew-resize; background: var(--dbo-dora-bg); box-shadow: inset 0 0 0 1.5px var(--dbo-dora-accent), 0 1px 3px color-mix(in oklch, var(--dbo-dora-ink) 20%, transparent); }
  .dbo-dora-h::after { content: ""; position: absolute; left: 4px; top: 8px; width: 2px; height: 10px; border-radius: 1px; background: var(--dbo-dora-accent); opacity: 0.6; }
  .dbo-dora-h[data-h="0"] { left: -5px; }
  .dbo-dora-h[data-h="1"] { right: -5px; }
  .dbo-dora-ov:has(.dbo-dora-body:hover) .dbo-dora-body { background: color-mix(in oklch, var(--dbo-dora-accent) 18%, transparent); }

  /* table */
  .dbo-dora-toggle { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 10px 0 8px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dbo-dora-muted); box-shadow: inset 0 0 0 1px var(--dbo-dora-line-2); }
  .dbo-dora-toggle i { width: 8px; height: 8px; border-radius: 1px; rotate: 45deg; background: var(--dbo-dora-line-2); transition: background-color 150ms; }
  .dbo-dora-toggle[aria-pressed="true"] { color: var(--dbo-dora-fail); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-dora-fail) 50%, transparent); background: color-mix(in oklch, var(--dbo-dora-fail) 6%, transparent); }
  .dbo-dora-toggle[aria-pressed="true"] i { background: var(--dbo-dora-fail); }
  .dbo-dora-tablewrap { height: 304px; overflow: auto; margin: 4px 0 0; scrollbar-width: thin; scrollbar-color: var(--dbo-dora-line-2) transparent; }
  .dbo-dora-table { width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums; }
  .dbo-dora-table th { position: sticky; top: 0; z-index: 1; padding: 0; background: var(--dbo-dora-card); border-bottom: 1px solid var(--dbo-dora-line-2); text-align: left; }
  .dbo-dora-table th button { width: 100%; display: flex; align-items: center; gap: 4px; padding: 8px 10px; font: 600 10px var(--dbo-dora-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-dora-faint); white-space: nowrap; }
  .dbo-dora-table th[aria-sort$="ending"] button { color: var(--dbo-dora-ink); }
  .dbo-dora-table th[aria-sort="ascending"] button::after { content: "↑"; }
  .dbo-dora-table th[aria-sort="descending"] button::after { content: "↓"; }
  .dbo-dora-num { text-align: right; }
  .dbo-dora-table th.dbo-dora-num button { justify-content: flex-end; }
  .dbo-dora-table td { padding: 8px 10px; border-bottom: 1px solid var(--dbo-dora-line); white-space: nowrap; font-size: 12px; }
  .dbo-dora-table td:nth-child(3) { white-space: normal; min-width: 220px; }
  .dbo-dora-table td small { display: block; font: 10.5px var(--dbo-dora-mono); color: var(--dbo-dora-faint); }
  .dbo-dora-table td[data-mono], .dbo-dora-table td.dbo-dora-num { font: 500 11.5px var(--dbo-dora-mono); }
  .dbo-dora-table tbody tr { cursor: pointer; outline: none; transition: background-color 120ms; }
  .dbo-dora-table tbody tr:hover { background: var(--dbo-dora-wash); }
  .dbo-dora-table tbody tr[aria-selected="true"] { background: var(--dbo-dora-tint); }
  .dbo-dora-table tbody tr:focus-visible td { box-shadow: inset 0 1px 0 var(--dbo-dora-accent), inset 0 -1px 0 var(--dbo-dora-accent); }
  .dbo-dora-res { display: inline-flex; align-items: center; gap: 6px; font: 600 11px var(--dbo-dora-mono); color: var(--dbo-dora-muted); }
  .dbo-dora-res i { width: 7px; height: 7px; border-radius: 50%; background: var(--dbo-dora-accent); }
  .dbo-dora-res[data-f="1"] { color: var(--dbo-dora-fail); }
  .dbo-dora-res[data-f="1"] i { border-radius: 1px; rotate: 45deg; background: var(--dbo-dora-fail); }

  /* detail */
  .dbo-dora-detail { grid-area: detail; padding: 14px 16px 16px; display: grid; gap: 10px; align-content: start; }
  .dbo-dora-detail[data-swap] > * { animation: dbo-dora-rise 380ms var(--dbo-dora-ease) both; animation-delay: calc(var(--i, 0) * 40ms); }
  .dbo-dora-dhead { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; }
  .dbo-dora-dhead h4 { font-size: 15px; font-weight: 700; letter-spacing: -0.02em; flex: 1 1 100%; }
  .dbo-dora-chip { display: inline-flex; align-items: center; gap: 5px; height: 21px; padding: 0 7px; border-radius: 5px; font: 600 11px var(--dbo-dora-mono); background: var(--dbo-dora-wash); color: var(--dbo-dora-muted); }
  .dbo-dora-chip[data-f="1"] { color: var(--dbo-dora-fail); background: color-mix(in oklch, var(--dbo-dora-fail) 9%, var(--dbo-dora-bg)); }
  .dbo-dora-chip[data-f="0"] { color: var(--dbo-dora-accent); background: var(--dbo-dora-tint); }
  .dbo-dora-meta { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; margin: 0; }
  .dbo-dora-meta dt { font: 600 10px var(--dbo-dora-mono); letter-spacing: 0.07em; text-transform: uppercase; color: var(--dbo-dora-faint); }
  .dbo-dora-meta dd { margin: 1px 0 0; font: 550 12.5px var(--dbo-dora-mono); font-variant-numeric: tabular-nums; }
  .dbo-dora-stack { display: flex; height: 22px; border-radius: 5px; overflow: hidden; gap: 2px; }
  .dbo-dora-stack span { flex: var(--f) 1 0; min-width: 3px; transform-origin: left; animation: dbo-dora-wipe 620ms var(--dbo-dora-ease) both; animation-delay: calc(var(--i) * 90ms + 80ms); }
  .dbo-dora-stack span:nth-child(1) { background: color-mix(in oklch, var(--dbo-dora-accent) 30%, var(--dbo-dora-bg)); }
  .dbo-dora-stack span:nth-child(2) { background: color-mix(in oklch, var(--dbo-dora-accent) 60%, var(--dbo-dora-bg)); }
  .dbo-dora-stack span:nth-child(3) { background: var(--dbo-dora-accent); }
  .dbo-dora-keyrow { display: flex; flex-wrap: wrap; gap: 4px 14px; font: 11px var(--dbo-dora-mono); color: var(--dbo-dora-muted); }
  .dbo-dora-keyrow span { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-dora-keyrow i { width: 9px; height: 9px; border-radius: 2px; }
  .dbo-dora-keyrow span:nth-child(1) i { background: color-mix(in oklch, var(--dbo-dora-accent) 30%, var(--dbo-dora-bg)); }
  .dbo-dora-keyrow span:nth-child(2) i { background: color-mix(in oklch, var(--dbo-dora-accent) 60%, var(--dbo-dora-bg)); }
  .dbo-dora-keyrow span:nth-child(3) i { background: var(--dbo-dora-accent); }
  .dbo-dora-keyrow b { color: var(--dbo-dora-ink); font-weight: 600; }
  .dbo-dora-note { font-size: 12px; color: var(--dbo-dora-muted); }
  .dbo-dora-note strong { color: var(--dbo-dora-fail); font-weight: 650; }
  .dbo-dora-empty { color: var(--dbo-dora-muted); font-size: 12.5px; padding: 6px 0; }

  /* failures */
  .dbo-dora-fails { grid-area: fails; display: flex; flex-direction: column; min-height: 0; }
  .dbo-dora-faillist { padding: 2px 8px 10px; max-height: 214px; overflow: auto; scrollbar-width: thin; }
