const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;

/* ---------- data ----------
   180 days of production deploys for six services. Each deploy carries its lead time
   (first commit -> PR -> approval -> production), whether it caused a failure, and how
   long service took to restore. The four keys, the lanes, the overview bars, the table
   and the failure list are all filtered views of this one array. */
const NOW = Date.UTC(2026, 9, 2, 15, 0), TODAY = Date.UTC(2026, 9, 2);
const GEN = 180, OV = 90;
const dayStart = k => TODAY - (OV - 1 - k) * 864e5;
const PEOPLE = ['Ines Okafor', 'Tomas Reyes', 'Priya Natarajan', 'Jun Takeda', 'Malik Osei', 'Sofia Lindqvist', 'Arjun Mehta', 'Hana Kowalski', 'Dario Esposito', 'Leah Brandt', 'Kofi Mensah', 'Yara Haddad'];
const SVC = [
  { id: 'web', name: 'storefront-web', rate: 2.3, lead: 6, fail: 0.06, mttr: 26, team: [0, 1, 2, 11],
    titles: ['Lazy-load product carousel images', 'Fix sticky header jitter on narrow screens', 'Move checkout button above the fold', 'Bump design tokens to 4.2', 'Skeleton states for order history', 'Server-render category pages', 'Persist basket across sign-in', 'Trim hero image payload by 40%', 'Keyboard focus order in filters', 'Show delivery slot countdown'],
    harm: ['blank product pages for a slice of sessions', 'a broken basket button on category pages', 'a 3x jump in client-side errors'] },
  { id: 'orders', name: 'orders-api', rate: 1.5, lead: 9, fail: 0.08, mttr: 41, team: [3, 4, 8],
    titles: ['Idempotency keys on order creation', 'Cursor pagination for order history', 'Retry outbox publisher with jitter', 'Drop legacy v1 status field', 'Partial refund endpoint', 'Validate postcode before quoting', 'Emit order.split events', 'Index orders by customer and date'],
    harm: ['duplicate orders on retried requests', '5xx on order history for 6% of calls', 'stuck orders in the outbox'] },
  { id: 'pricing', name: 'pricing-engine', rate: 0.85, lead: 19, fail: 0.1, mttr: 55, team: [6, 7, 9],
    titles: ['Cache tax tables per region', 'Round VAT per line, not per basket', 'Migrate rules engine to v3 syntax', 'Cap promo stacking at two codes', 'Shadow-run the new price calculator', 'Bulk price import for suppliers', 'Explain price breakdown in API'],
    harm: ['wrong VAT on 3% of baskets', 'promo codes rejected at checkout', 'p95 quote latency over 2 s'] },
  { id: 'ledger', name: 'ledger', rate: 0.35, lead: 46, fail: 0.16, mttr: 96, team: [5, 10],
    titles: ['Double-entry check on reversals', 'Partition journal table by month', 'Nightly reconciliation report', 'Rebuild balances from snapshots', 'Reject unbalanced postings early'],
    harm: ['journal writes blocked by lock contention', 'reconciliation drift on refunds'] },
  { id: 'notify', name: 'notifications', rate: 1.05, lead: 7, fail: 0.045, mttr: 22, team: [2, 8, 11],
    titles: ['Batch push sends per 500', 'Template preview endpoint', 'Quiet hours by recipient time zone', 'Dedupe texts within 10 minutes', 'Unsubscribe link in every email', 'Retry bounced email once'],
    harm: ['delayed dispatch texts', 'duplicate push notifications'] },
  { id: 'search', name: 'search-indexer', rate: 0.6, lead: 13, fail: 0.07, mttr: 34, team: [3, 6, 9],
    titles: ['Reindex synonyms on publish', 'Boost in-stock items', 'Incremental index for price changes', 'Typo tolerance for product codes', 'Facet counts for dietary tags'],
    harm: ['stale prices in search results', 'empty results for multi-word queries'] }
];

let seed = 20260;
const rand = () => {
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const gauss = () => Math.sqrt(-2 * Math.log(1 - rand())) * Math.cos(2 * Math.PI * rand());
const poisson = l => { let k = 0, p = 1; const L = Math.exp(-l); do { k++; p *= rand(); } while (p > L); return k - 1; };
const pick = a => a[Math.floor(rand() * a.length)];
const DEP = [];
SVC.forEach((s, si) => {
  for (let d = GEN - 1; d >= 0; d--) {
    const day = TODAY - d * 864e5, dow = new Date(day).getUTCDay(), wk = dow === 0 || dow === 6;
    const n = poisson(s.rate * (wk ? 0.08 : 1.18));
    for (let k = 0; k < n; k++) {
      const t = rand() < 0.05 ? day + rand() * 864e5 : day + (8.5 + rand() * 9.5) * 36e5;
      if (t > NOW - 6e5) continue;
      const age = (NOW - t) / 864e5;
      const lead = Math.max(0.6, s.lead * (0.62 + 0.38 * Math.min(1, age / 150)) * Math.exp(gauss() * 0.6));
      const c = 0.25 + rand() * 0.3, r = 0.18 + rand() * 0.27;
      const rough = s.id === 'pricing' && age > 17 && age < 25 ? 3.2 : 1; // the rules-engine migration week
      const fail = rand() < s.fail * rough;
      DEP.push({ svc: si, t, lead, parts: [lead * c, lead * r, lead * (1 - c - r)], fail,
        restore: fail ? Math.max(6, s.mttr * Math.exp(gauss() * 0.65)) : 0, how: rand() < 0.68 ? 'rolled back' : 'hot-fixed',
        title: pick(s.titles), who: PEOPLE[pick(s.team)], fixer: PEOPLE[pick(s.team)], harm: pick(s.harm),
        sha: Array.from({ length: 7 }, () => '0123456789abcdef'[Math.floor(rand() * 16)]).join('') });
    }
  }
});
DEP.sort((a, b) => a.t - b.t);
DEP.forEach((d, i) => { d.i = i; d.pr = 3820 + i; });

/* ---------- the four keys and their research bands ---------- */
const median = a => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const KEYS = [
  { k: 'df', label: 'Deploy frequency', up: true, log: true, cuts: [1 / 30, 1 / 7, 1], lo: 1 / 120, hi: 15 },
  { k: 'lead', label: 'Lead time', up: false, log: true, cuts: [720, 168, 24], lo: 2880, hi: 0.5 },
  { k: 'cfr', label: 'Change failure rate', up: false, log: false, cuts: [0.15, 0.1, 0.05], lo: 0.45, hi: 0 },
  { k: 'mttr', label: 'Time to restore', up: false, log: true, cuts: [10080, 1440, 60], lo: 43200, hi: 5 }
];
const BAND = ['Low', 'Medium', 'High', 'Elite'];
const bandOf = (K, v) => K.cuts.filter(c => K.up ? v >= c : v <= c).length;
function posOf(K, v) {
  const stops = [K.lo, ...K.cuts, K.hi], tr = K.log ? Math.log : x => x;
  for (let s = 0; s < 4; s++) {
    const a = stops[s], b = stops[s + 1];
    const inSeg = K.up ? v < b : v > b;
    if (inSeg || s === 3) return Math.max(0, Math.min(100, (s + Math.max(0, Math.min(1, (tr(Math.max(v, 1e-6)) - tr(a)) / (tr(b === 0 ? 1e-4 : b) - tr(a))))) * 25));
  }
  return 0;
}

/* ---------- formatting ---------- */
const nf = new Intl.NumberFormat('en-US');
const dfD = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const dfM = new Intl.DateTimeFormat('en-GB', { month: 'short', timeZone: 'UTC' });
const dfT = new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'UTC', hourCycle: 'h23' });
const hrs = h => h < 1 ? Math.round(h * 60) + ' min' : h < 48 ? h.toFixed(1) + ' h' : (h / 24).toFixed(1) + ' d';
const mins = m => m < 90 ? Math.round(m) + ' min' : m < 2880 ? (m / 60).toFixed(1) + ' h' : (m / 1440).toFixed(1) + ' d';
const fmtKey = (k, v) => {
  if (v == null) return '—';
  if (k === 'df') return v >= 1 ? `${v.toFixed(1)}<small>/ day</small>` : `${(v * 7).toFixed(1)}<small>/ week</small>`;
  if (k === 'lead') return v < 48 ? `${v.toFixed(1)}<small>h median</small>` : `${(v / 24).toFixed(1)}<small>d median</small>`;
  if (k === 'cfr') return `${(v * 100).toFixed(1)}<small>%</small>`;
  return v < 90 ? `${Math.round(v)}<small>min median</small>` : `${(v / 60).toFixed(1)}<small>h median</small>`;
};

/* ---------- state ---------- */
const st = { k0: OV - 14, k1: OV - 1, on: SVC.map(() => true), sel: null, hover: null, view: 'time', failOnly: false, sort: { k: 't', dir: -1 } };
const range = () => [dayStart(st.k0), Math.min(NOW, dayStart(st.k1) + 864e5)];
const inRange = (a, b) => DEP.filter(d => d.t >= a && d.t < b && st.on[d.svc]);
function stats(a, b) {
  const list = inRange(a, b), f = list.filter(d => d.fail);
  return { list, fails: f, n: list.length, df: list.length / ((b - a) / 864e5), lead: median(list.map(d => d.lead)), cfr: list.length ? f.length / list.length : null, mttr: median(f.map(d => d.restore)) };
}

/* ---------- sidebar services ---------- */
const svcs = $('.dbo-dora-svcs');
svcs.innerHTML = SVC.map((s, i) => `<li><label style="--i:${i}"><input type="checkbox" checked data-i="${i}"><b>${s.name}</b><small data-c></small></label></li>`).join('');
svcs.addEventListener('change', e => {
  const i = +e.target.dataset.i;
  if (!e.target.checked && st.on.filter(Boolean).length === 1) { e.target.checked = true; live.textContent = 'At least one service stays visible'; return; }
  st.on[i] = e.target.checked;
  if (st.sel && !st.on[st.sel.svc]) st.sel = null;
  renderAll(false);
});

/* ---------- four keys ---------- */
const keysEl = $('.dbo-dora-keys');
keysEl.innerHTML = KEYS.map((K, i) => `<article class="dbo-dora-key" style="--i:${i}" data-k="${K.k}">
  <h4><span>${K.label}</span><span class="dbo-dora-band"></span></h4>
  <div class="dbo-dora-kv"></div><div class="dbo-dora-delta"></div>
  <div class="dbo-dora-scale" aria-hidden="true">${BAND.map((b, j) => `<i style="--i:${j}"></i>`).join('')}<span>Low</span><span>Elite</span></div></article>`).join('');
function paintKeys(cur, prev) {
  KEYS.forEach(K => {
    const el = $(`[data-k="${K.k}"]`, keysEl), v = cur[K.k], p = prev[K.k];
    $('.dbo-dora-kv', el).innerHTML = fmtKey(K.k, v);
    const band = v == null ? null : bandOf(K, v), chip = $('.dbo-dora-band', el);
    chip.textContent = band == null ? 'n/a' : BAND[band]; chip.dataset.b = band ?? 1;
    $$('.dbo-dora-scale i', el).forEach((x, j) => x.toggleAttribute('data-on', j === band));
    $('.dbo-dora-scale', el).style.setProperty('--dbo-dora-pos', (v == null ? 0 : posOf(K, v)).toFixed(1) + '%');
    let d = '';
    if (v != null && p != null && p !== 0) {
      const better = K.k === 'cfr' ? v < p : K.up ? v > p : v < p;
      const txt = K.k === 'cfr' ? `${v >= p ? '+' : '−'}${Math.abs((v - p) * 100).toFixed(1)} pp` : `${v >= p ? '+' : '−'}${Math.abs((v - p) / p * 100).toFixed(0)}%`;
      d = `<b ${Math.abs(v - p) / Math.abs(p) < 0.02 ? '' : better ? 'data-good' : 'data-bad'}>${v >= p ? '▲' : '▼'} ${txt}</b> vs previous ${Math.round((range()[1] - range()[0]) / 864e5)} days`;
    } else d = 'no previous data';
    $('.dbo-dora-delta', el).innerHTML = d;
    el.setAttribute('aria-label', `${K.label}: ${$('.dbo-dora-kv', el).textContent}, ${chip.textContent}`);
  });
}

/* ---------- lanes ---------- */
const lanes = $('.dbo-dora-lanes'), svg = $('.dbo-dora-svg'), tip = $('.dbo-dora-tip'), live = $('.dbo-dora-live');
let PTS = [], LG = null;
function drawLanes(anim) {
  const W = lanes.clientWidth, H = lanes.clientHeight;
  if (!W || !H) return;
  const [a, b] = range(), vis = SVC.map((s, i) => i).filter(i => st.on[i]);
  const LW = W < 520 ? 104 : 140, axisH = 20, top = 2, iw = W - LW - 6;
  const lh = (H - axisH - top) / vis.length;
  const X = t => LW + (t - a) / (b - a) * iw;
  const days = (b - a) / 864e5, r = days > 45 ? 3 : days > 20 ? 3.8 : 4.6;
  const f = n => n.toFixed(1);
  let o = '';
  vis.forEach((si, li) => { if (li % 2 === 0) o += `<rect class="dbo-dora-lane" x="0" y="${f(top + li * lh)}" width="${W}" height="${f(lh)}" rx="4"/>`; });
  for (let t = a; t < b; t += 864e5) {
    const dow = new Date(t).getUTCDay();
    if (dow === 0 || dow === 6) o += `<rect class="dbo-dora-wkend" x="${f(X(t))}" y="${top}" width="${f(X(Math.min(b, t + 864e5)) - X(t))}" height="${f(lh * vis.length)}"/>`;
  }
  const step = [1, 2, 7, 14, 30].find(k => (days / k) * 58 <= iw) || 30;
  for (let t = a, k = 0; t <= b; t += 864e5, k++) {
    if (k % step) continue;
    const x = f(X(t));
    o += `<line class="dbo-dora-gl" x1="${x}" x2="${x}" y1="${top}" y2="${f(top + lh * vis.length + 4)}"/><text class="dbo-dora-ax" x="${x}" y="${H - 5}" text-anchor="middle">${dfD.format(t)}</text>`;
  }
  const counts = {};
  PTS = [];
  const list = inRange(a, b);
  list.forEach(d => { counts[d.svc] = (counts[d.svc] || 0) + 1; });
  vis.forEach((si, li) => {
    const y = top + lh * (li + 0.5);
    o += `<text class="dbo-dora-ln" x="8" y="${f(y - 2)}">${SVC[si].name}</text><text class="dbo-dora-lc" x="8" y="${f(y + 11)}">${counts[si] || 0} deploys</text>`;
  });
  const marks = [];
  list.forEach(d => {
    const li = vis.indexOf(d.svc), x = X(d.t), y = top + lh * (li + 0.5), dl = ((x - LW) / iw).toFixed(3);
    PTS.push({ d, x, y, li });
    if (d.fail) {
      const x2 = Math.max(x + 3, X(Math.min(b, d.t + d.restore * 6e4)));
      o += `<rect class="dbo-dora-rs" x="${f(x)}" y="${f(y - 2.5)}" width="${f(x2 - x)}" height="5" rx="2.5" style="--d:${dl}"/>`;
      marks.push(`<path class="dbo-dora-mk" data-f="1" data-i="${d.i}" style="--d:${dl}" d="M${f(x)} ${f(y - r - 1.4)}l${f(r + 1.4)} ${f(r + 1.4)}l${f(-r - 1.4)} ${f(r + 1.4)}l${f(-r - 1.4)} ${f(-r - 1.4)}z"/>`);
    } else marks.push(`<circle class="dbo-dora-mk" data-f="0" data-i="${d.i}" style="--d:${dl}" cx="${f(x)}" cy="${f(y)}" r="${r}"/>`);
  });
  o += marks.join('');
  const sp = st.sel && PTS.find(p => p.d === st.sel);
  if (sp) o += `<line class="dbo-dora-selline" x1="${f(sp.x)}" x2="${f(sp.x)}" y1="${top}" y2="${f(top + lh * vis.length)}"/><circle class="dbo-dora-sel" cx="${f(sp.x)}" cy="${f(sp.y)}" r="${r + 4.5}"/>`;
  svg.innerHTML = o;
  LG = { W, H, lh, top, vis, LW };
  if (anim && !reduce) { svg.setAttribute('data-anim', ''); setTimeout(() => svg.removeAttribute('data-anim'), 1700); }
  if (st.hover) markHot(st.hover);
}
function markHot(d) {
  $$('.dbo-dora-mk[data-hot]', svg).forEach(e => e.removeAttribute('data-hot'));
  if (d) { const e = $(`.dbo-dora-mk[data-i="${d.i}"]`, svg); if (e) e.setAttribute('data-hot', ''); }
}
function showTip(p) {
  const d = p.d, s = SVC[d.svc];
  tip.innerHTML = `<b>${d.title}</b><code>${s.name} · #${d.pr} · ${d.sha}</code><p>${dfT.format(d.t)} UTC · ${d.who}<br>lead time ${hrs(d.lead)}${d.fail ? ` · <em>failed, ${d.how} in ${mins(d.restore)}</em>` : ''}</p>`;
  tip.setAttribute('data-on', '');
  const tw = tip.offsetWidth, th = tip.offsetHeight;
  const left = p.x + 14 + tw > LG.W ? p.x - tw - 14 : p.x + 14;
  tip.style.transform = `translate(${Math.max(0, left)}px, ${Math.max(0, Math.min(LG.H - th, p.y - th - 8))}px)`;
}
const hideTip = () => tip.removeAttribute('data-on');
function nearest(px, py) {
  if (!LG) return null;
  const li = Math.floor((py - LG.top) / LG.lh);
  let best = null, bd = 12;
  PTS.forEach(p => { if (p.li !== li) return; const dd = Math.abs(p.x - px); if (dd < bd) { bd = dd; best = p; } });
  return best;
}
lanes.addEventListener('pointermove', e => {
  const r = lanes.getBoundingClientRect(), p = nearest(e.clientX - r.left, e.clientY - r.top);
  st.hover = p ? p.d : null; markHot(st.hover);
  lanes.style.cursor = p ? 'pointer' : 'default';
  if (p) showTip(p); else hideTip();
});
lanes.addEventListener('pointerleave', () => { st.hover = null; markHot(null); hideTip(); });
lanes.addEventListener('click', e => {
  const r = lanes.getBoundingClientRect(), p = nearest(e.clientX - r.left, e.clientY - r.top);
  select(p ? p.d : null);
});
lanes.addEventListener('keydown', e => {
  if (!PTS.length) return;
  const order = [...PTS].sort((p, q) => p.d.t - q.d.t);
  let cur = order.find(p => p.d === st.sel) || null, next = null;
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
    const i = cur ? order.indexOf(cur) : (e.key === 'ArrowRight' ? -1 : order.length);
    next = order[Math.max(0, Math.min(order.length - 1, i + (e.key === 'ArrowRight' ? 1 : -1)))];
  } else if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    cur = cur || order[order.length - 1];
