@property --dbo-incident-hue { syntax: "<number>"; inherits: true; initial-value: 28; }
@property --dbo-incident-done { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes dbo-incident-rise { from { opacity: 0; transform: translateY(8px); } }
