@keyframes dbo-incident-flash { 0% { background-color: color-mix(in oklch, var(--dbo-incident-accent) 22%, transparent); } }
@keyframes dbo-incident-blink { 50% { opacity: 0.35; } }

.dbo-incident {
  /* re-theme: background, ink, and the signal colour's lightness/chroma; the hue walks with the phase */
  --dbo-incident-bg: oklch(0.17 0.006 40);
