  width: 100%;
  height: var(--dbo-incident-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background:
    radial-gradient(120% 60% at 0% 0%, color-mix(in oklch, var(--dbo-incident-accent) 9%, transparent), transparent 60%),
    var(--dbo-incident-bg);
  color: var(--dbo-incident-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
