  transition: --dbo-incident-hue 1100ms var(--dbo-incident-ease);

  &[data-phase="0"] { --dbo-incident-hue: 22; }
  &[data-phase="1"] { --dbo-incident-hue: 42; }
  &[data-phase="2"] { --dbo-incident-hue: 68; }
