  .dbo-incident-idrow { grid-area: id; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  .dbo-incident-code { font: 650 12px var(--dbo-incident-mono); letter-spacing: 0.02em; color: var(--dbo-incident-muted); }
  .dbo-incident-top h2 { grid-area: title; font-size: clamp(17px, 0.85rem + 0.9cqi, 23px); font-weight: 650; letter-spacing: -0.02em; line-height: 1.15; }
  .dbo-incident-sevwrap { position: relative; }
