    background: var(--dbo-incident-raise); box-shadow: 0 0 0 1px var(--dbo-incident-line-2), 0 18px 40px oklch(0 0 0 / 0.55);
    transform-origin: 20px 0; transition: opacity 160ms, scale 220ms var(--dbo-incident-ease), display 220ms allow-discrete;
    @starting-style { opacity: 0; scale: 0.94; }
  }
  .dbo-incident-menu li { display: grid; grid-template-columns: 10px minmax(0, 1fr); gap: 0 9px; align-items: center; padding: 7px 9px; border-radius: 7px; cursor: pointer; outline: none; }
  .dbo-incident-menu li:hover, .dbo-incident-menu li:focus-visible { background: color-mix(in oklch, var(--dbo-incident-ink) 7%, transparent); }
  .dbo-incident-menu li i { width: 8px; height: 8px; border-radius: 50%; }
  .dbo-incident-menu li[data-sev="1"] i { background: var(--dbo-incident-red); }
  .dbo-incident-menu li[data-sev="2"] i { background: oklch(0.8 0.15 70); }
  .dbo-incident-menu li[data-sev="3"] i { background: oklch(0.78 0.08 230); }
  .dbo-incident-menu li b { font: 700 12px var(--dbo-incident-mono); }
  .dbo-incident-menu li small { grid-column: 2; font-size: 11.5px; color: var(--dbo-incident-muted); }
  .dbo-incident-menu li[aria-checked="true"] { box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); }
  .dbo-incident-phasepill { display: inline-flex; align-items: center; gap: 7px; height: 24px; padding: 0 9px; border-radius: 99px; font-size: 12px; font-weight: 650; color: var(--dbo-incident-accent); background: color-mix(in oklch, var(--dbo-incident-accent) 14%, transparent); }
  .dbo-incident-phasepill i { position: relative; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
  .dbo-incident-phasepill i::after { content: ""; position: absolute; inset: 0; border-radius: inherit; background: currentColor; animation: dbo-incident-ping 1.8s var(--dbo-incident-ease) infinite; }
  &[data-phase="4"] .dbo-incident-phasepill i::after { animation: none; opacity: 0; }
  .dbo-incident-clock { grid-area: clock; display: grid; justify-items: end; gap: 1px; text-align: right; }
  .dbo-incident-clock b { font: 600 clamp(26px, 1rem + 2.2cqi, 36px)/1 var(--dbo-incident-mono); letter-spacing: -0.04em; font-variant-numeric: tabular-nums; color: var(--dbo-incident-ink); }
  &[data-phase="4"] .dbo-incident-clock b { color: var(--dbo-incident-accent); }
  .dbo-incident-clock small { font-size: 11.5px; color: var(--dbo-incident-faint); }

  /* ---------- stepper ---------- */
  .dbo-incident-steps { grid-area: steps; display: flex; align-items: center; gap: 12px; padding: 8px 8px 8px 12px; border-radius: 12px; background: var(--dbo-incident-panel); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); }
  .dbo-incident-steps ol { flex: 1; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; counter-reset: dbo-incident-step; }
  .dbo-incident-step { position: relative; display: grid; gap: 5px; min-width: 0; font-size: 12px; color: var(--dbo-incident-faint); }
  .dbo-incident-step::before { content: ""; height: 4px; border-radius: 2px; background: var(--dbo-incident-line-2); }
  .dbo-incident-step span { display: flex; gap: 6px; align-items: baseline; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: 600; }
  .dbo-incident-step small { font: 10.5px var(--dbo-incident-mono); color: var(--dbo-incident-faint); font-variant-numeric: tabular-nums; }
  .dbo-incident-step[data-s="done"] { color: var(--dbo-incident-muted); }
  .dbo-incident-step[data-s="done"]::before { background: color-mix(in oklch, var(--dbo-incident-accent) 55%, var(--dbo-incident-panel)); }
  .dbo-incident-step[data-s="now"] { color: var(--dbo-incident-ink); }
  .dbo-incident-step[data-s="now"]::before { background: linear-gradient(90deg in oklch, var(--dbo-incident-accent) 0 60%, color-mix(in oklch, var(--dbo-incident-accent) 35%, var(--dbo-incident-panel))); }
  .dbo-incident-step[data-s="now"] small { color: var(--dbo-incident-accent); }
  .dbo-incident-step[data-new]::before { animation: dbo-incident-reveal 700ms var(--dbo-incident-ease) both; }
  .dbo-incident-advance {
    flex: none; display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px 0 14px; border-radius: 9px;
    font-weight: 650; color: var(--dbo-incident-bg); background: var(--dbo-incident-accent);
    box-shadow: 0 6px 18px color-mix(in oklch, var(--dbo-incident-accent) 30%, transparent); transition: filter 150ms, translate 150ms var(--dbo-incident-ease);
  }
  .dbo-incident-advance:hover { filter: brightness(1.08); translate: 0 -1px; }
  .dbo-incident-advance:active { translate: 0 1px; }
  .dbo-incident-advance svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  .dbo-incident-advance[data-reopen] { color: var(--dbo-incident-ink); background: var(--dbo-incident-raise); box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); }

  /* ---------- panels ---------- */
  .dbo-incident-panel { min-height: 0; min-width: 0; display: flex; flex-direction: column; border-radius: 12px; background: var(--dbo-incident-panel); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); overflow: hidden; animation: dbo-incident-rise 560ms var(--dbo-incident-ease) both; animation-delay: calc(var(--i, 0) * 60ms); }
  .dbo-incident-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; padding: 11px 12px 6px; }
  .dbo-incident-ph h3 { font-size: 12.5px; font-weight: 650; margin-right: auto; }
  .dbo-incident-ph small { font: 11px var(--dbo-incident-mono); color: var(--dbo-incident-faint); font-variant-numeric: tabular-nums; }
  .dbo-incident-impact { grid-area: impact; --i: 0; }
  .dbo-incident-people { grid-area: people; --i: 2; }
  .dbo-incident-feed { grid-area: feed; --i: 1; }
  .dbo-incident-tasks { grid-area: tasks; --i: 2; }
  .dbo-incident-comms { grid-area: comms; --i: 3; }

  /* impact */
  .dbo-incident-kpis { display: grid; grid-template-columns: repeat(3, auto); justify-content: space-between; gap: 8px; padding: 0 12px 4px; }
  .dbo-incident-kpis div { display: grid; gap: 1px; }
  .dbo-incident-kpis b { font: 600 17px var(--dbo-incident-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
  .dbo-incident-kpis [data-k="succ"][data-bad] { color: var(--dbo-incident-red); }
  .dbo-incident-kpis [data-k="succ"][data-good] { color: oklch(0.8 0.14 152); }
  .dbo-incident-chart { position: relative; flex: 1; min-height: 110px; margin: 0 8px 8px; outline: none; cursor: crosshair; }
  .dbo-incident-chart:focus-visible { box-shadow: inset 0 0 0 2px var(--dbo-incident-accent); border-radius: 8px; }
  .dbo-incident-chart svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbo-incident-gl { stroke: var(--dbo-incident-line); }
  .dbo-incident-slo { stroke: oklch(0.8 0.14 152); stroke-dasharray: 3 3; opacity: 0.7; }
  .dbo-incident-ax { font: 10px var(--dbo-incident-mono); fill: var(--dbo-incident-faint); font-variant-numeric: tabular-nums; }
  .dbo-incident-area { fill: color-mix(in oklch, var(--dbo-incident-accent) 16%, transparent); }
  .dbo-incident-line { fill: none; stroke: var(--dbo-incident-accent); stroke-width: 1.75; stroke-linejoin: round; }
  .dbo-incident-plot[data-anim] { animation: dbo-incident-reveal 1200ms var(--dbo-incident-ease) both; }
  .dbo-incident-mk line { stroke: var(--dbo-incident-muted); stroke-dasharray: 1 2; }
  .dbo-incident-mk circle { fill: var(--dbo-incident-bg); stroke: var(--dbo-incident-ink); stroke-width: 1.5; }
  .dbo-incident-cross { stroke: var(--dbo-incident-ink); opacity: 0.4; }
  .dbo-incident-dot { fill: var(--dbo-incident-bg); stroke: var(--dbo-incident-accent); stroke-width: 2; }
  .dbo-incident-tip { position: absolute; top: 0; left: 0; z-index: 3; padding: 6px 9px; border-radius: 8px; pointer-events: none; white-space: nowrap; background: var(--dbo-incident-sink); box-shadow: 0 0 0 1px var(--dbo-incident-line-2); font: 11px var(--dbo-incident-mono); font-variant-numeric: tabular-nums; opacity: 0; transition: opacity 120ms; }
  .dbo-incident-tip[data-on] { opacity: 1; }
  .dbo-incident-tip b { color: var(--dbo-incident-accent); }

  /* responders */
  .dbo-incident-roles { overflow: auto; padding: 0 8px 8px; scrollbar-width: thin; scrollbar-color: var(--dbo-incident-line-2) transparent; }
  .dbo-incident-role { display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; gap: 0 10px; align-items: center; padding: 6px 4px; border-radius: 8px; }
  .dbo-incident-role + .dbo-incident-role { border-top: 1px solid var(--dbo-incident-line); }
  .dbo-incident-av { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font: 700 11px var(--dbo-incident-mono); color: var(--dbo-incident-bg); background: oklch(0.8 0.08 var(--h)); }
  .dbo-incident-av[data-empty] { color: var(--dbo-incident-muted); background: none; box-shadow: inset 0 0 0 1.5px var(--dbo-incident-line-2); border: 0; }
  .dbo-incident-role b { font-weight: 600; font-size: 12.5px; display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .dbo-incident-role small { font-size: 11px; color: var(--dbo-incident-faint); display: block; }
  .dbo-incident-role em { font: 500 10.5px var(--dbo-incident-mono); font-style: normal; color: var(--dbo-incident-muted); }
  .dbo-incident-page { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--dbo-incident-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-incident-accent) 45%, transparent); transition: background-color 150ms; }
  .dbo-incident-page:hover { background: color-mix(in oklch, var(--dbo-incident-accent) 12%, transparent); }
  .dbo-incident-page[aria-busy="true"] { pointer-events: none; color: var(--dbo-incident-muted); box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); display: inline-flex; align-items: center; gap: 6px; }
  .dbo-incident-page[aria-busy="true"]::before { content: ""; width: 10px; height: 10px; border-radius: 50%; border: 1.5px solid currentColor; border-right-color: transparent; animation: dbo-incident-spin 800ms linear infinite; }

  /* timeline */
  .dbo-incident-filters { display: flex; flex-wrap: wrap; gap: 4px; }
  .dbo-incident-filters button { height: 24px; padding: 0 8px; border-radius: 6px; font: 600 11px var(--dbo-incident-mono); color: var(--dbo-incident-muted); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbo-incident-filters button:hover { color: var(--dbo-incident-ink); }
  .dbo-incident-filters button[aria-pressed="true"] { color: var(--dbo-incident-ink); background: var(--dbo-incident-raise); box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); }
  .dbo-incident-filters em { font-style: normal; color: var(--dbo-incident-faint); margin-left: 4px; }
  .dbo-incident-log { flex: 1; min-height: 0; overflow: auto; padding: 4px 12px 10px; scrollbar-width: thin; scrollbar-color: var(--dbo-incident-line-2) transparent; overscroll-behavior: contain; }
  .dbo-incident-ev { position: relative; display: grid; grid-template-columns: 52px 26px minmax(0, 1fr); gap: 0 8px; padding: 6px 0; }
  .dbo-incident-ev::before { content: ""; position: absolute; left: 72px; top: 30px; bottom: -6px; width: 1px; background: var(--dbo-incident-line); }
  .dbo-incident-ev:last-child::before { display: none; }
  .dbo-incident-ev time { display: grid; font: 600 11.5px var(--dbo-incident-mono); font-variant-numeric: tabular-nums; padding-top: 4px; }
  .dbo-incident-ev time small { font: 500 10px var(--dbo-incident-mono); color: var(--dbo-incident-faint); }
  .dbo-incident-ico { width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; color: var(--c); background: color-mix(in oklch, var(--c) 15%, transparent); }
  .dbo-incident-ico svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  .dbo-incident-ev[data-t="alert"] { --c: var(--dbo-incident-red); }
  .dbo-incident-ev[data-t="page"] { --c: oklch(0.8 0.12 300); }
  .dbo-incident-ev[data-t="note"] { --c: var(--dbo-incident-muted); }
  .dbo-incident-ev[data-t="action"] { --c: oklch(0.8 0.12 220); }
  .dbo-incident-ev[data-t="decision"] { --c: oklch(0.82 0.14 85); }
  .dbo-incident-ev[data-t="comms"] { --c: oklch(0.8 0.13 160); }
  .dbo-incident-ev[data-t="phase"] { --c: var(--dbo-incident-accent); }
  .dbo-incident-body { min-width: 0; padding-top: 2px; }
  .dbo-incident-body header { display: flex; gap: 8px; align-items: baseline; font-size: 11.5px; color: var(--dbo-incident-faint); }
  .dbo-incident-body header b { color: var(--dbo-incident-muted); font-weight: 600; }
  .dbo-incident-body p { font-size: 12.5px; color: var(--dbo-incident-ink); }
  .dbo-incident-body code { font: 11.5px var(--dbo-incident-mono); padding: 0 4px; border-radius: 4px; background: color-mix(in oklch, var(--dbo-incident-ink) 8%, transparent); }
  .dbo-incident-ev[data-t="phase"] p { font-weight: 650; color: var(--dbo-incident-accent); }
  .dbo-incident-ev[data-fresh] { animation: dbo-incident-flash 1.6s var(--dbo-incident-ease); border-radius: 8px; }
  .dbo-incident-empty { padding: 20px 4px; color: var(--dbo-incident-faint); font-size: 12px; }
  .dbo-incident-compose { display: flex; align-items: center; gap: 6px; margin: 0; padding: 8px; border-top: 1px solid var(--dbo-incident-line); background: color-mix(in oklch, var(--dbo-incident-panel), black 12%); }
  .dbo-incident-kind { display: inline-flex; gap: 1px; padding: 2px; border-radius: 8px; background: var(--dbo-incident-sink); flex: none; }
  .dbo-incident-kind button { height: 26px; padding: 0 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dbo-incident-muted); }
  .dbo-incident-kind button[aria-checked="true"] { color: var(--dbo-incident-ink); background: var(--dbo-incident-raise); }
  .dbo-incident-compose input { flex: 1; min-width: 0; height: 32px; padding: 0 10px; border: 0; border-radius: 8px; font: inherit; font-size: 12.5px; color: var(--dbo-incident-ink); background: var(--dbo-incident-sink); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); outline: none; transition: box-shadow 150ms; }
  .dbo-incident-compose input::placeholder { color: var(--dbo-incident-faint); }
  .dbo-incident-compose input:focus-visible { box-shadow: inset 0 0 0 1.5px var(--dbo-incident-accent); }
  .dbo-incident-post { width: 32px; height: 32px; flex: none; display: grid; place-items: center; border-radius: 8px; color: var(--dbo-incident-bg); background: var(--dbo-incident-accent); }
  .dbo-incident-post svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  .dbo-incident-compose:has(input:placeholder-shown) .dbo-incident-post { opacity: 0.4; pointer-events: none; }

  /* tasks */
  .dbo-incident-ring { position: relative; width: 30px; height: 30px; transition: --dbo-incident-done 700ms var(--dbo-incident-ease); }
  .dbo-incident-ring svg { width: 30px; height: 30px; rotate: -90deg; }
  .dbo-incident-ring circle { fill: none; stroke-width: 3.5; }
  .dbo-incident-ring circle:first-child { stroke: var(--dbo-incident-line-2); }
  .dbo-incident-ring circle:last-child { stroke: var(--dbo-incident-accent); stroke-linecap: round; stroke-dasharray: calc(var(--dbo-incident-done) * 1px) 100px; }
  .dbo-incident-ring b { position: absolute; inset: 0; display: grid; place-items: center; font: 650 9.5px var(--dbo-incident-mono); }
  .dbo-incident-checks { overflow: auto; padding: 0 8px 8px; scrollbar-width: thin; scrollbar-color: var(--dbo-incident-line-2) transparent; }
  .dbo-incident-checks label { display: grid; grid-template-columns: 16px minmax(0, 1fr); gap: 2px 10px; align-items: start; padding: 7px 6px; border-radius: 8px; cursor: pointer; transition: background-color 140ms; }
  .dbo-incident-checks label:hover { background: color-mix(in oklch, var(--dbo-incident-ink) 5%, transparent); }
  .dbo-incident-checks input { width: 15px; height: 15px; margin: 2px 0 0; }
  .dbo-incident-checks span { font-size: 12.5px; transition: color 200ms; }
  .dbo-incident-checks small { grid-column: 2; font-size: 11px; color: var(--dbo-incident-faint); }
  .dbo-incident-checks label:has(input:checked) span { color: var(--dbo-incident-faint); text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--dbo-incident-ink) 30%, transparent); }
  .dbo-incident-checks label:has(input:focus-visible) { outline: 2px solid var(--dbo-incident-accent); outline-offset: -2px; }

  /* comms */
  .dbo-incident-comms { gap: 7px; padding-bottom: 10px; overflow: auto; scrollbar-width: thin; }
  .dbo-incident-comms > * { flex-shrink: 0; }
  .dbo-incident-ph small[data-late] { color: var(--dbo-incident-red); }
  .dbo-incident-ph small[data-soon] { color: oklch(0.82 0.14 85); }
  .dbo-incident-tpl { display: flex; flex-wrap: wrap; gap: 3px; padding: 0 12px; }
  .dbo-incident-tpl button { height: 24px; padding: 0 6px; border-radius: 6px; font-size: 11px; font-weight: 600; color: var(--dbo-incident-muted); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); }
  .dbo-incident-tpl button[aria-checked="true"] { color: var(--dbo-incident-ink); background: var(--dbo-incident-raise); box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); }
  .dbo-incident-comms textarea { margin: 0 12px; padding: 8px 10px; min-height: 50px; resize: none; border: 0; border-radius: 8px; font: inherit; font-size: 12.5px; color: var(--dbo-incident-ink); background: var(--dbo-incident-sink); box-shadow: inset 0 0 0 1px var(--dbo-incident-line); outline: none; field-sizing: content; max-height: 120px; }
  .dbo-incident-comms textarea:focus-visible { box-shadow: inset 0 0 0 1.5px var(--dbo-incident-accent); }
  .dbo-incident-preview { margin: 0 12px; padding: 10px 12px; border-radius: 10px; color: oklch(0.25 0.02 250); background: oklch(0.97 0.004 250); }
  .dbo-incident-preview header { display: flex; justify-content: space-between; gap: 8px; align-items: center; margin-bottom: 4px; font-size: 12px; }
  .dbo-incident-preview header span { font: 700 10px var(--dbo-incident-mono); letter-spacing: 0.06em; text-transform: uppercase; padding: 3px 6px; border-radius: 4px; color: white; background: var(--pv, oklch(0.62 0.17 45)); }
  .dbo-incident-preview p { font-size: 12px; line-height: 1.45; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden; }
  .dbo-incident-preview small { display: block; margin-top: 4px; font-size: 10.5px; color: oklch(0.5 0.02 250); }
  .dbo-incident-publish { margin: 0 12px; height: 32px; border-radius: 8px; font-weight: 650; color: var(--dbo-incident-ink); background: var(--dbo-incident-raise); box-shadow: inset 0 0 0 1px var(--dbo-incident-line-2); transition: background-color 150ms; }
  .dbo-incident-publish:hover { background: color-mix(in oklch, var(--dbo-incident-accent) 20%, var(--dbo-incident-raise)); }

  /* ---------- responsive ---------- */
  @container (max-width: 1040px) {
    .dbo-incident-app {
      overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dbo-incident-line-2) transparent;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
      grid-template-rows: auto auto 250px 380px auto;
      grid-template-areas: "top top" "steps steps" "impact people" "feed feed" "tasks comms";
    }
    .dbo-incident-tasks, .dbo-incident-comms { min-height: 300px; }
  }
  @container (max-width: 760px) {
    .dbo-incident-app { padding: 10px; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto 240px 400px auto auto auto; grid-template-areas: "top" "steps" "impact" "feed" "tasks" "comms" "people"; }
    .dbo-incident-top { grid-template-columns: minmax(0, 1fr); grid-template-areas: "id" "title" "clock"; }
    .dbo-incident-clock { justify-items: start; text-align: left; grid-template-columns: auto auto; align-items: baseline; gap: 2px 10px; }
    .dbo-incident-clock small { grid-column: 1 / -1; }
    .dbo-incident-steps { flex-direction: column; align-items: stretch; }
    .dbo-incident-advance { justify-content: center; }
    .dbo-incident-tasks, .dbo-incident-comms, .dbo-incident-people { min-height: auto; }
  }
  @container (max-width: 480px) {
    .dbo-incident-step span { font-size: 10.5px; }
    .dbo-incident-step small { display: none; }
    .dbo-incident-kind button { padding: 0 6px; }
    .dbo-incident-compose { flex-wrap: wrap; }
    .dbo-incident-kind { order: -1; }
    .dbo-incident-ev { grid-template-columns: 44px 24px minmax(0, 1fr); }
    .dbo-incident-ev::before { left: 63px; }
  }

  @media (prefers-reduced-motion: reduce) {
