/* ---------- clock ----------
   The console runs on a simulated wall clock that starts at 14:39:12 UTC and then
   advances in real time, so the elapsed timer, the "next update due" countdown, new
   timeline entries and the live impact chart all agree with each other. */
const T0 = Date.UTC(2026, 9, 2, 14, 2, 0);            // declared
const START = Date.UTC(2026, 9, 2, 13, 54, 0);        // first failed unlocks
const MOUNT = Date.UTC(2026, 9, 2, 14, 39, 12);
