const nf = new Intl.NumberFormat('en-US');

const PH = ['Investigating', 'Identified', 'Mitigating', 'Monitoring', 'Resolved'];
const ADV = ['Mark identified', 'Start mitigating', 'Move to monitoring', 'Resolve incident', 'Reopen incident'];
const st = { phase: 1, phaseAt: [T0, at(14, 31)], sev: 2, filter: 'all', kind: 'note', tpl: 'identified', lastUpdate: at(14, 12), resolvedAt: null, visible: true };

/* ---------- timeline ---------- */
const ICO = {
  alert: '<path d="M6 16V11a6 6 0 0 1 12 0v5l1.5 2h-15z"/><path d="M10 20.5h4"/>',
  page: '<rect x="7" y="3.5" width="10" height="17" rx="2"/><path d="M11 17.5h2"/>',
  note: '<path d="M5 6.5h14M5 11.5h14M5 16.5h9"/>',
  action: '<path d="M13 3.5 5.5 13.5H12l-1 7 7.5-10H12z"/>',
  decision: '<path d="M6 21V4.5"/><path d="M6 5h11l-2.5 4L17 13H6"/>',
  comms: '<path d="M4 10v4h3l6 4V6L7 10z"/><path d="M16.5 9a4 4 0 0 1 0 6M19 6.5a7.5 7.5 0 0 1 0 11"/>',
  phase: '<path d="m6 7 5 5-5 5M13 7l5 5-5 5"/>'
};
const LOG = [
  { t: at(13, 58), type: 'alert', who: 'monitor', text: 'unlock-success below 95% for 5 min in eu-south' },
  { t: at(13, 59), type: 'page', who: 'pager', text: 'Paged Rhea Saini, operations on-call' },
  { t: at(14, 2), type: 'phase', who: 'Rhea Saini', text: 'Declared SEV 2. Amara Kwan is incident commander.' },
  { t: at(14, 5), type: 'note', who: 'Rhea Saini', text: 'Failures are 503s from <code>lock-gateway</code>; only scooters on firmware 7.3 are affected.' },
  { t: at(14, 9), type: 'action', who: 'Felix Duarte', text: 'Opened the bridge and told the Lisbon and Porto partner managers.' },
  { t: at(14, 12), type: 'comms', who: 'Felix Duarte', text: 'Status page · Investigating: some riders in Lisbon and Porto cannot unlock vehicles.' },
  { t: at(14, 18), type: 'alert', who: 'monitor', text: '<code>lock-gateway</code> p99 latency 8.2 s, threshold 2 s' },
  { t: at(14, 24), type: 'decision', who: 'Amara Kwan', text: 'Hold the 4.12 rollout everywhere; prepare rollback to 4.11.' },
  { t: at(14, 31), type: 'phase', who: 'Amara Kwan', text: 'Identified: 4.12 changed the TLS session cache, so firmware 7.3 does a full handshake on every unlock and times out.' },
  { t: at(14, 36), type: 'action', who: 'Rhea Saini', text: 'Rollback of <code>lock-gateway</code> to 4.11 started in eu-south, 2 of 6 pods done.' }
