const FILTERS = [['all', 'All', () => true], ['alert', 'Alerts', e => e.type === 'alert' || e.type === 'page'], ['action', 'Actions', e => e.type === 'action' || e.type === 'decision' || e.type === 'phase'], ['note', 'Notes', e => e.type === 'note'], ['comms', 'Comms', e => e.type === 'comms']];
const logEl = $('.dbo-incident-log'), filtersEl = $('.dbo-incident-filters');
const evHtml = e => `<li class="dbo-incident-ev" data-t="${e.type}"><time datetime="${new Date(e.t).toISOString()}">${hm(e.t)}<small>${rel(e.t)}</small></time><span class="dbo-incident-ico"><svg viewBox="0 0 24 24" aria-hidden="true">${ICO[e.type]}</svg></span><div class="dbo-incident-body"><header><b>${esc(e.who)}</b><span>${e.type}</span></header><p>${e.text}</p></div></li>`;
