  --dbo-logs-raise: color-mix(in oklch, var(--dbo-logs-bg), white 8%);
  --dbo-logs-sink: color-mix(in oklch, var(--dbo-logs-bg), black 28%);
  --dbo-logs-line: color-mix(in oklch, var(--dbo-logs-ink) 9%, transparent);
  --dbo-logs-line-2: color-mix(in oklch, var(--dbo-logs-ink) 17%, transparent);
