  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-logs-bg);
  color: var(--dbo-logs-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbo-logs-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-logs-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
