  .dbo-logs-eyebrow { font: 600 10px/1.2 var(--dbo-logs-mono); letter-spacing: 0.1em; text-transform: uppercase; color: var(--dbo-logs-faint); }

  .dbo-logs-app {
    display: grid; height: 100%;
    grid-template-columns: 220px minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-areas: "side top" "side hist" "side list";
  }

  /* ---------- facets ---------- */
  .dbo-logs-side { grid-area: side; min-height: 0; overflow: auto; padding: 14px 10px; background: var(--dbo-logs-sink); border-right: 1px solid var(--dbo-logs-line); scrollbar-width: thin; scrollbar-color: var(--dbo-logs-line-2) transparent; }
  .dbo-logs-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 16px; }
