    font: 12px var(--dbo-logs-mono); transition: background-color 120ms, opacity 160ms;
  }
  &[data-enter] .dbo-logs-facet label { animation: dbo-logs-in 380ms var(--dbo-logs-ease) both; animation-delay: calc(var(--i) * 30ms); }
  .dbo-logs-facet label:hover { background: color-mix(in oklch, var(--dbo-logs-ink) 6%, transparent); }
  .dbo-logs-facet input { margin: 0; width: 13px; height: 13px; }
