  [data-l="0"] { --c: var(--dbo-logs-l0); }
  [data-l="1"] { --c: var(--dbo-logs-l1); }
  [data-l="2"] { --c: var(--dbo-logs-l2); }
  [data-l="3"] { --c: var(--dbo-logs-l3); }
  [data-l="4"] { --c: var(--dbo-logs-l4); }

  /* ---------- top ---------- */
