  .dbo-logs-search:focus-within { box-shadow: inset 0 0 0 1.5px var(--dbo-logs-accent), 0 0 0 4px color-mix(in oklch, var(--dbo-logs-accent) 12%, transparent); }
  .dbo-logs-search[data-bad] { box-shadow: inset 0 0 0 1.5px var(--dbo-logs-hot); }
  .dbo-logs-search > svg { width: 16px; height: 16px; flex: none; fill: none; stroke: var(--dbo-logs-muted); stroke-width: 2; stroke-linecap: round; }
  .dbo-logs-search input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; color: var(--dbo-logs-ink); font: 12.5px var(--dbo-logs-mono); }
  .dbo-logs-search input::placeholder { color: var(--dbo-logs-faint); }
  .dbo-logs-regex { height: 24px; padding: 0 7px; border-radius: 5px; font: 700 12px var(--dbo-logs-mono); color: var(--dbo-logs-faint); transition: color 150ms, background-color 150ms; }
  .dbo-logs-regex:hover { color: var(--dbo-logs-ink); }
