  .dbo-logs-search:focus-within kbd { display: none; }
  .dbo-logs-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--dbo-logs-sink); box-shadow: inset 0 0 0 1px var(--dbo-logs-line); flex: none; }
