  .dbo-logs-seg button[aria-checked="true"] { color: var(--dbo-logs-ink); background: var(--dbo-logs-raise); }
  .dbo-logs-live { flex: none; display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 12px; border-radius: 9px; font: 650 12px var(--dbo-logs-mono); color: var(--dbo-logs-muted); box-shadow: inset 0 0 0 1px var(--dbo-logs-line-2); transition: color 150ms, background-color 150ms; }
  .dbo-logs-live i { width: 8px; height: 8px; border-radius: 50%; background: var(--dbo-logs-faint); }
  .dbo-logs-live[aria-pressed="true"] { color: var(--dbo-logs-accent); background: color-mix(in oklch, var(--dbo-logs-accent) 10%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-logs-accent) 35%, transparent); }
  .dbo-logs-live[aria-pressed="true"] i { background: var(--dbo-logs-accent); animation: dbo-logs-pulse 1.6s var(--dbo-logs-ease) infinite; }
