  .dbo-logs-qerr { color: var(--dbo-logs-hot); }
  .dbo-logs-clear { margin-left: auto; display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 6px 0 8px; border-radius: 5px; font: 600 11px var(--dbo-logs-mono); color: var(--dbo-logs-accent); background: color-mix(in oklch, var(--dbo-logs-accent) 10%, transparent); }
  .dbo-logs-canvas { position: relative; height: 92px; cursor: crosshair; touch-action: none; user-select: none; -webkit-user-select: none; outline: none; }
