  .dbo-logs-htip i { display: inline-block; width: 7px; height: 7px; border-radius: 2px; margin-right: 6px; background: var(--c); }
  .dbo-logs-swatches { position: absolute; width: 0; height: 0; overflow: hidden; }
  .dbo-logs-swatches i { color: var(--c); }
  .dbo-logs-swatches [data-l="grid"] { color: var(--dbo-logs-line); }
  .dbo-logs-swatches [data-l="text"] { color: var(--dbo-logs-faint); }

  /* ---------- list ---------- */
  .dbo-logs-listwrap { grid-area: list; position: relative; min-height: 0; display: flex; flex-direction: column; margin: 0 14px 14px; border-radius: 10px; background: var(--dbo-logs-sink); box-shadow: inset 0 0 0 1px var(--dbo-logs-line); overflow: hidden; }
  .dbo-logs-head, .dbo-logs-row { display: grid; grid-template-columns: 104px 54px 86px minmax(0, 1fr); gap: 10px; align-items: center; padding: 0 12px; }
  .dbo-logs-head { height: 28px; flex: none; font: 600 10px var(--dbo-logs-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-logs-faint); border-bottom: 1px solid var(--dbo-logs-line); }
  .dbo-logs-scroll { position: relative; flex: 1; min-height: 0; overflow: auto; outline: none; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--dbo-logs-line-2) transparent; }
  .dbo-logs-scroll:focus-visible { box-shadow: inset 0 0 0 2px var(--dbo-logs-accent); }
  .dbo-logs-spacer { position: relative; width: 100%; }
  .dbo-logs-progress { position: sticky; top: 0; z-index: 2; display: none; height: 2px; margin-bottom: -2px; background: var(--dbo-logs-accent); transform-origin: left; opacity: 0.7; }
