  .dbo-logs-trace:hover { background: color-mix(in oklch, var(--dbo-logs-accent) 10%, transparent); }
  .dbo-logs-live-region { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

  /* ---------- responsive ---------- */
