    .dbo-logs-side { display: flex; align-items: center; gap: 6px; overflow-x: auto; overflow-y: hidden; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbo-logs-line); scrollbar-width: none; }
    .dbo-logs-brand { padding: 0 6px 0 0; }
