    .dbo-logs-facet { margin: 0; flex: none; }
    .dbo-logs-facet ul { display: flex; gap: 4px; }
    .dbo-logs-facet label { grid-template-columns: 13px auto auto; padding: 3px 8px; box-shadow: inset 0 0 0 1px var(--dbo-logs-line); }
    .dbo-logs-facet s { display: none; }
    .dbo-logs-top { flex-wrap: wrap; padding: 10px 12px 6px; }
    .dbo-logs-search { flex: 1 1 100%; }
    .dbo-logs-hist { padding: 0 12px 6px; }
    .dbo-logs-listwrap { margin: 0 12px 12px; }
