  const page = Math.max(1, Math.floor(scroller.clientHeight / RH) - 1);
  if (e.key === 'ArrowDown') i = i < 0 ? Math.floor(scroller.scrollTop / RH) : Math.min(VIS.length - 1, i + 1);
  else if (e.key === 'ArrowUp') i = i < 0 ? Math.floor(scroller.scrollTop / RH) : Math.max(0, i - 1);
  else if (e.key === 'PageDown') i = Math.min(VIS.length - 1, Math.max(0, i) + page);
  else if (e.key === 'PageUp') i = Math.max(0, i - page);
  else if (e.key === 'Home') i = 0;
  else if (e.key === 'End') i = VIS.length - 1;
  else if (e.key === 'Enter') { if (st.sel) openDrawer(); e.preventDefault(); return; }
  else if (e.key === 'Escape') { if (!drawer.hidden) closeDrawer(); else if (st.brush) setBrush(null); return; }
  else return;
  e.preventDefault();
  st.sel = VIS[i].id;
  const y = i * RH;
  if (y < scroller.scrollTop) scroller.scrollTop = y;
  else if (y + RH > scroller.scrollTop + scroller.clientHeight) scroller.scrollTop = y + RH - scroller.clientHeight;
  paintRows();
  if (!drawer.hidden) openDrawer();
});

/* ---------- detail drawer ---------- */
function openDrawer() {
  const l = LINES.find(x => x.id === st.sel); if (!l) return;
  const fields = { svc: l.svc, host: l.host, level: LV[l.lv].toLowerCase(), ...l.f };
  const tok = (k, v) => `${k}:${/\s/.test(String(v)) ? '"' + v + '"' : v}`;
  drawer.innerHTML = `<div class="dbo-logs-dh" data-l="${l.lv}"><span class="dbo-logs-lv">${LV[l.lv]}</span><time>${new Date(l.t).toISOString().replace('T', ' ').slice(0, 23)} UTC</time>
    <button class="dbo-logs-x" type="button" aria-label="Close details"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>
    <p class="dbo-logs-dmsg">${esc(l.msg)}</p>
    <dl class="dbo-logs-fields">${Object.entries(fields).map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd><span><button type="button" data-tok="${esc(tok(k, v))}" aria-label="Only lines where ${esc(k)} is ${esc(v)}">+</button><button type="button" data-tok="-${esc(tok(k, v))}" aria-label="Exclude lines where ${esc(k)} is ${esc(v)}">−</button></span></div>`).join('')}</dl>
    ${l.f.trace_id ? `<button class="dbo-logs-trace" type="button" data-trace="${l.f.trace_id}">Show the ${LINES.filter(x => x.f.trace_id === l.f.trace_id).length} lines in this trace</button>` : ''}`;
  drawer.hidden = false;
}
function closeDrawer() { drawer.hidden = true; scroller.focus(); }
drawer.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (b.classList.contains('dbo-logs-x')) { closeDrawer(); return; }
  if (b.dataset.trace) { setQuery('trace_id:' + b.dataset.trace); if (st.live) setLive(false, true); return; }
  if (b.dataset.tok) { const k = b.dataset.tok.replace(/^-/, '').split(':')[0]; if (k === 'level') { setQuery(input.value + ' ' + b.dataset.tok); } else setQuery((input.value.trim() + ' ' + b.dataset.tok).trim()); }
});
drawer.addEventListener('keydown', e => { if (e.key === 'Escape') { e.stopPropagation(); closeDrawer(); } });

/* ---------- search, range, live ---------- */
const form = $('.dbo-logs-search'), input = $('input', form), rx = $('.dbo-logs-regex'), live = $('.dbo-logs-live'), lr = $('.dbo-logs-live-region');
let sayT = 0;
const say = msg => { clearTimeout(sayT); sayT = setTimeout(() => { lr.textContent = msg; }, 350); };
function applyQuery() {
  Q = parse(input.value, st.regex);
  form.toggleAttribute('data-bad', !!Q.err);
  $('[data-qerr]').textContent = Q.err || '';
  recompute(false);
  say(`${VIS.length} lines match`);
}
function setQuery(q) { input.value = q.trim().replace(/\s+/g, ' '); applyQuery(); }
let qT = 0;
input.addEventListener('input', () => { clearTimeout(qT); qT = setTimeout(applyQuery, 140); });
form.addEventListener('submit', e => { e.preventDefault(); clearTimeout(qT); applyQuery(); });
input.addEventListener('keydown', e => { if (e.key === 'Escape') { if (input.value) setQuery(''); else scroller.focus(); } });
rx.addEventListener('click', () => { st.regex = !st.regex; rx.setAttribute('aria-pressed', String(st.regex)); applyQuery(); });
root.addEventListener('keydown', e => {
  if (e.key === '/' && !e.target.closest('input, textarea')) { e.preventDefault(); input.focus(); input.select(); }
});
const ranges = $$('.dbo-logs-seg button');
ranges.forEach((b, i) => {
  const pickR = f => { ranges.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); if (f) b.focus(); st.range = +b.dataset.r; st.brush = null; $('[data-clear]').hidden = true; recompute(false); };
  b.addEventListener('click', () => pickR(false));
  b.addEventListener('keydown', e => { const d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0; if (!d) return; e.preventDefault(); ranges[(i + d + ranges.length) % ranges.length].click(); ranges[(i + d + ranges.length) % ranges.length].focus(); });
});
function setLive(on, quiet) {
  st.live = on; st.pausedAt = on ? null : clock();
  live.setAttribute('aria-pressed', String(on));
  $('span', live).textContent = on ? 'Live' : 'Paused';
  if (on) { st.brush = null; $('[data-clear]').hidden = true; catchUp(); recompute(false); }
  if (!quiet) say(on ? 'Live tail resumed' : 'Live tail paused');
}
live.addEventListener('click', () => setLive(!st.live));

/* ---------- live tail ---------- */
function catchUp() {
  const t = clock();
  if (t - genUntil < 50) return 0;
  const from = Math.max(genUntil, t - 120000), fresh = genSpan(from, t, []);
  genUntil = t;
  LINES.push(...fresh);
  if (LINES.length > CAP) LINES.splice(0, LINES.length - CAP);
  return fresh.length;
}
function tick() {
  if (!root.isConnected) return;
  if (st.live && st.visible && !document.hidden) {
    const follow = atBottom();
    const before = VIS.length, n = catchUp();
    if (n) {
      recompute(true);
      const added = VIS.length - before;
      if (!follow && added > 0) { pending += added; jump.hidden = false; $('[data-pending]').textContent = `${pending} new line${pending === 1 ? '' : 's'}`; }
    }
  }
  setTimeout(tick, 650);
}

/* ---------- lifecycle ---------- */
readColors(); sizeCanvas();
root.setAttribute('data-enter', ''); setTimeout(() => root.removeAttribute('data-enter'), 1400);
recompute(false);
if (!reduce) {
  const t0 = performance.now();
  const grow = now => {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - t0) / 800);
    drawHist(1 - Math.pow(1 - p, 3));
    if (p < 1) requestAnimationFrame(grow);
  };
  requestAnimationFrame(grow);
}
setTimeout(tick, 650);
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } sizeCanvas(); drawHist(1); paintRows(); });
ro.observe(hwrap); ro.observe(scroller);
const io = new IntersectionObserver(es => { if (!root.isConnected) { io.disconnect(); return; } st.visible = es[0].isIntersecting; root.toggleAttribute('data-paused', !st.visible); });
io.observe(root);

css:
@keyframes dbo-cluster-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dbo-cluster-bar { from { transform: scaleX(0); } }
@keyframes dbo-cluster-crash { 0%, 100% { box-shadow: inset 0 0 0 1.5px var(--dbo-cluster-hot); } 50% { box-shadow: inset 0 0 0 1.5px transparent; } }

.dbo-cluster {
  /* re-theme with these four; namespace colours below follow the same lightness */
  --dbo-cluster-bg: oklch(0.966 0.006 100);
  --dbo-cluster-ink: oklch(0.26 0.015 120);
  --dbo-cluster-accent: oklch(0.58 0.15 45);
  --dbo-cluster-hot: oklch(0.58 0.2 25);
  --dbo-cluster-ns-checkout: oklch(0.74 0.1 250);
  --dbo-cluster-ns-search: oklch(0.76 0.11 160);
  --dbo-cluster-ns-ingest: oklch(0.8 0.12 85);
  --dbo-cluster-ns-observability: oklch(0.74 0.1 320);
  --dbo-cluster-ns-kube-system: oklch(0.74 0.025 250);
  /* derived */
  --dbo-cluster-card: color-mix(in oklch, var(--dbo-cluster-bg), white 75%);
  --dbo-cluster-wash: color-mix(in oklch, var(--dbo-cluster-bg), var(--dbo-cluster-ink) 4%);
  --dbo-cluster-line: color-mix(in oklch, var(--dbo-cluster-ink) 11%, transparent);
  --dbo-cluster-line-2: color-mix(in oklch, var(--dbo-cluster-ink) 20%, transparent);
  --dbo-cluster-muted: color-mix(in oklch, var(--dbo-cluster-ink) 62%, var(--dbo-cluster-bg));
  --dbo-cluster-faint: color-mix(in oklch, var(--dbo-cluster-ink) 42%, var(--dbo-cluster-bg));
  --dbo-cluster-ease: cubic-bezier(0.2, 0.9, 0.25, 1);
  --dbo-cluster-mono: ui-monospace, "SF Mono", Menlo, monospace;

  width: 100%;
  height: var(--dbo-cluster-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-cluster-bg);
  color: var(--dbo-cluster-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: light;
  accent-color: var(--dbo-cluster-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-cluster-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & select { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-cluster-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbo-cluster-eyebrow { font: 600 10.5px/1.2 var(--dbo-cluster-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-cluster-faint); }

  [data-ns="checkout"] { --nc: var(--dbo-cluster-ns-checkout); }
  [data-ns="search"] { --nc: var(--dbo-cluster-ns-search); }
  [data-ns="ingest"] { --nc: var(--dbo-cluster-ns-ingest); }
  [data-ns="observability"] { --nc: var(--dbo-cluster-ns-observability); }
  [data-ns="kube-system"] { --nc: var(--dbo-cluster-ns-kube-system); }

  .dbo-cluster-app {
    display: grid; height: 100%;
    grid-template-columns: 64px minmax(0, 1fr);
    grid-template-rows: auto auto minmax(0, 1fr);
    grid-template-areas: "rail top" "rail legend" "rail main";
  }

  /* ---------- rail ---------- */
  .dbo-cluster-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 14px; padding: 14px 0; border-right: 1px solid var(--dbo-cluster-line); background: var(--dbo-cluster-wash); }
  .dbo-cluster-logo svg { width: 34px; height: 34px; padding: 6px; border-radius: 10px; fill: none; stroke: var(--dbo-cluster-bg); stroke-width: 1.7; stroke-linejoin: round; background: var(--dbo-cluster-ink); }
  .dbo-cluster-rail [role="tablist"] { display: grid; gap: 4px; }
  .dbo-cluster-rail [role="tab"] { position: relative; width: 44px; height: 44px; display: grid; place-items: center; border-radius: 10px; color: var(--dbo-cluster-muted); transition: background-color 150ms, color 150ms; }
  .dbo-cluster-rail [role="tab"] span { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .dbo-cluster-rail [role="tab"] svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  .dbo-cluster-rail [role="tab"]:hover { color: var(--dbo-cluster-ink); background: color-mix(in oklch, var(--dbo-cluster-ink) 6%, transparent); }
  .dbo-cluster-rail [role="tab"][aria-selected="true"] { color: var(--dbo-cluster-accent); background: var(--dbo-cluster-card); box-shadow: 0 0 0 1px var(--dbo-cluster-line), 0 1px 3px color-mix(in oklch, var(--dbo-cluster-ink) 10%, transparent); }
  .dbo-cluster-rail [role="tab"][aria-selected="true"]::before { content: ""; position: absolute; left: -10px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dbo-cluster-accent); }

  /* ---------- top ---------- */
  .dbo-cluster-top { grid-area: top; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding: 14px 18px 8px; }
  .dbo-cluster-title { display: grid; gap: 2px; }
  .dbo-cluster-title h2 { font: 700 clamp(19px, 0.9rem + 0.9cqi, 24px)/1.1 var(--dbo-cluster-mono); letter-spacing: -0.04em; }
  .dbo-cluster-sum { display: flex; gap: 18px; margin: 0 0 0 auto; }
  .dbo-cluster-sum div { display: grid; gap: 1px; }
  .dbo-cluster-sum dt { font: 600 10px var(--dbo-cluster-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-cluster-faint); }
  .dbo-cluster-sum dd { margin: 0; font: 650 15px var(--dbo-cluster-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  .dbo-cluster-sum dd small { font-size: 11px; font-weight: 500; color: var(--dbo-cluster-muted); letter-spacing: 0; }
  .dbo-cluster-sum [data-hot] { color: var(--dbo-cluster-hot); }
  .dbo-cluster-tools { margin-left: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
  .dbo-cluster-seg { display: inline-flex; padding: 3px; gap: 2px; border-radius: 9px; background: color-mix(in oklch, var(--dbo-cluster-ink) 7%, transparent); }
  .dbo-cluster-seg button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--dbo-cluster-muted); }
  .dbo-cluster-seg button[aria-checked="true"] { color: var(--dbo-cluster-ink); background: var(--dbo-cluster-card); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbo-cluster-ink) 16%, transparent); }
  .dbo-cluster-sort { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--dbo-cluster-muted); }
  .dbo-cluster-sort select { height: 32px; padding: 0 8px; border-radius: 8px; border: 0; background: var(--dbo-cluster-card); box-shadow: inset 0 0 0 1px var(--dbo-cluster-line-2); font-size: 12px; font-weight: 600; }
  .dbo-cluster-add { display: inline-flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px 0 9px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--dbo-cluster-bg); background: var(--dbo-cluster-ink); transition: background-color 150ms, opacity 150ms; }
  .dbo-cluster-add:hover { background: color-mix(in oklch, var(--dbo-cluster-ink), var(--dbo-cluster-accent) 30%); }
  .dbo-cluster-add:disabled { opacity: 0.4; cursor: not-allowed; }
  .dbo-cluster-add svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; }

  .dbo-cluster-legend { grid-area: legend; display: flex; flex-wrap: wrap; align-items: center; gap: 8px 18px; padding: 0 18px 12px; }
  .dbo-cluster-nschips { display: flex; flex-wrap: wrap; gap: 6px; }
  .dbo-cluster-legend button { display: inline-flex; align-items: center; gap: 7px; height: 26px; padding: 0 10px 0 8px; border-radius: 99px; font: 500 11.5px var(--dbo-cluster-mono); color: var(--dbo-cluster-muted); box-shadow: inset 0 0 0 1px var(--dbo-cluster-line); transition: color 150ms, background-color 150ms, box-shadow 150ms; }
  .dbo-cluster-legend button i { width: 10px; height: 10px; border-radius: 3px; background: var(--nc); }
  .dbo-cluster-legend button em { font-style: normal; color: var(--dbo-cluster-faint); }
  .dbo-cluster-legend button:hover { color: var(--dbo-cluster-ink); }
  .dbo-cluster-legend button[aria-pressed="true"] { color: var(--dbo-cluster-ink); background: color-mix(in oklch, var(--nc) 22%, var(--dbo-cluster-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--nc) 70%, var(--dbo-cluster-ink)); }

  /* ---------- main ---------- */
  .dbo-cluster-main { grid-area: main; min-height: 0; overflow: auto; padding: 0 18px 18px; scrollbar-width: thin; scrollbar-color: var(--dbo-cluster-line-2) transparent; }
  .dbo-cluster-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 228px), 1fr)); gap: 12px; }
  .dbo-cluster-node {
    display: flex; flex-direction: column; gap: 8px; padding: 11px 12px 10px; border-radius: 12px; background: var(--dbo-cluster-card);
    box-shadow: 0 0 0 1px var(--dbo-cluster-line), 0 1px 2px color-mix(in oklch, var(--dbo-cluster-ink) 6%, transparent);
    transition: box-shadow 200ms, background-color 200ms;
    animation: dbo-cluster-rise 520ms var(--dbo-cluster-ease) both; animation-delay: calc(var(--i) * 50ms);
  }
  &[data-settled] .dbo-cluster-node { animation: none; }
  .dbo-cluster-node[data-cordon] { background: repeating-linear-gradient(135deg, var(--dbo-cluster-card) 0 8px, var(--dbo-cluster-wash) 8px 16px); box-shadow: 0 0 0 1px var(--dbo-cluster-line-2); }
  .dbo-cluster-nh { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px; align-items: center; }
  .dbo-cluster-nh b { font: 650 12px var(--dbo-cluster-mono); letter-spacing: -0.03em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-cluster-nh small { grid-column: 1; font: 10.5px var(--dbo-cluster-mono); color: var(--dbo-cluster-faint); }
  .dbo-cluster-state { grid-row: 1 / 3; grid-column: 2; display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: 5px; font: 650 10.5px var(--dbo-cluster-mono); color: oklch(0.5 0.12 150); background: color-mix(in oklch, oklch(0.6 0.12 150) 12%, transparent); }
  .dbo-cluster-state i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  .dbo-cluster-node[data-cordon] .dbo-cluster-state { color: var(--dbo-cluster-accent); background: color-mix(in oklch, var(--dbo-cluster-accent) 12%, transparent); }
  .dbo-cluster-bars { display: grid; gap: 3px; }
  .dbo-cluster-bars div { display: grid; grid-template-columns: 28px minmax(0, 1fr) 96px; gap: 6px; align-items: center; font: 10.5px var(--dbo-cluster-mono); color: var(--dbo-cluster-muted); font-variant-numeric: tabular-nums; }
  .dbo-cluster-bars div span:last-child { text-align: right; }
  .dbo-cluster-bars s { height: 5px; border-radius: 3px; background: color-mix(in oklch, var(--dbo-cluster-ink) 9%, transparent); overflow: hidden; text-decoration: none; }
  .dbo-cluster-bars s::before { content: ""; display: block; height: 100%; width: calc(var(--p) * 100%); border-radius: inherit; background: var(--dbo-cluster-ink); transform-origin: left; transition: width 600ms var(--dbo-cluster-ease), background-color 300ms; }
  .dbo-cluster-bars div[data-hi] s::before { background: var(--dbo-cluster-accent); }
  &:not([data-settled]) .dbo-cluster-bars s::before { animation: dbo-cluster-bar 700ms var(--dbo-cluster-ease) both; animation-delay: calc(var(--i) * 50ms + 200ms); }
  .dbo-cluster-bin { position: relative; height: 132px; border-radius: 7px; background: repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in oklch, var(--dbo-cluster-ink) 6%, transparent) 5px 6px), var(--dbo-cluster-wash); outline: none; }
  .dbo-cluster-bin:focus-visible { box-shadow: 0 0 0 2px var(--dbo-cluster-accent); }
  .dbo-cluster-free { position: absolute; display: grid; place-items: center; font: 600 10px var(--dbo-cluster-mono); color: var(--dbo-cluster-faint); pointer-events: none; text-align: center; line-height: 1.2; }
  .dbo-cluster-pod {
    position: absolute; padding: 1px; transform-origin: 0 0; cursor: pointer; outline: none;
  }
  .dbo-cluster-pod > span {
    display: flex; align-items: flex-start; height: 100%; overflow: hidden; padding: 3px 5px; border-radius: 4px;
    font: 600 9.5px/1.15 var(--dbo-cluster-mono); letter-spacing: -0.02em; color: color-mix(in oklch, var(--nc) 25%, black);
    background: var(--nc); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--nc), black 12%);
    transition: opacity 200ms, filter 200ms, box-shadow 160ms;
  }
  .dbo-cluster-pod[data-ds] > span { background: repeating-linear-gradient(135deg, var(--nc) 0 3px, color-mix(in oklch, var(--nc), white 35%) 3px 6px); }
  .dbo-cluster-pod[data-small] > span { color: transparent; }
  .dbo-cluster-pod:hover > span, .dbo-cluster-pod:focus-visible > span { box-shadow: inset 0 0 0 2px var(--dbo-cluster-ink); }
  .dbo-cluster-pod[aria-selected="true"] > span { box-shadow: inset 0 0 0 2px var(--dbo-cluster-ink), 0 0 0 2px var(--dbo-cluster-card); }
  .dbo-cluster-pod[data-crash] > span { animation: dbo-cluster-crash 1.6s steps(2) infinite; }
  .dbo-cluster-pod[data-dim] > span { opacity: 0.22; filter: saturate(0.3); }
  &[data-moving] .dbo-cluster-pod > span { color: transparent; }
  .dbo-cluster-nf { display: flex; gap: 6px; align-items: center; justify-content: space-between; }
  .dbo-cluster-nf small { font: 10.5px var(--dbo-cluster-mono); color: var(--dbo-cluster-faint); }
  .dbo-cluster-nf button { height: 26px; padding: 0 10px; border-radius: 7px; font-size: 11.5px; font-weight: 650; color: var(--dbo-cluster-muted); box-shadow: inset 0 0 0 1px var(--dbo-cluster-line-2); transition: color 150ms, background-color 150ms; }
  .dbo-cluster-nf button:hover { color: var(--dbo-cluster-ink); background: color-mix(in oklch, var(--dbo-cluster-ink) 5%, transparent); }
  .dbo-cluster-nf button[data-act="uncordon"] { color: var(--dbo-cluster-accent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-cluster-accent) 50%, transparent); }

  /* pending */
