      $('[data-v]', row).textContent = `${Math.round(a / b * 100)}% · ${r === 'cpu' ? cores(b - a) : gib(b - a).replace(' GiB', 'G')} free`;
    });
    const mine = PODS.filter(p => p.node === n.id).sort((a, b) => val(b, st.res) - val(a, st.res) || a.name.localeCompare(b.name));
    $('[data-count]', el).textContent = `${mine.length} pods`;
    const act = $('[data-act]', el);
    act.dataset.act = n.cordon ? 'uncordon' : 'drain';
    act.textContent = n.cordon ? 'Uncordon' : 'Drain';
    act.setAttribute('aria-label', `${n.cordon ? 'Uncordon' : 'Drain'} ${n.name}`);
    const bw = bin.clientWidth || 220, bh = bin.clientHeight || 132, cap = val(n, st.res);
    const free = cap - mine.reduce((a, p) => a + val(p, st.res), 0);
    const items = [...mine.map(p => ({ id: p.id, v: val(p, st.res) })), { id: 'free', v: Math.max(0, free) }].map(x => ({ ...x, v: x.v / cap * bw * bh }));
    const rects = squarify(items.sort((a, b) => b.v - a.v), bw, bh);
    let fe = freeEls.get(n.id);
    if (!fe) { fe = document.createElement('div'); fe.className = 'dbo-cluster-free'; freeEls.set(n.id, fe); }
    if (fe.parentElement !== bin) bin.appendChild(fe);
    fe.hidden = true;
    rects.forEach(r => {
      const pos = `left:${(r.x / bw * 100).toFixed(3)}%;top:${(r.y / bh * 100).toFixed(3)}%;width:${(r.w / bw * 100).toFixed(3)}%;height:${(r.h / bh * 100).toFixed(3)}%`;
      if (r.id === 'free') { fe.hidden = false; fe.style.cssText = pos; fe.textContent = r.w > 60 && r.h > 26 ? `${fmtRes(free, st.res)} free` : ''; return; }
      const p = PODS.find(x => x.id === r.id), pe = podEl(p);
      if (pe.parentElement !== bin) bin.appendChild(pe);
      pe.style.cssText = pos;
      pe.toggleAttribute('data-small', r.w < 54 || r.h < 20);
      pe.firstChild.textContent = r.h > 34 && r.w > 70 ? `${p.wl.name} ${fmtRes(val(p, st.res), st.res)}` : p.wl.name;
    });
  });
  const pend = PODS.filter(p => !p.node).sort(bySize);
  pend.forEach(p => { const pe = podEl(p); pe.style.cssText = ''; pe.removeAttribute('data-small'); pe.firstChild.textContent = `${p.wl.name} · ${p.short || 'pending'}`; tray.appendChild(pe); });
  $('[data-pendnote]').textContent = pend.length ? pend[0].reason : '';
  $('[data-pendcount]').textContent = pend.length;
  paintSummary(); paintLegend(); paintWorkloads();
}
function paintSummary() {
  const run = PODS.filter(p => p.node).length, pend = PODS.length - run;
  const ac = NODES.reduce((a, n) => a + n.cpu, 0), am = NODES.reduce((a, n) => a + n.mem, 0);
  const rc = PODS.filter(p => p.node).reduce((a, p) => a + p.cpu, 0), rm = PODS.filter(p => p.node).reduce((a, p) => a + p.mem, 0);
  const cord = NODES.filter(n => n.cordon).length;
  $('.dbo-cluster-sum').innerHTML = `<div><dt>Nodes</dt><dd>${NODES.length}${cord ? ` <small>· ${cord} cordoned</small>` : ''}</dd></div>
    <div><dt>Pods</dt><dd>${run} <small>running</small>${pend ? ` <small>·</small> <span data-hot>${pend}</span> <small>pending</small>` : ''}</dd></div>
    <div><dt>CPU requested</dt><dd>${Math.round(rc / ac * 100)}% <small>of ${cores(ac)}</small></dd></div>
    <div><dt>Memory requested</dt><dd>${Math.round(rm / am * 100)}% <small>of ${gib(am)}</small></dd></div>`;
  $('.dbo-cluster-add').disabled = NODES.filter(n => n.pool === 'general').length >= 6;
}
function paintLegend() {
  const leg = $('.dbo-cluster-nschips');
  leg.innerHTML = NS.map(ns => `<button type="button" data-ns="${ns}" aria-pressed="${!!st.hl && st.hl.type === 'ns' && st.hl.key === ns}"><i></i>${ns}<em>${PODS.filter(p => p.ns === ns).length}</em></button>`).join('') +
    (st.hl && st.hl.type === 'wl' ? `<button type="button" data-ns="${WL.find(w => w.name === st.hl.key).ns}" data-clearwl aria-pressed="true"><i></i>${st.hl.key} ✕</button>` : '');
}

/* ---------- FLIP: pods move between bins and the pending tray ---------- */
function flip(mutate) {
  const first = new Map();
  podEls.forEach((el, id) => { if (el.isConnected) first.set(id, el.getBoundingClientRect()); });
  mutate();
  if (reduce) return;
  root.setAttribute('data-moving', '');
  let k = 0;
  podEls.forEach((el, id) => {
    const a = first.get(id), b = el.getBoundingClientRect();
    if (!b.width) return;
    if (!a) { el.animate([{ opacity: 0, transform: 'scale(0.4)' }, { opacity: 1, transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.9,.25,1)' }); return; }
    const dx = a.left - b.left, dy = a.top - b.top, sx = a.width / b.width, sy = a.height / b.height;
    if (Math.abs(dx) < 0.5 && Math.abs(dy) < 0.5 && Math.abs(sx - 1) < 0.01 && Math.abs(sy - 1) < 0.01) return;
    const far = Math.hypot(dx, dy) > 140;
    el.animate([{ transform: `translate(${dx}px, ${dy}px) scale(${sx}, ${sy})` }, { transform: 'none' }],
      { duration: far ? 760 : 560, delay: far ? (k++ % 12) * 28 : 0, easing: 'cubic-bezier(.2,.9,.25,1)', fill: 'backwards' });
  });
  clearTimeout(flip.t); flip.t = setTimeout(() => root.removeAttribute('data-moving'), 1100);
}

/* ---------- actions ---------- */
function drain(n) {
  flip(() => {
    n.cordon = true;
    const t = now();
    const evicted = PODS.filter(p => p.node === n.id && !p.ds);
    evicted.forEach(p => { p.node = null; p.name = `${p.wl.name}-${p.wl.hash}-${sfx(5)}`; p.born = t; p.restarts = 0; p.crash = false; p.events = [{ t, kind: 'Evicted', msg: `Replaced pod evicted from ${n.name} by drain`, warn: true }]; p.use = { cpu: p.cpu * 0.4, mem: p.mem * 0.5 }; });
    const queue = PODS.filter(p => !p.node).sort(bySize);
    queue.forEach(schedule);
    layoutAll();
    const pend = PODS.filter(p => !p.node).length;
    live.textContent = `Drained ${n.name}: ${evicted.length} pods rescheduled${pend ? `, ${pend} pending` : ''}.`;
  });
}
function uncordon(n) {
  flip(() => {
    n.cordon = false;
    PODS.filter(p => !p.node).sort(bySize).forEach(schedule);
    layoutAll();
    live.textContent = `${n.name} is schedulable again.`;
  });
}
function addGeneral() {
  flip(() => {
    const n = addNode('general');
    const ds = mkPod(WL.find(w => w.ds), true); ds.node = n.id; ds.born = now();
    ds.events.push({ t: now(), kind: 'Scheduled', msg: `Successfully assigned ${ds.ns}/${ds.name} to ${n.name}` });
    PODS.filter(p => !p.node).sort(bySize).forEach(schedule);
    layoutAll(); sortCards(false);
    live.textContent = `Added ${n.name}.`;
  });
}
grid.addEventListener('click', e => {
  const b = e.target.closest('[data-act]');
  if (b) { const n = NODES.find(x => x.id === b.closest('.dbo-cluster-node').dataset.id); b.dataset.act === 'drain' ? drain(n) : uncordon(n); return; }
  const pe = e.target.closest('.dbo-cluster-pod'); if (pe) openPod(pe.dataset.id);
});
tray.addEventListener('click', e => { const pe = e.target.closest('.dbo-cluster-pod'); if (pe) openPod(pe.dataset.id); });
$('.dbo-cluster-add').addEventListener('click', addGeneral);

/* ---------- keyboard inside a bin ---------- */
root.addEventListener('keydown', e => {
  const bin = e.target.closest('.dbo-cluster-bin, .dbo-cluster-tray');
  if (e.key === 'Escape') { if (!drawer.hidden) closeDrawer(); else if (st.hl) { st.hl = null; refreshDim(); } hideTip(); return; }
  if (!bin) return;
  const pods = $$('.dbo-cluster-pod', bin).sort((a, b) => { const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect(); return ra.top - rb.top || ra.left - rb.left; });
  const i = pods.indexOf(e.target.closest('.dbo-cluster-pod'));
  if ((e.key === 'Enter' || e.key === ' ') && i >= 0) { e.preventDefault(); openPod(pods[i].dataset.id); return; }
  const d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : e.key === 'ArrowLeft' || e.key === 'ArrowUp' ? -1 : 0;
  if (!d || !pods.length) return;
  e.preventDefault();
  const nx = pods[i < 0 ? (d > 0 ? 0 : pods.length - 1) : (i + d + pods.length) % pods.length];
  nx.focus(); showTip(nx);
});

/* ---------- tooltip ---------- */
function showTip(pe) {
  const p = PODS.find(x => x.id === pe.dataset.id); if (!p) return;
  const node = NODES.find(n => n.id === p.node);
  tip.innerHTML = `<b>${p.name}</b>${cores(p.cpu)} CPU · ${gib(p.mem)} requested<br>${node ? 'on ' + node.name : 'Pending · ' + (p.short || '')}${p.restarts ? ` · ${p.restarts} restarts` : ''}`;
  tip.setAttribute('data-on', '');
  const R = root.getBoundingClientRect(), b = pe.getBoundingClientRect(), tw = tip.offsetWidth, th = tip.offsetHeight;
  let x = b.left - R.left + b.width / 2 - tw / 2, y = b.top - R.top - th - 8;
  if (y < 6) y = b.bottom - R.top + 8;
  tip.style.transform = `translate(${Math.max(6, Math.min(R.width - tw - 6, x))}px, ${y}px)`;
}
const hideTip = () => tip.removeAttribute('data-on');
root.addEventListener('pointerover', e => { const pe = e.target.closest('.dbo-cluster-pod'); if (pe && !root.hasAttribute('data-moving')) showTip(pe); });
root.addEventListener('pointerout', e => { if (e.target.closest('.dbo-cluster-pod') && !e.relatedTarget?.closest?.('.dbo-cluster-pod')) hideTip(); });

/* ---------- drawer ---------- */
function gauge(label, use, req, lim, fmt) {
  return `<div><h5>${label}<span>${fmt(use)} used</span></h5><div class="dbo-cluster-gauge" ${use / lim > 0.95 ? 'data-over' : ''} style="--u:${Math.min(1, use / lim).toFixed(3)};--r:${(req / lim).toFixed(3)}"><b></b><i></i></div>
    <div class="dbo-cluster-glabel"><span>request ${fmt(req)}</span><span>limit ${fmt(lim)}</span></div></div>`;
}
function openPod(id) {
  st.sel = id;
  const p = PODS.find(x => x.id === id), node = NODES.find(n => n.id === p.node);
  const status = !node ? 'Pending' : p.crash ? 'CrashLoopBackOff' : 'Running';
  const limCpu = p.cpu * 2, limMem = p.mem;
  drawer.innerHTML = `<div class="dbo-cluster-dh"><h4>${p.name}</h4><button class="dbo-cluster-x" type="button" aria-label="Close pod details"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>
    <div class="dbo-cluster-chips"><span class="dbo-cluster-chip" data-ns="${p.ns}">${p.ns}</span><span class="dbo-cluster-chip" data-st="${status}">${status}</span><span class="dbo-cluster-chip">${p.ds ? 'DaemonSet' : 'Deployment'}</span><span class="dbo-cluster-chip">Burstable</span></div>
    <div class="dbo-cluster-res">${node ? gauge('CPU', p.use.cpu, p.cpu, limCpu, v => cores(v)) + gauge('Memory', p.use.mem, p.mem, limMem, gib) : `<p class="dbo-cluster-glabel" style="justify-content:flex-start">Requests ${cores(p.cpu)} CPU and ${gib(p.mem)}; nothing is running yet.</p>`}</div>
    <dl class="dbo-cluster-kv"><dt>Node</dt><dd>${node ? node.name : '—'}</dd><dt>Workload</dt><dd>${p.wl.name}</dd>
      <dt>Selector</dt><dd>${p.wl.pool ? 'pool=' + p.wl.pool : 'none'}</dd><dt>Tolerates</dt><dd>${p.wl.tol || '—'}</dd>
      <dt>Restarts</dt><dd>${p.restarts}${p.crash ? ' · last OOMKilled' : ''}</dd><dt>Age</dt><dd>${ago(p.born)}</dd></dl>
    <ol class="dbo-cluster-events">${[...p.events].reverse().map(ev => `<li ${ev.warn ? 'data-warn' : ''}><time>${ago(ev.t)}</time><b>${ev.kind}</b><p>${ev.msg}</p></li>`).join('')}</ol>`;
  drawer.hidden = false;
  refreshDim();
  $('.dbo-cluster-x', drawer).focus();
}
function closeDrawer() {
  const id = st.sel; st.sel = null; drawer.hidden = true; refreshDim();
  const pe = id && podEls.get(id); if (pe && pe.isConnected) pe.focus();
}
drawer.addEventListener('click', e => { if (e.target.closest('.dbo-cluster-x')) closeDrawer(); });
function refreshDim() { PODS.forEach(podEl); paintLegend(); }

/* ---------- legend + workloads ---------- */
$('.dbo-cluster-nschips').addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  if (b.hasAttribute('data-clearwl')) st.hl = null;
  else st.hl = st.hl && st.hl.type === 'ns' && st.hl.key === b.dataset.ns ? null : { type: 'ns', key: b.dataset.ns };
  refreshDim();
});
const tbody = $('.dbo-cluster-table tbody');
function paintWorkloads() {
  tbody.innerHTML = WL.map((w, i) => {
    const pods = PODS.filter(p => p.wl === w), ready = pods.filter(p => p.node).length, want = w.ds ? NODES.length : w.n;
    const on = new Set(pods.filter(p => p.node).map(p => p.node));
    return `<tr tabindex="${i ? -1 : 0}" data-wl="${w.name}"><td><span class="dbo-cluster-wn" data-ns="${w.ns}"><i></i>${w.name}</span></td><td>${w.ns}</td>
      <td><span class="dbo-cluster-ready" ${ready < want ? 'data-short' : ''}>${ready}/${want}</span></td><td class="dbo-cluster-num">${cores(w.cpu * want)}</td><td class="dbo-cluster-num">${gib(w.mem * want)}</td>
      <td><span class="dbo-cluster-dots" aria-label="on ${on.size} of ${NODES.length} nodes">${NODES.map(n => `<i ${on.has(n.id) ? 'data-on' : ''}></i>`).join('')}</span></td></tr>`;
  }).join('');
}
tbody.addEventListener('click', e => { const r = e.target.closest('tr'); if (r) showWorkload(r.dataset.wl); });
tbody.addEventListener('keydown', e => {
  const r = e.target.closest('tr'); if (!r) return;
  if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); showWorkload(r.dataset.wl); return; }
  const rows = $$('tr', tbody), i = rows.indexOf(r), d = e.key === 'ArrowDown' ? 1 : e.key === 'ArrowUp' ? -1 : 0;
  if (!d) return; e.preventDefault();
  const n = rows[Math.max(0, Math.min(rows.length - 1, i + d))]; rows.forEach(x => { x.tabIndex = x === n ? 0 : -1; }); n.focus();
});
function showWorkload(name) { st.hl = { type: 'wl', key: name }; showView('cap'); refreshDim(); live.textContent = `Highlighting ${name}`; }

/* ---------- views, resource toggle, sort ---------- */
const tabs = $$('[role="tab"]');
function showView(v, focus) {
  st.view = v;
  tabs.forEach(t => { const on = t.dataset.view === v; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
  $$('[role="tabpanel"]').forEach(p => { p.hidden = p.dataset.panel !== v; });
  hideTip();
  if (v === 'cap') layoutAll();
}
tabs.forEach((t, i) => {
  t.addEventListener('click', () => showView(t.dataset.view));
  t.addEventListener('keydown', e => { const d = ['ArrowDown', 'ArrowRight'].includes(e.key) ? 1 : ['ArrowUp', 'ArrowLeft'].includes(e.key) ? -1 : 0; if (!d) return; e.preventDefault(); showView(tabs[(i + d + tabs.length) % tabs.length].dataset.view, true); });
});
const resBtns = $$('.dbo-cluster-seg button');
resBtns.forEach((b, i) => {
  const pick = f => { if (st.res === b.dataset.res) return; resBtns.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; }); if (f) b.focus(); st.res = b.dataset.res; root.dataset.res = st.res; flip(layoutAll); };
  b.addEventListener('click', () => pick(false));
  b.addEventListener('keydown', e => { const d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0; if (!d) return; e.preventDefault(); resBtns[(i + d + resBtns.length) % resBtns.length].click(); resBtns[(i + d + resBtns.length) % resBtns.length].focus(); });
});
function sortCards(animate) {
  const key = n => st.sort === 'alloc' ? -used(n)[st.res] / n[st.res] : st.sort === 'pool' ? ['general', 'highmem', 'batch'].indexOf(n.pool) * 100 + NODES.indexOf(n) : NODES.indexOf(n);
  const order = [...NODES].sort((a, b) => key(a) - key(b));
  const first = animate && !reduce ? new Map(order.map(n => [n.id, cards.get(n.id).getBoundingClientRect()])) : null;
  order.forEach(n => grid.appendChild(cards.get(n.id)));
  if (first) order.forEach((n, k) => {
    const el = cards.get(n.id), a = first.get(n.id), b = el.getBoundingClientRect();
    const dx = a.left - b.left, dy = a.top - b.top;
    if (Math.abs(dx) + Math.abs(dy) > 1) el.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: 'none' }], { duration: 620, delay: k * 25, easing: 'cubic-bezier(.2,.9,.25,1)', fill: 'backwards' });
  });
}
$('.dbo-cluster-sort select').addEventListener('change', e => { st.sort = e.target.value; sortCards(true); });

/* ---------- lifecycle ---------- */
layoutAll();
requestAnimationFrame(() => { if (!root.isConnected) return; layoutAll(); });
setTimeout(() => { if (root.isConnected) root.setAttribute('data-settled', ''); }, 1400);
let rw = grid.clientWidth;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (Math.abs(grid.clientWidth - rw) < 1) return;
  rw = grid.clientWidth; layoutAll();
});
ro.observe(grid);

css:
@keyframes dbo-pipeline-rise { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbo-pipeline-grow { from { transform: scaleY(0); } }
@keyframes dbo-pipeline-wipe { from { transform: scaleX(0); } }
@keyframes dbo-pipeline-dash { to { stroke-dashoffset: -16; } }
@keyframes dbo-pipeline-stripes { to { background-position: 16px 0; } }
@keyframes dbo-pipeline-spin { to { rotate: 360deg; } }

.dbo-pipeline {
  /* re-theme with these five */
  --dbo-pipeline-bg: oklch(0.195 0.022 262);
  --dbo-pipeline-ink: oklch(0.94 0.012 250);
  --dbo-pipeline-accent: oklch(0.81 0.15 68);
  --dbo-pipeline-ok: oklch(0.8 0.12 158);
  --dbo-pipeline-bad: oklch(0.69 0.18 24);
  /* derived */
  --dbo-pipeline-run: oklch(0.78 0.09 235);
  --dbo-pipeline-panel: color-mix(in oklch, var(--dbo-pipeline-bg), white 4%);
  --dbo-pipeline-raise: color-mix(in oklch, var(--dbo-pipeline-bg), white 8.5%);
  --dbo-pipeline-sink: color-mix(in oklch, var(--dbo-pipeline-bg), black 25%);
  --dbo-pipeline-line: color-mix(in oklch, var(--dbo-pipeline-ink) 10%, transparent);
  --dbo-pipeline-line-2: color-mix(in oklch, var(--dbo-pipeline-ink) 18%, transparent);
  --dbo-pipeline-muted: color-mix(in oklch, var(--dbo-pipeline-ink) 60%, var(--dbo-pipeline-bg));
  --dbo-pipeline-faint: color-mix(in oklch, var(--dbo-pipeline-ink) 38%, var(--dbo-pipeline-bg));
  --dbo-pipeline-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbo-pipeline-mono: ui-monospace, "SF Mono", Menlo, monospace;

  width: 100%;
  height: var(--dbo-pipeline-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-pipeline-bg);
  color: var(--dbo-pipeline-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: dark;
  accent-color: var(--dbo-pipeline-accent);
  box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & select { font: inherit; color: inherit; }
  & button { background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-pipeline-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & kbd { font: 600 10px var(--dbo-pipeline-mono); padding: 1px 5px; border-radius: 4px; background: color-mix(in oklch, var(--dbo-pipeline-ink) 10%, transparent); color: var(--dbo-pipeline-ink); }

  [data-s="success"] { --sc: var(--dbo-pipeline-ok); }
  [data-s="failed"] { --sc: var(--dbo-pipeline-bad); }
  [data-s="running"] { --sc: var(--dbo-pipeline-run); }
  [data-s="queued"], [data-s="skipped"] { --sc: var(--dbo-pipeline-faint); }

  .dbo-pipeline-app { display: grid; height: 100%; grid-template-columns: 290px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- runs ---------- */
  .dbo-pipeline-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; background: var(--dbo-pipeline-sink); border-right: 1px solid var(--dbo-pipeline-line); }
  .dbo-pipeline-brand { display: flex; align-items: center; gap: 10px; padding: 16px 16px 12px; }
  .dbo-pipeline-brand svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; fill: none; stroke: var(--dbo-pipeline-bg); stroke-width: 1.8; stroke-linecap: round; background: var(--dbo-pipeline-accent); flex: none; }
  .dbo-pipeline-brand span { display: grid; line-height: 1.2; min-width: 0; }
  .dbo-pipeline-brand b { font: 650 12.5px var(--dbo-pipeline-mono); letter-spacing: -0.03em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-pipeline-brand small { font-size: 11px; color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-filters { display: flex; gap: 6px; padding: 0 12px 10px; }
  .dbo-pipeline-seg { display: inline-flex; gap: 2px; padding: 3px; border-radius: 8px; background: color-mix(in oklch, var(--dbo-pipeline-ink) 6%, transparent); }
  .dbo-pipeline-seg button { height: 24px; padding: 0 9px; border-radius: 6px; font: 600 11.5px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-seg button:hover { color: var(--dbo-pipeline-ink); }
  .dbo-pipeline-seg button[aria-checked="true"] { color: var(--dbo-pipeline-ink); background: var(--dbo-pipeline-raise); }
  .dbo-pipeline-sort { margin-left: auto; height: 30px; padding: 0 6px; border: 0; border-radius: 8px; background: color-mix(in oklch, var(--dbo-pipeline-ink) 6%, transparent); font-size: 12px; }
  .dbo-pipeline-runs { flex: 1; min-height: 0; overflow: auto; padding: 0 8px 10px; outline: none; scrollbar-width: thin; scrollbar-color: var(--dbo-pipeline-line-2) transparent; }
  .dbo-pipeline-runs:focus-visible { box-shadow: inset 0 0 0 2px var(--dbo-pipeline-accent); border-radius: 8px; }
  .dbo-pipeline-run {
    display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; gap: 2px 9px; align-items: center; padding: 8px 8px 9px; border-radius: 9px; cursor: pointer;
    transition: background-color 120ms; animation: dbo-pipeline-rise 420ms var(--dbo-pipeline-ease) both; animation-delay: calc(var(--i) * 22ms);
  }
  &[data-settled] .dbo-pipeline-run { animation: none; }
  .dbo-pipeline-run:hover { background: color-mix(in oklch, var(--dbo-pipeline-ink) 5%, transparent); }
  .dbo-pipeline-run[aria-selected="true"] { background: var(--dbo-pipeline-raise); box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2); }
  .dbo-pipeline-run[data-active] { box-shadow: inset 0 0 0 2px var(--dbo-pipeline-accent); }
  .dbo-pipeline-ico { width: 16px; height: 16px; color: var(--sc); }
  .dbo-pipeline-ico svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  [data-s="running"] > .dbo-pipeline-ico svg { animation: dbo-pipeline-spin 1.4s linear infinite; }
  .dbo-pipeline-run b { font: 600 12px var(--dbo-pipeline-mono); display: flex; gap: 6px; align-items: baseline; min-width: 0; }
  .dbo-pipeline-run b em { font-style: normal; font-weight: 500; color: var(--dbo-pipeline-accent); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-pipeline-run b em[data-main] { color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-run time { font: 500 11.5px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); font-variant-numeric: tabular-nums; text-align: right; }
  .dbo-pipeline-run[data-s="failed"] time { color: var(--dbo-pipeline-bad); }
  .dbo-pipeline-run p { grid-column: 2 / -1; font-size: 11.5px; color: var(--dbo-pipeline-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-pipeline-mini { grid-column: 2 / -1; display: flex; gap: 1px; height: 4px; margin-top: 3px; border-radius: 2px; overflow: hidden; }
  .dbo-pipeline-mini i { flex: var(--f) 1 0; background: color-mix(in oklch, var(--dbo-pipeline-ink) calc(14% + var(--k) * 9%), transparent); }
  .dbo-pipeline-run[data-s="failed"] .dbo-pipeline-mini i:last-child { background: var(--dbo-pipeline-bad); }
  .dbo-pipeline-run[data-s="running"] .dbo-pipeline-mini { background: repeating-linear-gradient(90deg, color-mix(in oklch, var(--dbo-pipeline-run) 40%, transparent) 0 6px, transparent 6px 10px); background-size: 16px 4px; animation: dbo-pipeline-stripes 600ms linear infinite; }

  /* ---------- main ---------- */
  .dbo-pipeline-main { grid-area: main; min-height: 0; overflow: auto; padding: 16px 18px 16px; display: flex; flex-direction: column; gap: 12px; scrollbar-width: thin; scrollbar-color: var(--dbo-pipeline-line-2) transparent; }
  .dbo-pipeline-head { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 18px; align-items: end; }
  .dbo-pipeline-head .dbo-pipeline-eyebrow { font: 600 10.5px var(--dbo-pipeline-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-pipeline-faint); display: flex; gap: 8px; align-items: center; }
  .dbo-pipeline-pill { display: inline-flex; align-items: center; gap: 5px; height: 20px; padding: 0 7px; border-radius: 5px; font: 700 10px var(--dbo-pipeline-mono); letter-spacing: 0.06em; color: var(--sc); background: color-mix(in oklch, var(--sc) 15%, transparent); }
  .dbo-pipeline-head h2 { font-size: clamp(17px, 0.85rem + 0.9cqi, 22px); font-weight: 650; letter-spacing: -0.02em; line-height: 1.2; grid-column: 1; }
  .dbo-pipeline-head p { grid-column: 1; font: 11.5px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-totals { grid-column: 2; grid-row: 1 / 4; display: flex; gap: 18px; text-align: right; }
  .dbo-pipeline-totals div { display: grid; gap: 1px; }
  .dbo-pipeline-totals span { font: 600 10px var(--dbo-pipeline-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-pipeline-faint); }
  .dbo-pipeline-totals b { font: 600 clamp(20px, 0.9rem + 1.2cqi, 27px)/1.05 var(--dbo-pipeline-mono); letter-spacing: -0.05em; font-variant-numeric: tabular-nums; }
  .dbo-pipeline-totals b[data-crit] { color: var(--dbo-pipeline-accent); }
  .dbo-pipeline-totals small { font: 11px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-ok); }

  .dbo-pipeline-whatif { display: flex; align-items: center; gap: 10px; padding: 8px 8px 8px 12px; border-radius: 10px; background: color-mix(in oklch, var(--dbo-pipeline-accent) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-pipeline-accent) 35%, transparent); transition: opacity 200ms, translate 260ms var(--dbo-pipeline-ease); @starting-style { opacity: 0; translate: 0 -6px; } }
  .dbo-pipeline-whatif svg { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--dbo-pipeline-accent); stroke-width: 1.8; stroke-linejoin: round; }
  .dbo-pipeline-whatif p { flex: 1; font-size: 12.5px; }
  .dbo-pipeline-whatif b { font-weight: 650; color: var(--dbo-pipeline-accent); font-variant-numeric: tabular-nums; }
  .dbo-pipeline-whatif button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2); }
  .dbo-pipeline-whatif button:hover { background: color-mix(in oklch, var(--dbo-pipeline-ink) 8%, transparent); }

  .dbo-pipeline-panel { min-width: 0; border-radius: 12px; background: var(--dbo-pipeline-panel); box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line); }
  .dbo-pipeline-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding: 10px 12px 4px; }
  .dbo-pipeline-ph h3 { font-size: 12.5px; font-weight: 650; }
  .dbo-pipeline-stat { font: 11px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); display: inline-flex; align-items: center; gap: 6px; }
  .dbo-pipeline-stat::before { content: ""; width: 14px; height: 0; border-top: 1.5px dashed var(--c, var(--dbo-pipeline-muted)); }
  .dbo-pipeline-stat[data-p90] { --c: var(--dbo-pipeline-accent); }
  .dbo-pipeline-n { margin-left: auto; }

  .dbo-pipeline-trend { position: relative; height: 104px; margin: 0 10px 8px; outline: none; cursor: pointer; }
  .dbo-pipeline-trend:focus-visible { box-shadow: 0 0 0 2px var(--dbo-pipeline-accent); border-radius: 6px; }
  .dbo-pipeline-trend svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  .dbo-pipeline-gl { stroke: var(--dbo-pipeline-line); }
  .dbo-pipeline-ax { font: 10px var(--dbo-pipeline-mono); fill: var(--dbo-pipeline-faint); font-variant-numeric: tabular-nums; }
  .dbo-pipeline-bar { fill: color-mix(in oklch, var(--sc) 70%, transparent); transform-box: fill-box; transform-origin: 50% 100%; transition: fill 150ms; }
  .dbo-pipeline-bar[data-s="success"] { fill: color-mix(in oklch, var(--dbo-pipeline-ink) 30%, transparent); }
  .dbo-pipeline-bar[data-on] { fill: var(--dbo-pipeline-ink); }
  .dbo-pipeline-bar[data-s="failed"][data-on] { fill: var(--dbo-pipeline-bad); }
  .dbo-pipeline-bar[data-hot] { fill: color-mix(in oklch, var(--dbo-pipeline-ink) 70%, transparent); }
  .dbo-pipeline-trend[data-anim] .dbo-pipeline-bar { animation: dbo-pipeline-grow 600ms var(--dbo-pipeline-ease) both; animation-delay: calc(var(--i) * 14ms); }
  .dbo-pipeline-pl { stroke-width: 1.25; stroke-dasharray: 4 3; }
  .dbo-pipeline-pl[data-k="50"] { stroke: var(--dbo-pipeline-muted); }
  .dbo-pipeline-pl[data-k="90"] { stroke: var(--dbo-pipeline-accent); }
  .dbo-pipeline-ttip { position: absolute; top: 0; left: 0; z-index: 3; padding: 7px 9px; border-radius: 8px; pointer-events: none; white-space: nowrap; background: var(--dbo-pipeline-sink); box-shadow: 0 0 0 1px var(--dbo-pipeline-line-2), 0 10px 24px oklch(0 0 0 / 0.4); font: 11px/1.5 var(--dbo-pipeline-mono); opacity: 0; transition: opacity 100ms; }
  .dbo-pipeline-ttip[data-on] { opacity: 1; }
  .dbo-pipeline-ttip b { color: var(--sc, var(--dbo-pipeline-ink)); }

  .dbo-pipeline-viewpanel { flex: 1 0 auto; display: flex; flex-direction: column; min-height: 330px; }
  .dbo-pipeline-tabs { display: flex; gap: 2px; }
  .dbo-pipeline-tabs button { height: 28px; padding: 0 12px; border-radius: 7px; font-size: 12.5px; font-weight: 650; color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-tabs button[aria-selected="true"] { color: var(--dbo-pipeline-ink); background: var(--dbo-pipeline-raise); }
  .dbo-pipeline-legend { display: flex; gap: 12px; font: 11px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-legend li { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-pipeline-legend i { width: 16px; height: 3px; border-radius: 2px; background: var(--dbo-pipeline-accent); box-shadow: 0 0 8px color-mix(in oklch, var(--dbo-pipeline-accent) 70%, transparent); }
  .dbo-pipeline-legend i[data-k="cache"] { width: 10px; height: 10px; border-radius: 3px; box-shadow: none; background: none; border: 1.5px dashed var(--dbo-pipeline-accent); }
  .dbo-pipeline-hint { margin-left: auto; font-size: 11.5px; color: var(--dbo-pipeline-faint); }
  .dbo-pipeline-views { position: relative; flex: 1; min-height: 0; display: flex; }
  .dbo-pipeline-graph, .dbo-pipeline-time { flex: 1; min-width: 0; overflow: auto; padding: 6px 12px 12px; scrollbar-width: thin; scrollbar-color: var(--dbo-pipeline-line-2) transparent; }

  /* graph */
  .dbo-pipeline-canvas { position: relative; min-width: 760px; }
  .dbo-pipeline-edges { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
  .dbo-pipeline-stage { font: 600 10px var(--dbo-pipeline-mono); letter-spacing: 0.1em; text-transform: uppercase; fill: var(--dbo-pipeline-faint); }
  .dbo-pipeline-e { fill: none; stroke: var(--dbo-pipeline-line-2); stroke-width: 1.25; transition: stroke 200ms, stroke-width 200ms, opacity 200ms; }
  .dbo-pipeline-e[data-crit] { stroke: var(--dbo-pipeline-accent); stroke-width: 2; filter: drop-shadow(0 0 4px color-mix(in oklch, var(--dbo-pipeline-accent) 60%, transparent)); }
  .dbo-pipeline-e[data-crit][data-run] { stroke-dasharray: 5 3; animation: dbo-pipeline-dash 900ms linear infinite; }
  .dbo-pipeline-e[data-skip] { stroke-dasharray: 2 4; opacity: 0.5; }
  .dbo-pipeline-canvas:has(.dbo-pipeline-node:hover) .dbo-pipeline-e:not([data-hot]) { opacity: 0.35; }
  .dbo-pipeline-e[data-hot] { stroke: var(--dbo-pipeline-ink); }
  .dbo-pipeline-node {
    position: absolute; width: var(--w); height: 40px; display: grid; grid-template-columns: 16px minmax(0, 1fr); grid-template-rows: auto auto; align-content: center; gap: 0 8px; padding: 0 10px 0 9px;
    border-radius: 9px; text-align: left; background: var(--dbo-pipeline-raise); box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2);
    transition: box-shadow 180ms, background-color 180ms, opacity 200ms, translate 200ms var(--dbo-pipeline-ease);
  }
  .dbo-pipeline-node:hover { translate: 0 -1px; background: color-mix(in oklch, var(--dbo-pipeline-raise), white 4%); }
  .dbo-pipeline-node .dbo-pipeline-ico { grid-row: 1 / 3; align-self: center; }
  .dbo-pipeline-node b { font: 600 10.5px/1.25 var(--dbo-pipeline-mono); letter-spacing: -0.035em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-pipeline-node time { font: 500 10.5px/1.2 var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); font-variant-numeric: tabular-nums; }
  .dbo-pipeline-node[data-crit] { box-shadow: inset 0 0 0 1.5px var(--dbo-pipeline-accent), 0 0 18px -6px var(--dbo-pipeline-accent); }
  .dbo-pipeline-node[data-crit] time { color: var(--dbo-pipeline-accent); }
  .dbo-pipeline-node[data-s="skipped"], .dbo-pipeline-node[data-s="queued"] { opacity: 0.5; background: none; box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2); }
  .dbo-pipeline-node[data-s="failed"] { background: color-mix(in oklch, var(--dbo-pipeline-bad) 14%, var(--dbo-pipeline-raise)); }
  .dbo-pipeline-node[data-cached] { background: color-mix(in oklch, var(--dbo-pipeline-accent) 10%, var(--dbo-pipeline-raise)); outline: 1.5px dashed var(--dbo-pipeline-accent); outline-offset: 2px; }
  .dbo-pipeline-node[aria-pressed="true"] { background: color-mix(in oklch, var(--dbo-pipeline-ink) 14%, var(--dbo-pipeline-raise)); }
  .dbo-pipeline-node[data-s="running"]::after { content: ""; position: absolute; left: 6px; right: 6px; bottom: 3px; height: 2px; border-radius: 1px; background: linear-gradient(90deg, var(--dbo-pipeline-run) calc(var(--p) * 100%), color-mix(in oklch, var(--dbo-pipeline-ink) 12%, transparent) 0); }
  .dbo-pipeline-graph[data-anim] .dbo-pipeline-node { animation: dbo-pipeline-rise 460ms var(--dbo-pipeline-ease) both; animation-delay: calc(var(--c) * 90ms + var(--r) * 30ms); }

  /* gantt */
  .dbo-pipeline-gantt { display: grid; grid-template-columns: 128px minmax(0, 1fr); align-items: center; row-gap: 3px; }
  .dbo-pipeline-gaxis { grid-column: 2; position: relative; height: 18px; border-bottom: 1px solid var(--dbo-pipeline-line); }
  .dbo-pipeline-gaxis span { position: absolute; bottom: 3px; translate: -50% 0; font: 10px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-faint); font-variant-numeric: tabular-nums; }
  .dbo-pipeline-gl2 { position: absolute; top: 0; bottom: 0; width: 1px; background: var(--dbo-pipeline-line); }
  .dbo-pipeline-glabel { font: 500 11px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding-right: 8px; cursor: pointer; }
  .dbo-pipeline-glabel[data-crit] { color: var(--dbo-pipeline-accent); }
  .dbo-pipeline-track { position: relative; height: 20px; cursor: pointer; }
  .dbo-pipeline-track::before { content: ""; position: absolute; inset: 9px 0; background: var(--dbo-pipeline-line); }
  .dbo-pipeline-gq { position: absolute; top: 9px; height: 2px; left: var(--q0); width: var(--qw); background: var(--dbo-pipeline-line-2); }
  .dbo-pipeline-gb { position: absolute; top: 3px; height: 14px; left: var(--x0); width: max(3px, var(--xw)); border-radius: 4px; background: color-mix(in oklch, var(--sc) 55%, var(--dbo-pipeline-panel)); transform-origin: left; transition: left 500ms var(--dbo-pipeline-ease), width 500ms var(--dbo-pipeline-ease), background-color 200ms; }
  .dbo-pipeline-gb[data-s="success"] { background: color-mix(in oklch, var(--dbo-pipeline-ink) 34%, var(--dbo-pipeline-panel)); }
  .dbo-pipeline-gb[data-crit] { background: var(--dbo-pipeline-accent); box-shadow: 0 0 12px -2px color-mix(in oklch, var(--dbo-pipeline-accent) 70%, transparent); }
  .dbo-pipeline-gb[data-cached] { outline: 1.5px dashed var(--dbo-pipeline-accent); outline-offset: 1px; }
  .dbo-pipeline-gb[data-s="running"] { background: repeating-linear-gradient(135deg, var(--dbo-pipeline-run) 0 5px, color-mix(in oklch, var(--dbo-pipeline-run) 60%, var(--dbo-pipeline-panel)) 5px 10px); background-size: 14px 14px; animation: dbo-pipeline-stripes 700ms linear infinite; }
  .dbo-pipeline-gb[data-s="skipped"], .dbo-pipeline-gb[data-s="queued"] { background: none; box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2); }
  .dbo-pipeline-time[data-anim] .dbo-pipeline-gb { animation: dbo-pipeline-wipe 600ms var(--dbo-pipeline-ease) both; animation-delay: calc(var(--i) * 30ms); }
  .dbo-pipeline-track:hover .dbo-pipeline-gb, .dbo-pipeline-track[data-sel] .dbo-pipeline-gb { box-shadow: 0 0 0 2px var(--dbo-pipeline-ink); }
  .dbo-pipeline-now { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--dbo-pipeline-run); box-shadow: 0 0 8px var(--dbo-pipeline-run); pointer-events: none; }

  /* job drawer */
  .dbo-pipeline-job {
    position: absolute; top: 0; right: 0; bottom: 0; z-index: 4; width: min(320px, 100%); overflow: auto; padding: 12px 14px 14px; border-radius: 0 12px 12px 0;
    background: var(--dbo-pipeline-panel); box-shadow: -1px 0 0 var(--dbo-pipeline-line-2), -16px 0 30px oklch(0 0 0 / 0.35);
    transition: translate 300ms var(--dbo-pipeline-ease), opacity 200ms; @starting-style { translate: 20px 0; opacity: 0; }
    scrollbar-width: thin;
  }
  .dbo-pipeline-jh { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
  .dbo-pipeline-jh h3 { font: 650 14px var(--dbo-pipeline-mono); letter-spacing: -0.03em; flex: 1; overflow-wrap: anywhere; }
  .dbo-pipeline-x { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 7px; color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-x:hover { color: var(--dbo-pipeline-ink); background: color-mix(in oklch, var(--dbo-pipeline-ink) 8%, transparent); }
  .dbo-pipeline-x svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  .dbo-pipeline-kv { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 5px 14px; margin: 0 0 12px; font: 11.5px var(--dbo-pipeline-mono); }
  .dbo-pipeline-kv dt { color: var(--dbo-pipeline-faint); }
  .dbo-pipeline-kv dd { margin: 0; font-variant-numeric: tabular-nums; }
  .dbo-pipeline-kv dd[data-crit] { color: var(--dbo-pipeline-accent); }
  .dbo-pipeline-cache { width: 100%; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; text-align: left; font-size: 12.5px; box-shadow: inset 0 0 0 1px var(--dbo-pipeline-line-2); transition: background-color 150ms, box-shadow 150ms; }
  .dbo-pipeline-cache i { position: relative; width: 30px; height: 18px; flex: none; border-radius: 99px; background: color-mix(in oklch, var(--dbo-pipeline-ink) 18%, transparent); transition: background-color 200ms; }
  .dbo-pipeline-cache i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--dbo-pipeline-ink); transition: translate 260ms linear(0, 0.5 18%, 0.92 36%, 1.06 52%, 1.01 72%, 1); }
  .dbo-pipeline-cache[aria-checked="true"] { background: color-mix(in oklch, var(--dbo-pipeline-accent) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbo-pipeline-accent) 45%, transparent); }
  .dbo-pipeline-cache[aria-checked="true"] i { background: var(--dbo-pipeline-accent); }
  .dbo-pipeline-cache[aria-checked="true"] i::after { translate: 12px 0; background: var(--dbo-pipeline-bg); }
  .dbo-pipeline-cache small { display: block; font-size: 11px; color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-log { margin: 12px 0 0; padding: 10px 11px; border-radius: 8px; background: var(--dbo-pipeline-sink); font: 11px/1.55 var(--dbo-pipeline-mono); white-space: pre-wrap; overflow-wrap: anywhere; color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-log b { color: var(--dbo-pipeline-bad); font-weight: 600; }
  .dbo-pipeline-deps { margin-top: 10px; font: 11px var(--dbo-pipeline-mono); color: var(--dbo-pipeline-muted); }
  .dbo-pipeline-deps b { color: var(--dbo-pipeline-ink); font-weight: 600; }
  .dbo-pipeline-live { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

  /* ---------- responsive ---------- */
  @container (max-width: 960px) {
    .dbo-pipeline-app { grid-template-columns: 248px minmax(0, 1fr); }
    .dbo-pipeline-hint { display: none; }
  }
  @container (max-width: 760px) {
    .dbo-pipeline-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
    .dbo-pipeline-side { border-right: 0; border-bottom: 1px solid var(--dbo-pipeline-line); }
    .dbo-pipeline-brand { padding: 10px 12px 8px; }
    .dbo-pipeline-runs { display: flex; gap: 6px; overflow-x: auto; overflow-y: hidden; padding: 0 12px 10px; scrollbar-width: none; flex: none; }
    .dbo-pipeline-run { flex: none; width: 210px; }
