css:
@property --dbo-canary-score { syntax: "<number>"; inherits: true; initial-value: 0; }
@property --dbo-canary-n { syntax: "<integer>"; inherits: true; initial-value: 0; }
@keyframes dbo-canary-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbo-canary-reveal { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dbo-canary-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }

.dbo-canary {
  /* re-theme with these five */
  --dbo-canary-bg: oklch(0.975 0.008 95);
  --dbo-canary-ink: oklch(0.24 0.02 75);
  --dbo-canary-accent: oklch(0.85 0.16 92);
  --dbo-canary-pass: oklch(0.56 0.12 155);
  --dbo-canary-fail: oklch(0.58 0.19 28);
  /* derived */
  --dbo-canary-gold: color-mix(in oklch, var(--dbo-canary-accent), var(--dbo-canary-ink) 42%);
  --dbo-canary-base: oklch(0.56 0.025 250);
  --dbo-canary-card: color-mix(in oklch, var(--dbo-canary-bg), white 70%);
  --dbo-canary-wash: color-mix(in oklch, var(--dbo-canary-bg), var(--dbo-canary-ink) 4%);
  --dbo-canary-line: color-mix(in oklch, var(--dbo-canary-ink) 11%, transparent);
  --dbo-canary-line-2: color-mix(in oklch, var(--dbo-canary-ink) 20%, transparent);
  --dbo-canary-muted: color-mix(in oklch, var(--dbo-canary-ink) 62%, var(--dbo-canary-bg));
  --dbo-canary-faint: color-mix(in oklch, var(--dbo-canary-ink) 42%, var(--dbo-canary-bg));
  --dbo-canary-marg: oklch(0.72 0.14 65);
  --dbo-canary-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --dbo-canary-mono: ui-monospace, "SF Mono", Menlo, monospace;

  width: 100%;
  height: var(--dbo-canary-h, 680px);
  container-type: inline-size;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dbo-canary-bg);
  color: var(--dbo-canary-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: light;
  accent-color: var(--dbo-canary-gold);
  box-shadow: inset 0 0 0 1px var(--dbo-canary-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbo-canary-gold); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dbo-canary-eyebrow { font: 600 10.5px/1.2 var(--dbo-canary-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-canary-faint); }
  [data-v="pass"], [data-v="low"] { --vc: var(--dbo-canary-pass); }
  [data-v="high"] { --vc: var(--dbo-canary-fail); }
  [data-v="nodata"] { --vc: var(--dbo-canary-faint); }

  .dbo-canary-app { display: grid; height: 100%; grid-template-columns: 232px minmax(0, 1fr); grid-template-areas: "side main"; }

  /* ---------- side ---------- */
  .dbo-canary-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 18px 12px 14px; border-right: 1px solid var(--dbo-canary-line); background: var(--dbo-canary-wash); }
  .dbo-canary-brand { display: flex; align-items: center; gap: 10px; padding: 0 6px 12px; }
  .dbo-canary-brand svg { width: 32px; height: 32px; padding: 5px; border-radius: 50%; fill: var(--dbo-canary-accent); stroke: var(--dbo-canary-ink); stroke-width: 1.4; stroke-linejoin: round; background: var(--dbo-canary-ink); }
  .dbo-canary-brand svg circle { fill: var(--dbo-canary-ink); stroke: none; }
  .dbo-canary-brand span { display: grid; line-height: 1.15; }
  .dbo-canary-brand b { font-weight: 750; letter-spacing: -0.02em; font-size: 14px; }
  .dbo-canary-brand small { font-size: 11px; color: var(--dbo-canary-muted); }
  .dbo-canary-sidehead { padding: 0 8px; }
  .dbo-canary-rels { display: grid; gap: 3px; }
  .dbo-canary-rel { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 8px; align-items: baseline; padding: 9px 10px; border-radius: 10px; cursor: pointer; outline: none; transition: background-color 150ms, box-shadow 150ms; animation: dbo-canary-rise 480ms var(--dbo-canary-ease) both; animation-delay: calc(var(--i) * 60ms); }
  .dbo-canary-rel:hover { background: color-mix(in oklch, var(--dbo-canary-ink) 5%, transparent); }
  .dbo-canary-rel[aria-selected="true"] { background: var(--dbo-canary-card); box-shadow: 0 0 0 1px var(--dbo-canary-line), 0 1px 3px color-mix(in oklch, var(--dbo-canary-ink) 8%, transparent); }
  .dbo-canary-rel:focus-visible { box-shadow: 0 0 0 2px var(--dbo-canary-gold); }
  .dbo-canary-rel b { font: 650 13px var(--dbo-canary-mono); letter-spacing: -0.03em; }
  .dbo-canary-rel small { grid-column: 1 / -1; font-size: 11.5px; color: var(--dbo-canary-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .dbo-canary-st { font: 700 9.5px/1 var(--dbo-canary-mono); letter-spacing: 0.06em; text-transform: uppercase; padding: 4px 6px; border-radius: 4px; color: var(--dbo-canary-ink); background: var(--dbo-canary-accent); }
  .dbo-canary-st[data-st="rolled back"] { color: var(--dbo-canary-card); background: var(--dbo-canary-fail); }
  .dbo-canary-st[data-st="promoted"] { color: var(--dbo-canary-card); background: var(--dbo-canary-pass); }
  .dbo-canary-st[data-st="analyzing"]::before { content: ""; display: inline-block; width: 5px; height: 5px; margin-right: 5px; border-radius: 50%; background: currentColor; vertical-align: 1px; animation: dbo-canary-pulse 1.4s ease-in-out infinite; }
  .dbo-canary-policy { margin: auto 0 0; padding: 12px 8px 0; border-top: 1px solid var(--dbo-canary-line); display: grid; gap: 7px; }
  .dbo-canary-policy dt { font: 600 10px var(--dbo-canary-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dbo-canary-faint); }
  .dbo-canary-policy dd { margin: 0; font-size: 12px; color: var(--dbo-canary-muted); }

  /* ---------- main ---------- */
  .dbo-canary-main {
    grid-area: main; min-height: 0; overflow: auto; padding: 18px 20px 18px; display: grid; gap: 12px; align-content: start;
    grid-template-columns: 236px minmax(0, 1fr);
    grid-template-areas: "head head" "roll roll" "score metrics";
    scrollbar-width: thin; scrollbar-color: var(--dbo-canary-line-2) transparent;
  }
  .dbo-canary-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: flex-end; gap: 6px 16px; }
  .dbo-canary-head > div { display: grid; gap: 3px; flex: 1 1 320px; min-width: 0; }
  .dbo-canary-head h2 { font-size: clamp(19px, 0.95rem + 1cqi, 26px); font-weight: 750; letter-spacing: -0.035em; line-height: 1.1; }
  .dbo-canary-head h2 em { font-style: normal; font-family: var(--dbo-canary-mono); font-weight: 650; letter-spacing: -0.05em; padding: 0 6px; border-radius: 6px; background: var(--dbo-canary-accent); }
  .dbo-canary-head p { font-size: 12.5px; color: var(--dbo-canary-muted); }
  .dbo-canary-head p code { font: 12px var(--dbo-canary-mono); color: var(--dbo-canary-ink); }
  .dbo-canary-pods { display: flex; gap: 14px; font: 11.5px var(--dbo-canary-mono); color: var(--dbo-canary-muted); }
  .dbo-canary-pods span { display: inline-flex; align-items: center; gap: 6px; }
  .dbo-canary-pods i { width: 14px; height: 3px; border-radius: 2px; background: var(--c); }
  .dbo-canary-pods b { color: var(--dbo-canary-ink); font-weight: 650; }

  .dbo-canary-panel { min-width: 0; border-radius: 14px; background: var(--dbo-canary-card); box-shadow: 0 0 0 1px var(--dbo-canary-line), 0 1px 2px color-mix(in oklch, var(--dbo-canary-ink) 5%, transparent); }
  .dbo-canary-ph { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding: 11px 14px 4px; }
  .dbo-canary-ph h3 { font-size: 12.5px; font-weight: 700; }
  .dbo-canary-clock { font: 600 12px var(--dbo-canary-mono); color: var(--dbo-canary-muted); font-variant-numeric: tabular-nums; }
  .dbo-canary-ctrls { margin-left: auto; display: flex; gap: 6px; }
  .dbo-canary-play, .dbo-canary-now { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 11px 0 8px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbo-canary-line-2); transition: background-color 150ms; }
  .dbo-canary-now { padding: 0 11px; color: var(--dbo-canary-gold); }
  .dbo-canary-play:hover, .dbo-canary-now:hover { background: var(--dbo-canary-wash); }
  .dbo-canary-play svg { width: 15px; height: 15px; fill: currentColor; }
  .dbo-canary-play[aria-pressed="true"] { background: var(--dbo-canary-ink); color: var(--dbo-canary-bg); box-shadow: none; }

  /* rollout track */
  .dbo-canary-roll { grid-area: roll; }
  .dbo-canary-track { position: relative; height: 92px; margin: 2px 14px 12px; cursor: ew-resize; touch-action: none; user-select: none; -webkit-user-select: none; outline: none; }
  .dbo-canary-track:focus-visible { box-shadow: 0 0 0 2px var(--dbo-canary-gold); border-radius: 8px; }
